insert into public.catalog_classes (id,name_pt,name_en,description_pt,hp_per_level,key_attributes,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.cov.prestige.cov-knight-of-the-flying-hunt','Knight of the Flying Hunt','Knight of the Flying Hunt','Race: Human or half-moon elf. Base Attack Bonus: +7. Skills: Handle Animal 8 ranks, Ride 8 ranks. Feats: Favored in Guild (Knights of the Flying Hunt), Mounted Combat, Weapon Focus (lance). Alignment: Lawful good, neutral good, or lawful neutral. Special: Native or permanent resident of Nimbral. Special: Membership in the Knights of the Flying Hunt.',10,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-cov','D&D 3.5 — Champions of Valor',106,'dnd35','{"id":"cov-knight-of-the-flying-hunt","name":"Knight of the Flying Hunt","hitDie":10,"requirements":["Race: Human or half-moon elf.","Base Attack Bonus: +7.","Skills: Handle Animal 8 ranks, Ride 8 ranks.","Feats: Favored in Guild (Knights of the Flying Hunt), Mounted Combat, Weapon Focus (lance).","Alignment: Lawful good, neutral good, or lawful neutral.","Special: Native or permanent resident of Nimbral.","Special: Membership in the Knights of the Flying Hunt."],"classSkills":"Diplomacy, Handle Animal, Intimidate, Jump, Ride, Search, Spot, Swim","skillPointsPerLevel":"2 + Int modifier","levels":[{"level":1,"bab":"+1","fort":"+2","ref":"+0","will":"+2","special":"Armor proficiency, flying hunt armor, pegasus mount"},{"level":2,"bab":"+2","fort":"+3","ref":"+0","will":"+3","special":"Armored ease (2)"},{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+3","special":"—"},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+4","special":"Bonus feat"},{"level":5,"bab":"+5","fort":"+4","ref":"+1","will":"+4","special":"Storm armor"},{"level":6,"bab":"+6","fort":"+5","ref":"+2","will":"+5","special":"—"},{"level":7,"bab":"+7","fort":"+5","ref":"+2","will":"+5","special":"Armored ease (4)"},{"level":8,"bab":"+8","fort":"+6","ref":"+2","will":"+6","special":"Bonus feat"},{"level":9,"bab":"+9","fort":"+6","ref":"+3","will":"+6","special":"—"},{"level":10,"bab":"+10","fort":"+7","ref":"+3","will":"+7","special":"Greater storm armor"}],"classFeaturesText":"As a Knight of the Flying Hunt, you become an expert at mounted combat, utilizing a host of skills and maneuvers to defeat your enemies, while at the same time gaining more powerful enhancements to your special glass armor. \n\n Armor Proficiency: You gain proficiency in light, medium, and heavy armor. \n\n Flying Hunt Armor: At 1st level, you are considered a novice, and you receive a suit of flying hunt armor (see page 65) from the Nimbral Lords. This armor is attuned to you and can never be used by another. If this suit of armor is lost or destroyed, the Nimbral Lords will replace it, though you must pay the gp cost normally required to create the armor. \n\n Pegasus Mount: At 1st level, you receive a trained pegasus to serve you in your defense of Nimbral. The mount remains with you until it is slain or dismissed. It requires food and rest, and you are responsible for tending to its needs. When riding this mount, you gain a competence bonus on Ride checks equal to your class level. If the mount dies, you can have it raised from the dead (at the normal cost) or obtain another mount. You can only obtain a replacement after living and meditating among the trained pegasi of the Knights for one week. \n\n Armored Ease (Ex): You learn to adapt your movements to the restrictive nature of armor. Beginning at 2nd level, you can lessen the armor check penalty of any armor with which you are proficient by 2 (minimum 0). At 7th level, this reduction improves to 4 (minimum 0). \n\n Bonus Feat: At 4th level, and again at 8th level, you gain a bonus feat, which must be selected from the following list: Animal Affinity, Greater Weapon Focus (lance), Greater Weapon Specialization (lance), Ride-By Attack, Skill Focus (Ride), Spirited Charge, Trample, Weapon Specialization (lance). You must meet the normal prerequisites in order to select any of these feats. \n\n Storm Armor: At 5th level, you are considered a full Knight and your flying hunt armor is further enhanced by the Nimbral Lords to become storm armor (see page 69). This armor is attuned to you and can never be used by another. If this suit of armor is lost or destroyed, the Nimbral Lords will replace it, though you must pay the gp cost normally required to create the armor. \n\n Greater Storm Armor: At 10th level, you are recognized by the Knights as an excellent and experienced leader. For your loyal service and outstanding performance, the Nimbral Lords bestow another enhancement upon your storm armor, making it greater storm armor. You can choose any one of the following effects and add it to your armor at no charge: arrow deflection (as the shield special ability); fortification (light); magic missile (3/day, CL 7th); mirror image (1/day; CL 10th); spell resistance 13; or water walk (as a ring of water walking). Alternatively, you can choose a different armor special ability (with a price of up to 30,000 gp or a base price modifier of up to +3 bonus) and add it to your armor at only 75% of the normal market price. Either way, this addition requires the normal amount of time required to improve the item, which likely means that you must turn over your storm armor to the Nimbral Lords for a number of days or weeks. If this suit of armor is lost or destroyed, the Lords will replace it, though you must pay the gp cost normally required to create the armor."}'::jsonb),
('dnd35.cov.prestige.cov-knight-of-the-weave','Knight of the Weave','Knight of the Weave','Alignment: Any non-evil. Base Attack Bonus: +5 or ability to spontaneously cast 3rd-level arcane spells. Skills: Knowledge (arcana) 1 rank, Knowledge (history) 1 rank, Spellcraft 1 rank. Oath to the Weave: A knight must swear to defend the Weave at all costs, sacrificing his own life to preserve it if necessary. Special: Cannot be a Shadow Weave user.',8,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-cov','D&D 3.5 — Champions of Valor',106,'dnd35','{"id":"cov-knight-of-the-weave","name":"Knight of the Weave","hitDie":8,"requirements":["Alignment: Any non-evil.","Base Attack Bonus: +5 or ability to spontaneously cast 3rd-level arcane spells.","Skills: Knowledge (arcana) 1 rank, Knowledge (history) 1 rank, Spellcraft 1 rank.","Oath to the Weave: A knight must swear to defend the Weave at all costs, sacrificing his own life to preserve it if necessary.","Special: Cannot be a Shadow Weave user."],"classSkills":"Concentration, Craft, Diplomacy, Intimidate, Knowledge (arcana), Knowledge (history), Profession, Spellcraft, Spot, Use Magic Device","skillPointsPerLevel":"2 + Int modifier","levels":[{"level":1,"bab":"+0","fort":"+2","ref":"+0","will":"+2","special":"Detect magic, read magic, spellcasting"},{"level":2,"bab":"+1","fort":"+3","ref":"+0","will":"+3","special":"Armored caster (light)"},{"level":3,"bab":"+2","fort":"+3","ref":"+1","will":"+3","special":"—"},{"level":4,"bab":"+3","fort":"+4","ref":"+1","will":"+4","special":"Fast metamagic"},{"level":5,"bab":"+3","fort":"+4","ref":"+1","will":"+4","special":"—"},{"level":6,"bab":"+4","fort":"+5","ref":"+2","will":"+5","special":"Spellfire (healing)"},{"level":7,"bab":"+5","fort":"+5","ref":"+2","will":"+5","special":"—"},{"level":8,"bab":"+6","fort":"+6","ref":"+2","will":"+6","special":"Armored caster (medium)"},{"level":9,"bab":"+6","fort":"+6","ref":"+3","will":"+6","special":"—"},{"level":10,"bab":"+7","fort":"+7","ref":"+3","will":"+7","special":"Spellfire (blasting)"}],"classFeaturesText":"Knights of the Weave cast arcane spells and learn how to tap into the raw power of the Weave. A knight’s caster level for his spell-like abilities is equal to his class level. \n\n Detect Magic (Sp): At 1st level, you gain the ability to use detect magic at will. \n\n Read Magic (Sp): At 1st level, you gain the ability to use read magic at will. \n\n Spellcasting: Knights of the Weave cast arcane spells like a sorcerer (you use your Charisma score to determine bonus spells per day, save DCs, and so on). Refer to Table 4–3 to determine your spells known and spells per day. You incur the normal arcane spell failure chance for wearing armor (but see Armored Caster, below). Your caster level for your knight spells is equal to your knight class level plus any other arcane caster levels you may have. This class’s spellcasting progression allows you to quickly approach the highest-level spells available to a single-class spellcaster of your character level, but you will always know fewer spells and be able to cast fewer spells per day than a single-class spellcaster. \n\n Armored Caster (Ex): Normally, armor of any type interferes with an arcane spellcaster’s gestures, which can cause his spells to fail (if those spells have somatic components). At 2nd level, you become more attuned to the Weave and can cast your arcane spells while wearing light armor without incurring the normal arcane spell failure chance. If you wear medium or heavy armor or carry a shield, you incur an arcane spell failure chance if the spell has a somatic component. At 8th level and higher, you can cast your arcane spells in light or medium armor without incurring arcane spell failure. Casting in heavy armor or with a shield still incurs the normal arcane spell failure chance. \n\n Fast Metamagic (Ex): At 4th level you become able to channel extra magic into an arcane spell to employ metamagic feats more efficiently. When spontaneously casting an arcane spell (such as a sorcerer spell or a knight spell) with one or more metamagic effects applied to it, you can expend an extra spell slot to cast the spell without increasing its casting time (as normal for applying metamagic to a spontaneously cast spell). The extra spell slot must equal or exceed the spell slot used to cast the metamagic-affected spell, but need not be from the same spellcasting class. For example, if you wanted to apply your Silent Spell metamagic feat to a magic missile spell, you would normally cast the spell as a full-round action. If you expended an extra spell slot of 2nd level or higher, you could cast the silent magic missile as a standard action instead. You could even quicken the magic missile spell, but you would have to expend a 5th-level or higher spell slot. This ability doesn’t let you apply a metamagic effect if you don’t already have the appropriate feat. \n\n Spellfire (Su): While you are not a natural user of spellfire, your connection to the Weave gives you a limited ability to channel raw magical energy as if you were born with this talent. You cannot absorb spells targeted at you, nor can you store spellfire energy for later use, but you can use your own arcane spell energy to heal (or later, to blast). Starting at 6th level, you can convert your available arcane spells (from any class) to healing spellfire. You can convert a single arcane spell slot or prepared arcane spell as a standard action to heal a target by touch, restoring 2 hit points per spell level expended for this purpose. At 10th level, you can also convert your arcane spells into spellfire blasts that deal damage. As a standard action, you can convert a single arcane spell slot or prepared arcane spell into a ranged touch attack (maximum range 400 feet), dealing 1d6 points of spellfire damage per spell level expended, Reflex DC 20 half. Spellfire damage is half fire damage and half raw magical power; creatures with immunity or resistance to fire apply this effect only to half the damage. See page 56 of the FORGOTTEN REALMS Campaign Setting for more details on this ability. \n\n Multiclassing: A paladin who takes levels in Knight of the Weave can still take levels in paladin. KNIGHT OF THE WEAVE SPELL LIST Knights of the Weave choose their spells from the following list. 1st Level—bless, bless weapon, charm person, command, comprehend languages, cure light wounds, divine favor, lesser restoration, mage armor, magic missile, magic weapon, read magic, shield. 2nd Level—arcane lock, bear’s endurance, bull’s strength, cat’s grace, darkvision, delay poison, eagle’s splendor, resist energy, see invisibility, shield other. 3rd Level—arcane sight, cure moderate wounds, Darsson’s potionMag, daylight, dispel magic, fly, forcewardMag, greater magic weapon, phantom steed, remove curse. 4th Level—break enchantment, cure serious wounds, death ward, lesser globe of invulnerability, mark of justice, neutralize poison, restoration. 5th Level—cure critical wounds, dimension door, disrupting weapon, Mordenkainen’s faithful hound, spell resistance, true seeing. 6th Level—banishment, greater dispel magic, teleport.","spellsPerDayAndKnown":[[2,null,null,null,null,null],[2,null,null,null,null,null],[3,2,null,null,null,null],[3,2,null,null,null,null],[4,3,2,null,null,null],[4,3,2,2,null,null],[4,4,3,2,2,null],[4,4,3,3,2,2],[4,4,4,3,3,2],[4,4,4,3,3,3]]}'::jsonb),
('dnd35.cov.prestige.cov-moonsea-skysentinel','Moonsea Skysentinel','Moonsea Skysentinel','Base Attack Bonus: +5. Skills: Handle Animal 8 ranks, Ride 8 ranks. Feats: Mounted Combat. Special: Membership in the Knights of the North.',8,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-cov','D&D 3.5 — Champions of Valor',106,'dnd35','{"id":"cov-moonsea-skysentinel","name":"Moonsea Skysentinel","hitDie":8,"requirements":["Base Attack Bonus: +5.","Skills: Handle Animal 8 ranks, Ride 8 ranks.","Feats: Mounted Combat.","Special: Membership in the Knights of the North."],"classSkills":"Climb, Craft, Handle Animal, Intimidate, Jump, Knowledge (geography), Ride, Spot","skillPointsPerLevel":"2 + Int modifier","levels":[{"level":1,"bab":"+1","fort":"+2","ref":"+0","will":"+0","special":"Dire hawk steed, magical defense +1"},{"level":2,"bab":"+2","fort":"+3","ref":"+0","will":"+0","special":"Shield 1/day"},{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+1","special":"Spell turning 1/day"},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+1","special":"Magical defense +2"},{"level":5,"bab":"+5","fort":"+4","ref":"+1","will":"+1","special":"Shield 2/day"},{"level":6,"bab":"+6","fort":"+5","ref":"+2","will":"+2","special":"Spell turning 2/day"},{"level":7,"bab":"+7","fort":"+5","ref":"+2","will":"+2","special":"Magical defense +3"},{"level":8,"bab":"+8","fort":"+6","ref":"+2","will":"+2","special":"Shield 3/day"},{"level":9,"bab":"+9","fort":"+6","ref":"+3","will":"+3","special":"Spell turning 3/day"},{"level":10,"bab":"+10","fort":"+7","ref":"+3","will":"+3","special":"Magical defense +4"}],"classFeaturesText":"The Moonsea skysentinel’s class features make you particularly adept at aerial combat and scouting, while at the same time resistant to magical attacks from your hated foes, the Zhentarim skymages. The combination of offensive specialties and defensive protections make you particularly handy at quick strikes against ground-based foes with little risk to yourself. \n\n Dire Hawk Steed: As a Moonsea skysentinel, you gain a trained dire hawk of Large size as your personal mount. The dire hawk serves you loyally, carrying you into combat or fighting at your side. The dire hawk has maximum hit points but is otherwise a normal specimen of its size. See page 122 for this creature’s statistics block. Your dire hawk steed gains 1 HD for every three class levels you gain beyond 1st (increasing to 10 HD at 4th, to 11 HD at 7th, and to 12 HD at 10th). Each time it gains a Hit Die, its natural armor bonus and Strength score each improve by 2 (in addition to the normal improvements gained with added Hit Dice, such as skill points, feats, and ability score improvements). A dire hawk steed can’t be used as an animal companion. \n\n Magical Defense (Ex): Your training in resisting the deadly spells cast by Zhentarim skymages manifests as a bonus on saving throws against spells and spell-like abilities for both you and your mount. This bonus is +1 starting at 1st level, and it increases to +2 at 4th level, +3 at 7th level, and +4 at 10th level. The ability only functions while you are mounted on your dire hawk steed. \n\n Shield (Sp): Upon reaching 2nd level, you gain an innate ability to withstand incoming attacks from your enemies. Once per day you can use a shield effect. Your caster level is equal to your class level. If you are mounted on your dire hawk, the spell affects both you and your mount, but if you dismount your dire hawk loses the benefit. You can use this ability one additional time per day for every three levels gained above 2nd. \n\n Spell Turning (Sp): Starting at 3rd level, you can use a spell turning effect as an immediate action; the duration is 1 round or until expended. If you are mounted on your dire hawk, the spell affects both you and your mount (and you share a common pool of spell levels affected), but if you dismount your dire hawk loses the benefit. You can use this ability once per day at 3rd level, and one additional time per day for every three levels gained above 3rd."}'::jsonb),
('dnd35.cov.prestige.cov-triadic-knight','Triadic Knight','Triadic Knight','Patron Deity: Ilmater, Torm, and/or Tyr. Alignment: Lawful good. Base Attack Bonus: +5. Feats: Initiate of IlmaterPG, Initiate of Torm (see page 31), or Initiate of TyrPG; plus Endurance. Skills: Knowledge (local) 4 ranks, Knowledge (religion) 4 ranks, Knowledge (the planes) 2 ranks. Special: Aura of good class feature.',10,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-cov','D&D 3.5 — Champions of Valor',106,'dnd35','{"id":"cov-triadic-knight","name":"Triadic Knight","hitDie":10,"requirements":["Patron Deity: Ilmater, Torm, and/or Tyr.","Alignment: Lawful good.","Base Attack Bonus: +5.","Feats: Initiate of IlmaterPG, Initiate of Torm (see page 31), or Initiate of TyrPG; plus Endurance.","Skills: Knowledge (local) 4 ranks, Knowledge (religion) 4 ranks, Knowledge (the planes) 2 ranks.","Special: Aura of good class feature."],"classSkills":"Concentration, Craft, Diplomacy, Handle Animal, Heal, Knowledge (local, nobility and royalty, the planes, religion), Profession, Ride, Sense Motive","skillPointsPerLevel":"2 + Int modifier","levels":[{"level":1,"bab":"+1","fort":"+2","ref":"+0","will":"+0","special":"Aura of good, special mount","advancesSpellcasting":false},{"level":2,"bab":"+2","fort":"+3","ref":"+0","will":"+0","special":"Hands of Ilmater","advancesSpellcasting":true},{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+1","special":"Shield other","advancesSpellcasting":true},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+1","special":"Eyes of Tyr","advancesSpellcasting":true},{"level":5,"bab":"+5","fort":"+4","ref":"+1","will":"+1","special":"Discern lies, smite evil 1/day","advancesSpellcasting":true},{"level":6,"bab":"+6","fort":"+5","ref":"+2","will":"+2","special":"Heart of Torm","advancesSpellcasting":true},{"level":7,"bab":"+7","fort":"+5","ref":"+2","will":"+2","special":"Shout, threefold smite","advancesSpellcasting":false}],"classFeaturesText":"The Triadic knight’s class features combine elements of the paladin with defensive abilities that allow him to remain at full fighting strength even when faced with adverse conditions. \n\n Spellcasting: At each new Triadic knight level other than 1st or 7th, you gain new spells per day and an increase in caster level (and spells known, if applicable) as if you had also gained a level in a divine spellcasting class you belonged to before adding the prestige class. You do not, however, gain all the benefits a character of that class would have gained. If you had more than one divine spellcasting class before becoming a Triadic knight, you must decide to which class you add the new level for purposes of determining spells per day, caster level, and spells known. \n\n Aura of Good (Ex): Your Triadic knight levels stack with other class levels that grant this ability for the purpose of determining the power of your aura of good. \n\n Special Mount (Sp): As a Triadic knight, you gain the service of an unusually intelligent, strong, and loyal steed. See the paladin class feature, page 44 of the Player’s Handbook. Levels of Triadic knight stack with other class levels in classes that grant this feature for the purpose of determining the special mount’s abilities. \n\n Hands of Ilmater (Su): At 2nd level and higher, you can no longer become nauseated or sickened. \n\n Shield Other (Sp): Starting at 3rd level, you can use a shield other effect once per day; your caster level is equal to twice your class level. Triadic knights often call this ability “martyr’s embrace.” \n\n Eyes of Tyr (Su): At 4th level and higher, you can no longer become dazzled or blinded (except by physical damage to your eyes). \n\n Discern Lies (Sp): At 5th level, you become able to use a discern lies effect once per day; your caster level is equal to twice your class level. Triadic knights often call this ability “judge’s insight.” \n\n Smite Evil (Su): Beginning at 5th level, you can smite evil once per day. See the paladin class feature, page 44 of the Player’s Handbook. If you already have this ability from another class, your Triadic knight class levels stack with that class’s levels for the purpose of determining the extra damage dealt. For example, a 5th-level paladin/4th-level Triadic knight would deal an extra 9 points of damage with each successful smite evil attempt. Smite evil attempts per day gained from multiple sources stack. \n\n Heart of Torm (Su): At 6th level, you gain immunity to fear. \n\n Shout (Sp): At 7th level, you can use shout once per day; your caster level is equal to twice your class level. Triadic knights often call this ability “lion’s roar.” \n\n Threefold Smite (Su): At 7th level, you can combine three smite evil attempts in a single attack. Doing this costs you three of your daily smite evil attempts; if you don’t have at least three such attempts remaining, you can’t use this ability. Making a threefold smite requires a full-round action and triples the bonus on damage rolls (but not on attack rolls) normally applied with a smite evil attack. For example, a 5th-level paladin/7th-level Triadic knight would deal an extra 36 points of damage (three times his effective smite evil level of 12th)."}'::jsonb)
insert into public.catalog_items (id,name_pt,name_en,description_pt,item_category,level,price_gp,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.cov.substitution.cov-sub-berronar-valkyrie-paladin','Berronar Valkyrie','Berronar Valkyrie','Berronar’s Valkyries are female dwarf paladins of the goddess Berronar Truesilver. They study tactics and charge into battle to save male dwarf warriors. Their special powers help them look after their allies and punish oathbreakers. To take a Berronar Valkyrie paladin substitution level, a character must be a female dwarf, have Berronar as her patron deity, and be about to take her 3rd, 4th, or 6th level of paladin.','substitution',1,null,ARRAY['Paladin']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-berronar-valkyrie-paladin","name":"Berronar Valkyrie","baseClass":"Paladin","hitDie":10,"flavor":"Berronar’s Valkyries are female dwarf paladins of the goddess Berronar Truesilver. They study tactics and charge into battle to save male dwarf warriors. Their special powers help them look after their allies and punish oathbreakers.","requirements":"To take a Berronar Valkyrie paladin substitution level, a character must be a female dwarf, have Berronar as her patron deity, and be about to take her 3rd, 4th, or 6th level of paladin.","classSkills":"Berronar Valkyrie paladin substitution levels have the class skills of the standard paladin.","levels":[{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+1","special":"Everbright blessing"},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+1","special":"Valiant rescue"},{"level":6,"bab":"+6/+1","fort":"+5","ref":"+2","will":"+2","special":"Binding oath, touch of fatigue"}],"featuresText":"All of the following are features of the Berronar Valkyrie substitution levels.\n\nEverbright Blessing (Su): Starting at 3rd level, a Valkyrie’s armor, shield, and primary weapon are treated as if they had the everbright special ability; they shine like polished silver, they are immune to acid and rust attacks, and the armor provides her with resistance to acid 5. This ability only applies to the items the Valkyrie is wearing; if the items are removed or dropped, they lose this property until she picks them up again. This benefit replaces the divine health class feature gained by a standard paladin at 3rd level.\n\nValiant Rescue (Ex): Starting at 4th level, a Valkyrie gains a special ability to charge into harm’s way to protect an ally. A Valkyrie can charge into melee with a creature that threatens one of her allies and still make a full attack with a single melee weapon rather than a single attack. During this charge she acts as if she had the Mobility feat; if she is mounted, this bonus also applies to her mount. A Valkyrie can use this ability a number of times per day equal to 3 + her Charisma modifier. This benefit replaces the turn undead class feature gained by a standard paladin at 4th level.\n\nBinding Oath (Su): At 6th level, a Valkyrie gains the ability to magically link two willing individuals making an oath (or a legal agreement). This link has two effects. First, it informs both parties and the Valkyrie instantly if the oath is broken in any way. Second, the individual who breaks the oath is fatigued for one day per paladin level of the Valkyrie at the time of the oath-binding. A Valkyrie can bind an oath once per week as a full-round action. For every three paladin levels gained thereafter, the Valkyrie can use this ability one extra time per week (2/week at 9th level, 3/week at 12th level, and so forth). This benefit replaces the remove disease class feature gained by a standard paladin at 6th level. A Berronar Valkyrie who selects this substitution level never gains the remove disease ability.\n\nTouch of Fatigue (Sp): Beginning at 6th level, a Valkyrie can use touch of fatigue at will. This ability is normally used to admonish those about to stray from their promises or to punish those guilty of minor infractions. The save DC against this spell-like ability is 10 + the Valkyrie’s Charisma modifier.","skillPointsPerLevel":"2 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-broken-one-monk','Broken One','Broken One','These kind and enduring monks dedicated to Ilmater are focused on defending the faithful and temples of the Broken God while acting as agents of punishment against those who would cruelly harm others. They combine the skills of healer and hunter in the service of their deity. They often assist other servants of the Triad when injustices against the innocent have occurred. To take a Broken One substitution level, a character must have Ilmater as her patron deity and be about to take her 3rd, 6th, or 7th level of monk.','substitution',1,null,ARRAY['Monk']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-broken-one-monk","name":"Broken One","baseClass":"Monk","hitDie":8,"flavor":"These kind and enduring monks dedicated to Ilmater are focused on defending the faithful and temples of the Broken God while acting as agents of punishment against those who would cruelly harm others. They combine the skills of healer and hunter in the service of their deity. They often assist other servants of the Triad when injustices against the innocent have occurred.","requirements":"To take a Broken One substitution level, a character must have Ilmater as her patron deity and be about to take her 3rd, 6th, or 7th level of monk.","classSkills":"Broken One substitution levels have the class skills of the standard monk class plus Heal and Survival.","levels":[{"level":3,"bab":"+2","fort":"+3","ref":"+3","will":"+3","special":"Lay on hands"},{"level":6,"bab":"+4","fort":"+5","ref":"+5","will":"+5","special":"Tenacious tracker, slow fall 30 ft."},{"level":7,"bab":"+5","fort":"+5","ref":"+5","will":"+5","special":"Locate creature"}],"featuresText":"All of the following are features of the Broken One substitution levels.\n\nLay on Hands (Su): At 3rd level, a Broken One can gain the ability to heal wounds with her touch (see the paladin class feature, page 44 of the Player’s Handbook). If the character has a Charisma score of 11 or lower, she can heal a number of points of damage each day equal to her monk class level. This benefit replaces the still mind class feature gained by a standard monk.\n\nTenacious Tracker (Su): Beginning at 6th level, a Broken One gains the ability to follow the trail of those cruel enough to torture and maim others. She receives Track as a bonus feat. She gains a +10 competence bonus on Survival checks made to track those with Loviatar as a patron deity. Furthermore, whenever she physically touches the flesh of one who has been injured within the previous hour by someone who has Loviatar as his patron deity, she receives a clear mental image of that person’s true appearance. This benefit replaces the bonus feat gained by a standard monk at 6th level.\n\nSlow Fall (Ex): A Broken One’s slow fall ability is identical to a standard monk’s ability at 6th level.\n\nLocate Creature (Sp): Starting at 7th level, a Broken One can use locate creature once per day, but only when attempting to find a creature that has Loviatar as a patron deity. Her caster level is equal to her class level. This benefit replaces the wholeness of body class feature gained by a standard monk at 7th level.","skillPointsPerLevel":"4 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-claw-of-the-sun-and-the-ankh-paladin','Claw of the Sun and the Ankh','Claw of the Sun and the Ankh','The first Mulhorandi order of paladins to worship a god other than Osiris, the Claw of the Sun and the Ankh serves Horus-Re. Its fearless and fanatical soldiers are dedicated to energetically pursing the evil minions of Set, relentlessly destroying them and their foul plans whenever they are found. To take a Claw of the Sun and The Ankh substitution level, a character must have Horus-Re as his patron deity and be about to take his 1st, 6th, or 12th level of paladin.','substitution',1,null,ARRAY['Paladin']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-claw-of-the-sun-and-the-ankh-paladin","name":"Claw of the Sun and the Ankh","baseClass":"Paladin","hitDie":10,"flavor":"The first Mulhorandi order of paladins to worship a god other than Osiris, the Claw of the Sun and the Ankh serves Horus-Re. Its fearless and fanatical soldiers are dedicated to energetically pursing the evil minions of Set, relentlessly destroying them and their foul plans whenever they are found.","requirements":"To take a Claw of the Sun and The Ankh substitution level, a character must have Horus-Re as his patron deity and be about to take his 1st, 6th, or 12th level of paladin.","classSkills":"Claw of the Sun and the Ankh substitution levels have the class skills of the standard paladin class.","levels":[{"level":1,"bab":"+1","fort":"+2","ref":"+0","will":"+0","special":"Aura of good, bird of prey, detect evil"},{"level":6,"bab":"+6/+1","fort":"+5","ref":"+2","will":"+2","special":"Smite minions of Set"},{"level":12,"bab":"+12/+7/+2","fort":"+8","ref":"+4","will":"+4","special":"Horus-Re’s glory"}],"featuresText":"All of the following are features of the Claw of the Sun and the Ankh substitution levels.\n\nBird of Prey (Su): Beginning at 1st level, once per day a Claw of the Sun and the Ankh can pay homage to his god by taking on aspects of a hawk. His hands turn into claws that deal 1d4 points of damage; the attacks deal extra damage equal to one-half his paladin level to evil creatures. These attacks are considered magic, good-aligned weapons for the purpose of overcoming damage reduction. The paladin is considered to be proficient with these natural weapons while using this form. This transformation lasts for a number of rounds equal to 3 + his Charisma modifier. At 5th level, and every five levels thereafter, a Claw of the Sun and the Ankh can use this ability one extra time per day. This benefit replaces the smite evil class feature gained by a standard paladin. A Claw of the Sun and the Ankh never gains any smite evil attacks at later levels.\n\nSmite Minions of Set (Su): A Claw of the Sun and the Ankh is tasked with eliminating members of the church of Set. Starting at 6th level he can use a melee attack to attempt to smite a creature that has Set as its patron deity. This otherwise functions as the paladin’s normal smite evil class feature. A Claw of the Sun and the Ankh can use this smite attack once per day, plus one extra time per day for every three levels gained beyond 6th. This benefit replaces the standard paladin’s remove disease class feature. A Claw of the Sun and the Ankh who selects this substitution level never gains the remove disease ability.\n\nHorus-Re’s Glory (Su): Starting at 12th level, a Claw’s armor shines brightly (as the daylight spell). This illumination can be suppressed or resumed at will with a standard action. This benefit replaces the 3rd-level spell slot gained by a standard paladin at 12th level. From this point forward, a Claw of the Sun and the Ankh who selects this substitution level can prepare one less 3rd-level paladin spell than normal.","skillPointsPerLevel":"2 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-crescent-moon-knight-paladin','Crescent Moon Knight','Crescent Moon Knight','These unusual paladins of the Order of the Crescent Moon serve either Clangeddin Silverbeard or Selûne. The order was founded by an alliance between humans and dwarves to defeat marauding lycanthropes; now, the descendants of the founders teach old family skills and pass heirlooms to the next generation of defenders. To take a Crescent Moon Knight paladin substitution level, a character must have Clangeddin Silverbeard or Selûne as his patron deity, be related to or a close friend of one of the founding families, and be about to take his 4th, 6th, or 10th level of paladin.','substitution',1,null,ARRAY['Paladin']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-crescent-moon-knight-paladin","name":"Crescent Moon Knight","baseClass":"Paladin","hitDie":10,"flavor":"These unusual paladins of the Order of the Crescent Moon serve either Clangeddin Silverbeard or Selûne. The order was founded by an alliance between humans and dwarves to defeat marauding lycanthropes; now, the descendants of the founders teach old family skills and pass heirlooms to the next generation of defenders.","requirements":"To take a Crescent Moon Knight paladin substitution level, a character must have Clangeddin Silverbeard or Selûne as his patron deity, be related to or a close friend of one of the founding families, and be about to take his 4th, 6th, or 10th level of paladin.","classSkills":"Crescent Moon Knight paladin substitution levels have the class skills of the standard paladin plus Knowledge (local Impiltur).","levels":[{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+1","special":"Favored enemy lycanthropes +2"},{"level":6,"bab":"+6/+1","fort":"+5","ref":"+2","will":"+2","special":"Remove disease, cure lycanthropy"},{"level":10,"bab":"+10/+5","fort":"+7","ref":"+3","will":"+3","special":"Battlesong"}],"featuresText":"All of the following are features of the Crescent Moon Knight substitution levels.\n\nFavored Enemy (Ex): At 4th level, a Knight gains lycanthropes as a favored enemy, just as if he were a 1st-level ranger. Unlike standard ranger favored enemies, which are organized by monster type, the Knight’s favored enemy bonuses apply to all lycanthropes regardless of type (for example, the bonuses apply against a human werewolf and a hill giant dire wereboar). This benefit replaces the turn undead class feature gained by a standard paladin at 4th level.\n\nCure Lycanthropy (Su): Starting at 6th level, a Knight becomes versed in the methods of curing lycanthropy. A Knight counts as a 12th-level cleric for the purpose of curing lycanthropy within 3 days of a lycanthrope’s attack. A Knight can use his remove disease spell-like ability as if it were break enchantment or remove curse to cure a lycanthrope on the nights of the full moon.\n\nBattlesong (Su): Once per day starting at 10th level, a Knight can begin an inspiring battle song as a standard action. This song functions like a bard’s inspire courage ability, using the Knight’s paladin level minus 4 as his bard level. For example, a 10th-level paladin who selects this substitution level would receive a +1 morale bonus on the relevant rolls, while an 18th-level paladin would receive a +3 morale bonus. A Knight need not have any ranks in Perform to use this class feature. This benefit replaces the 2nd-level spell slot gained by a standard paladin at 10th level. From this point forward, a Crescent Moon Knight who selects this substitution level can prepare one less 2nd-level paladin spell than normal.","skillPointsPerLevel":"2 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-darksong-knight-fighter','Darksong Knight','Darksong Knight','The Darksong Knights are elite soldiers of Eilistraee who further her many causes and hunt the yochlol, the demonic servants of the Spider Queen. They develop an intricate, dancelike style of swordplay and special powers to defeat their demonic enemies. To take a Darksong Knight substitution level, a character must have Eilistraee as her patron deity and be about to take her 2nd, 6th, or 8th level of fighter.','substitution',1,null,ARRAY['Fighter']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-darksong-knight-fighter","name":"Darksong Knight","baseClass":"Fighter","hitDie":8,"flavor":"The Darksong Knights are elite soldiers of Eilistraee who further her many causes and hunt the yochlol, the demonic servants of the Spider Queen. They develop an intricate, dancelike style of swordplay and special powers to defeat their demonic enemies.","requirements":"To take a Darksong Knight substitution level, a character must have Eilistraee as her patron deity and be about to take her 2nd, 6th, or 8th level of fighter.","classSkills":"Darksong Knight substitution levels have the class skills of the standard fighter class plus Perform (dance).","levels":[{"level":2,"bab":"+2","fort":"+3","ref":"+0","will":"+0","special":"Bonus feat, dancing feint"},{"level":6,"bab":"+6/+1","fort":"+5","ref":"+2","will":"+2","special":"Bonus feat, favored enemy yochlols +2"},{"level":8,"bab":"+8/+3","fort":"+6","ref":"+2","will":"+2","special":"Bonus feat, combat dancing"}],"featuresText":"All of the following are features of the Darksong Knight substitution levels.\n\nBonus Feat: A Darksong Knight’s choice of bonus feats is identical to a standard fighter’s bonus feats.\n\nDancing Feint (Ex): Starting at 2nd level, a Darksong Knight can use her Perform (dance) skill to feint in combat as if it were the Bluff skill.\n\nFavored Enemy (Ex): At 4th level, a Darksong Knight gains yochlols as a favored enemy, just as if she were a 1st-level ranger. Unlike standard ranger favored enemies, which are classified by monster type, the Knight’s favored enemy bonuses apply only to yochlols, not all kinds of demons.\n\nCombat Dancing (Ex): At 8th level, a Darksong Knight with at least 5 ranks in Perform (dance) gains a +2 dodge bonus against attacks of opportunity. If she uses Spring Attack, she gains a +2 circumstance bonus on the attack roll made as part of the maneuver.","skillPointsPerLevel":"2 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-dukar-wizard','Dukar','Dukar','These wizards of a dwindling order protect the tenuous peace under the Sea of Fallen Stars, working quietly and secretly to achieve their goals and rebuild their numbers. Many of their powers stem from living coral implanted under the skin of their hands. To take a Dukar substitution level, a character must be about to take his 5th, 10th, or 15th level of wizard. The first time a character takes a Dukar substitution level, he must undergo a secret Dukar ritual that implants the living coral under the skin of his palms (see Dukar hand coral, page 63). The coral does not interfere with using his hands in any way. If the Dukar somehow loses this coral, he loses his coral-related powers, but if he is implanted again he immediately regains his full abilities.','substitution',1,null,ARRAY['Wizard']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-dukar-wizard","name":"Dukar","baseClass":"Wizard","hitDie":4,"flavor":"These wizards of a dwindling order protect the tenuous peace under the Sea of Fallen Stars, working quietly and secretly to achieve their goals and rebuild their numbers. Many of their powers stem from living coral implanted under the skin of their hands.","requirements":"To take a Dukar substitution level, a character must be about to take his 5th, 10th, or 15th level of wizard. The first time a character takes a Dukar substitution level, he must undergo a secret Dukar ritual that implants the living coral under the skin of his palms (see Dukar hand coral, page 63). The coral does not interfere with using his hands in any way. If the Dukar somehow loses this coral, he loses his coral-related powers, but if he is implanted again he immediately regains his full abilities.","classSkills":"Dukar substitution levels have the class skills of the standard wizard class plus Swim.","levels":[{"level":5,"bab":"+2","fort":"+1","ref":"+1","will":"+4","special":"Coral claw, bonus spells"},{"level":10,"bab":"+5","fort":"+3","ref":"+3","will":"+7","special":"Coral power, bonus spells"},{"level":15,"bab":"+7/+2","fort":"+5","ref":"+5","will":"+9","special":"Coral power, bonus spells"}],"featuresText":"All of the following are features of the Dukar substitution levels.\n\nBonus Spells (Ex): There are four Dukar orders, each with two associated schools of magic. Upon taking his first Dukar substitution level, a Dukar chooses one order and can never change it thereafter (similar to choosing a wizard specialty school). Each time a Dukar substitution level is taken, a Dukar adds two spells to his spell book; these must be from one or both of his order’s associated schools of magic (either one from each or both from the same). A specialist wizard Dukar is not restricted to choosing these bonus spells from his school of specialization, but he cannot use them to acquire spells from his prohibited school (therefore, choosing an order that studies one of your prohibited schools is normally a bad choice). The orders are as follows. Order Color Schools of Magic Jhimar* Red Enchantment, evocation Kupav Blue Aburation, transmutation Maalirn Green Conjuration, divination Numos White Illusion, necromancy * The order of Jhimar was destroyed centuries ago and its knowledge and traditions are lost. This class feature replaces the standard wizard’s ability to add two spells to his spellbook each time he gains a wizard level.\n\nCoral Claw (Ex): At 5th level, a Dukar can extend the coral under his skin to form sharp spikes on his hand, giving him a claw attack that deals 1d4 points of damage. The Dukar is automatically proficient in the coral weapon and can extend or retract the coral as a swift action. This benefit replaces the bonus feat normally gained by a 5th-level wizard.\n\nCoral Power: At 10th and 15th level, a Dukar learns how to use his implanted coral in different ways. Each time this ability is gained, a Dukar chooses one ability from the following choices. Each ability can be taken twice, with increasing effect.\n\nAcid (Ex): A Dukar adds 1d4 points of acid damage to all claw attacks (including those made with his coral claw; see above). The acid quickly decays and cannot be stored for later use. A Dukar and his gear are not harmed by his own coral’s acid. This ability functions automatically, though a Dukar can suspend or resume this ability as a free action. If a Dukar selects the ability a second time, the acid damage increases to 1d8 points.\n\nArmor (Ex): Three times per day as a standard action, a Dukar can make his coral extend hard growths across his skin, giving him a +1 enhancement bonus to his natural armor bonus to AC. These growths crumble to dust after 10 minutes. If a Dukar selects this ability a second time, the enhancement bonus to his natural armor increases to +2.\n\nColor Spray (Sp): A Dukar’s coral gains the ability to glow intensely in confusing patterns. At will as a standard action, a Dukar can use this light as a color spray effect. Using this ability requires the Dukar to have one hand free, uncovered, and able to make gestures. The save DC of this ability is Intelligence-based. If a Dukar takes this ability a second time, the save DC of this ability increases by 2.\n\nWound Transfer (Su): A Dukar’s coral develops the ability to transfer life energy by touch from him to another creature, healing its wounds at the expense of his own health. Each use of this ability heals the target of 1d6 points of damage and deals a like amount of damage to the Dukar. If a Dukar chooses this ability a second time, he heals the target of 2d6 points of damage and takes a like amount of damage per use. This ability can never provide a target more hit points than its full normal total +10. Any hit points gained beyond its normal maximum are treated as temporary hit points that last for up to 1 hour. This benefit replaces the bonus feat normally gained by a 10thor 15th-level wizard.","skillPointsPerLevel":"2 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-eternal-order-paladin','Eternal Order','Eternal Order','The primary duty of the Knights of the Eternal Order—Kelemvor’s main order of paladins—is to hunt and destroy powerful undead. They develop powerful undead-fighting powers by sacrificing other paladin abilities. To take an Eternal Order substitution level, a character must have Kelemvor as her patron deity and be about to take her 1st, 3rd, or 6th level of paladin.','substitution',1,null,ARRAY['Paladin']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-eternal-order-paladin","name":"Eternal Order","baseClass":"Paladin","hitDie":10,"flavor":"The primary duty of the Knights of the Eternal Order—Kelemvor’s main order of paladins—is to hunt and destroy powerful undead. They develop powerful undead-fighting powers by sacrificing other paladin abilities.","requirements":"To take an Eternal Order substitution level, a character must have Kelemvor as her patron deity and be about to take her 1st, 3rd, or 6th level of paladin.","classSkills":"Eternal Order substitution levels have the class skills of the standard paladin class.","levels":[{"level":1,"bab":"+1","fort":"+2","ref":"+0","will":"+0","special":"Aura of good, detect evil, corpsestrike 1/day, undead knowledge"},{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+1","special":"Aura of courage, eternal vigor, undead knowledge"},{"level":6,"bab":"+6/+1","fort":"+5","ref":"+2","will":"+2","special":"Greater turning, undead knowledge"}],"featuresText":"All of the following are features of the Eternal Order substitution levels.\n\nCorpsestrike (Su): An Eternal Order paladin can, as a swift action, surround her weapon with a visible gray aura of holy power that sheds light equal to a candle. Any weapon so affected can ignore any damage reduction (other than DR #/epic) possessed by an undead creature, regardless of its source. This aura lasts for a number of minutes equal to the paladin’s class level. This benefit replaces the standard paladin’s smite evil class feature. Any time an Eternal Order paladin would later gain an extra smite evil attempt (such as at 5th level), she can instead use this ability one extra time per day.\n\nUndead Knowledge (Ex): Each time an Eternal Order substitution level is taken, the character gains a cumulative +2 competence bonus on Knowledge (religion) checks concerning undead.\n\nEternal Vigor (Ex): Beginning at 3rd level, an Eternal Order paladin can ignore the effects of negative levels bestowed upon her by an undead creature. This benefit replaces the standard paladin’s divine health class feature.\n\nGreater Turning (Su): At 6th level, an Eternal Order paladin gains the ability to perform a greater turning once per day in place of a regular turning, just as if she had access to the Sun domain. This benefit replaces the standard paladin’s remove disease class feature normally gained at 6th level. At any level where a standard paladin gains an extra daily use of remove disease, an Eternal Order paladin instead gains another daily use of her greater turning ability.","skillPointsPerLevel":"2 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-fangshields-barbarian','Fangshields Barbarian','Fangshields Barbarian','Barbarians of the Fangshields have few worries about traps, because they spend most of their time in their home territory rather than crawling through dungeons. They train their bodies to their physical peak so they can be the shock troops of the organization, relying on their speed and strength to decimate enemy creatures quickly. Other monsters can fight in formation against massed enemies, but the Fangshields barbarians are skilled at charging opposing monsters and battering them with a few powerful hits. To take a Fangshields barbarian substitution level, a character must be a nonhumanoid creature about to take his 3rd, 5th, or 7th level of barbarian.','substitution',1,null,ARRAY['Barbarian']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-fangshields-barbarian","name":"Fangshields Barbarian","baseClass":"Barbarian","hitDie":12,"flavor":"Barbarians of the Fangshields have few worries about traps, because they spend most of their time in their home territory rather than crawling through dungeons. They train their bodies to their physical peak so they can be the shock troops of the organization, relying on their speed and strength to decimate enemy creatures quickly. Other monsters can fight in formation against massed enemies, but the Fangshields barbarians are skilled at charging opposing monsters and battering them with a few powerful hits.","requirements":"To take a Fangshields barbarian substitution level, a character must be a nonhumanoid creature about to take his 3rd, 5th, or 7th level of barbarian.","classSkills":"Fangshields barbarian substitution levels have the class skills of the standard barbarian class.","levels":[{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+1","special":"Fast charge (+10 ft.)"},{"level":5,"bab":"+5","fort":"+4","ref":"+1","will":"+1","special":"Awesome charge"},{"level":7,"bab":"+11/+6/+1","fort":"+7","ref":"+3","will":"+3","special":"Raging vigor"}],"featuresText":"All of the following are features of the Fangshields barbarian substitution levels.\n\nFast Charge (Ex): At 3rd level, a Fangshields barbarian gains a 10-foot enhancement bonus to his speed when he charges. This applies to any type of movement the barbarian uses. This benefit replaces the trap sense class feature gained by a standard barbarian at 3rd level. At any level where a standard barbarian gains a bonus to trap sense (6th, 9th, 12th, 15th, and 18th), a Fangshields barbarian instead increases the enhancement bonus to his charge speed by 10 feet.\n\nAwesome Charge (Ex): At 5th level, a charging Fangshields barbarian in a rage can make an attack at the end of the charge as if he had the Awesome Blow feat (see page 303 of the Monster Manual), even if he does not have the normal prerequisites for that feat. (Normally, Awesome Blow requires a standard action; this is a specific exception to that rule.) This benefit replaces the improved uncanny dodge class feature gained by a standard barbarian at 5th level.\n\nRaging Vigor (Ex): At 7th level, a Fangshields barbarian gains the ability to direct his force of will inward, causing his injured body to heal itself. As a standard action, he can spend one of his daily uses of rage to heal damage equal to twice his Hit Dice. He can even use this ability if he is already raging. This benefit replaces the standard barbarian’s damage reduction gained at 7th level. Instead, the Fangshields barbarian gains damage reduction 1/— at 10th level, and his damage reduction is treated as 1 point lower than normal from that point forward.","skillPointsPerLevel":"4 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-fangshields-druid','Fangshields Druid','Fangshields Druid','Druids of the Fangshields are the healers and nurturers of the group, acting on behalf of their more monstrous allies who cannot interact with “civilized” humanoids without causing fear and panic. To take a Fangshields druid substitution level, a character must be a nonhumanoid creature about to take her 4th, 5th, or 7th level of druid.','substitution',1,null,ARRAY['Druid']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-fangshields-druid","name":"Fangshields Druid","baseClass":"Druid","hitDie":8,"flavor":"Druids of the Fangshields are the healers and nurturers of the group, acting on behalf of their more monstrous allies who cannot interact with “civilized” humanoids without causing fear and panic.","requirements":"To take a Fangshields druid substitution level, a character must be a nonhumanoid creature about to take her 4th, 5th, or 7th level of druid.","classSkills":"Fangshields druid substitution levels have the class skills of the standard druid class.","levels":[{"level":4,"bab":"+3","fort":"+4","ref":"+1","will":"+4","special":"Spontaneous curing"},{"level":5,"bab":"+3","fort":"+4","ref":"+1","will":"+4","special":"Wild shape hands"},{"level":7,"bab":"+5","fort":"+5","ref":"+2","will":"+5","special":"Wild shape (humanoid)"}],"featuresText":"All of the following are features of the Fangshields druid substitution levels.\n\nSpontaneous Curing (Su): At 4th level, a Fangshields druid can spontaneously convert prepared druid spells of 1st level or higher into cure light wounds spells, just as a cleric can. Unlike a cleric, she cannot convert her prepared spells into any cure spell, just cure light wounds, nor can she apply metamagic feats to these spontaneously cast spells. This benefit replaces the resist nature’s lure class ability gained by a standard druid at 4th level.\n\nWild Shape Hands (Su): At 5th level, a Fangshields druid can use her wild shape ability to create simple dexterous hands if she doesn’t have them already. For example, a giant eagle, lammasu, or unicorn could use wild shape to change her feet, paws, or hooves into hands that work as well as human hands. These hands lose any natural attacks they previously possessed, but otherwise still function like their original shape (a unicorn could walk or run at normal speed on her hoof-hands, for example). She can make this change whenever she uses her wild shape, even when she assumes another form. For example, a unicorn druid could take the form of a wolf with functional paw-hands. This benefit is in addition to the standard druid’s wild shape ability. Wild Shape (Humanoid) (Su): At 7th level, a Fangshields druid can use her wild shape ability to assume a Medium humanoid form. The humanoid form can resemble a human, dwarf, elf, or other Medium humanoid as the druid desires and has the appropriate racial traits for that race (according to the polymorph spell). This ability is typically used by a druid to interact with humanoid settlements without drawing too much attention to herself. However, the humanoid form retains some of a Fangshields druid’s original monstrous appearance, much like how a lycanthrope in hybrid form has humanoid and animal features, resulting in a –4 penalty on Disguise checks made to pass as a humanoid. The hybrid form can speak as well as a true humanoid, though the change of form does not give the druid knowledge of that form’s language (a druid in the form of an elf wouldn’t automatically know how to speak Elven, but could use her elf-mouth to speak any languages she did know).\n\nExample: A giant eagle could wild shape into a humanlike humanoid, but she would resemble an eagle–human hybrid (much like an avoral guardinal); a treant taking the form of an elf hybrid would look like a tall elf with barklike skin and leaves in her hair (much like a dryad). This benefit replaces the third use of wild shape per day gained by a standard druid at 8th level. From this point forward, a Fangshields druid has one less daily use of wild shape than normal.","skillPointsPerLevel":"4 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-fangshields-ranger','Fangshields Ranger','Fangshields Ranger','Rangers of the Fangshields use their skills to patrol the wildlands, as well as to spy on and hunt evil creatures. However, some of the standard ranger class features are useless to creatures that lack hands to use manufactured weapons. Fangshields rangers learn other abilities to take advantage of their nonhumanoid anatomy, helping them become dangerous leaders of beasts and animals. To take a Fangshields ranger substitution level, a character must be a nonhumanoid creature about to take his 2nd, 4th, or 5th level of ranger.','substitution',1,null,ARRAY['Ranger']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-fangshields-ranger","name":"Fangshields Ranger","baseClass":"Ranger","hitDie":8,"flavor":"Rangers of the Fangshields use their skills to patrol the wildlands, as well as to spy on and hunt evil creatures. However, some of the standard ranger class features are useless to creatures that lack hands to use manufactured weapons. Fangshields rangers learn other abilities to take advantage of their nonhumanoid anatomy, helping them become dangerous leaders of beasts and animals.","requirements":"To take a Fangshields ranger substitution level, a character must be a nonhumanoid creature about to take his 2nd, 4th, or 5th level of ranger.","classSkills":"Fangshields ranger substitution levels have the class skills of the standard ranger class plus Diplomacy.","levels":[{"level":2,"bab":"+2","fort":"+3","ref":"+3","will":"+0","special":"Combat style"},{"level":4,"bab":"+4","fort":"+4","ref":"+4","will":"+1","special":"Animal companion"},{"level":5,"bab":"+5","fort":"+4","ref":"+4","will":"+1","special":"Lion and the Unicorn"}],"featuresText":"All of the following are features of the Fangshields ranger substitution levels.\n\nCombat Style (Ex): Often lacking hands, Fangshields rangers have a third option for their combat style: natural attacks. If a ranger selects this combat style, at 2nd level he gains Multiattack (if he has more than one kind of natural attack) or Improved Natural Attack (if he has only one kind of natural attack) as a bonus feat. At 6th level, a ranger with this combat style gains Weapon Focus for any one of his natural attack types. At 11th level, a ranger with this combat option gains Weapon Focus for a second of his natural weapons, or Greater Weapon Focus for his natural weapon if he has only one kind. A Fangshields ranger need not meet any of the normal prerequisites for these bonus feats.\n\nAnimal Companion (Ex): A Fangshields ranger uses the normal ranger animal companion rules, but because he is beastlike himself, he has a stronger bond with the animal. The ranger’s effective druid level is treated as one-half his ranger level +2.\n\nLion and the Unicorn (Ex): At 5th level, a Fangshields ranger chooses an affinity for Nobanion or Lurue, even if he already has a patron deity (this doesn’t cause a religious conflict). If he chooses Nobanion, he gets a +1 sacred bonus to AC during the day; if he chooses Lurue, he gets a +1 sacred bonus to AC during the night. He gets the benefit of this ability whether or not he is outside or knows the time of day. This ability doesn’t apply on a plane other than the Material Plane. This benefit replaces the second favored enemy class feature gained by a standard ranger at 5th level.","skillPointsPerLevel":"6 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-golden-cup-paladin','Golden Cup','Golden Cup','Paladins who are members of the Order of the Golden Cup serve Ilmater and have dedicated themselves to healing the sick and weak and protecting the innocent. Peaceful counterparts to the Companions of the Noble Heart (see page 100), they don’t shy away from combating evil, but they allow their companions to actively hunt it down while they focus on protecting those who can’t protect themselves. To take a Golden Cup substitution level, a character must have Ilmater as her patron deity and be about to take her 3rd, 4th, or 10th level of paladin.','substitution',1,null,ARRAY['Paladin']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-golden-cup-paladin","name":"Golden Cup","baseClass":"Paladin","hitDie":10,"flavor":"Paladins who are members of the Order of the Golden Cup serve Ilmater and have dedicated themselves to healing the sick and weak and protecting the innocent. Peaceful counterparts to the Companions of the Noble Heart (see page 100), they don’t shy away from combating evil, but they allow their companions to actively hunt it down while they focus on protecting those who can’t protect themselves.","requirements":"To take a Golden Cup substitution level, a character must have Ilmater as her patron deity and be about to take her 3rd, 4th, or 10th level of paladin.","classSkills":"Golden Cup substitution levels have the class skills of the standard paladin class.","levels":[{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+1","special":"Defend the weak"},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+1","special":"Shield other"},{"level":10,"bab":"+10/+5","fort":"+7","ref":"+3","will":"+3","special":"Expanded healing"}],"featuresText":"All of the following are features of the Golden Cup substitution levels.\n\nDefend the Weak (Ex): Starting at 3rd level, a Golden Cup paladin can protect nearby allies in combat. If she uses Combat Expertise, fights defensively, or uses the total defense action, she can grant the dodge bonus to AC from these actions to any single creature standing adjacent to her in addition to herself. This benefit replaces the standard paladin’s aura of courage class feature.\n\nShield Other (Sp): Beginning at 4th level, a Golden Cup paladin can use shield other as a spell-like ability. She needs no focus for this ability, but she must be able to touch the character. She can use this ability a number of times per day equal to her Charisma bonus (minimum 1/day), though she can’t affect more than one target simultaneously (a second use ends the duration of any previous use). Her caster level is equal to her paladin level. This benefit replaces the standard paladin’s turn undead class feature.\n\nExpanded Healing (Su): Beginning at 10th level, a Golden Cup paladin can treat her paladin level as three higher than normal for the purpose of determining the maximum amount of healing she can bestow with her lay on hands ability per day. She can also treat her caster level as three higher than normal for the purpose of any conjuration (healing) spell she casts. This benefit replaces the third daily use of the smite evil ability gained by a standard paladin at 10th level. From this point forward, she has one less daily use of smite evil than normal.","skillPointsPerLevel":"2 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-golden-lion-paladin','Golden Lion','Golden Lion','The Order of the Golden Lion serves Torm and was created specifically to serve the Penance of Duty accepted by those of his faith. Members of the order are a varied bunch but united in their devotion and strength of purpose. They develop special powers to defend good temples, defeat Faerûnian evils, and repair damage to the Weave. To take a Golden Lion paladin substitution level, a character must have Torm as her patron deity, maintain the appearance of her armor and helm in accordance with the standards of the order, and be about to take her 1st, 4th, or 6th level of paladin. Furthermore, as part of an ongoing atonement for their church’s hostilities toward other good churches in the years preceding the Time of Troubles, the Golden Lions pledge to help rebuild and defend these churches. Once per month each Golden Lion must perform a quest for or spend a day defending a good temple of another faith. The Golden Lion must follow orders from this temple as if they came from her own temple, but can disregard any order that conflicts with her own faith or that would certainly result in her death (the good faiths involved understand the boundaries of the Penance of Duty and won’t ask for things they wouldn’t ask of their own champions of the faith).','substitution',1,null,ARRAY['Paladin']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-golden-lion-paladin","name":"Golden Lion","baseClass":"Paladin","hitDie":10,"flavor":"The Order of the Golden Lion serves Torm and was created specifically to serve the Penance of Duty accepted by those of his faith. Members of the order are a varied bunch but united in their devotion and strength of purpose. They develop special powers to defend good temples, defeat Faerûnian evils, and repair damage to the Weave.","requirements":"To take a Golden Lion paladin substitution level, a character must have Torm as her patron deity, maintain the appearance of her armor and helm in accordance with the standards of the order, and be about to take her 1st, 4th, or 6th level of paladin. Furthermore, as part of an ongoing atonement for their church’s hostilities toward other good churches in the years preceding the Time of Troubles, the Golden Lions pledge to help rebuild and defend these churches. Once per month each Golden Lion must perform a quest for or spend a day defending a good temple of another faith. The Golden Lion must follow orders from this temple as if they came from her own temple, but can disregard any order that conflicts with her own faith or that would certainly result in her death (the good faiths involved understand the boundaries of the Penance of Duty and won’t ask for things they wouldn’t ask of their own champions of the faith).","classSkills":"Golden Lion substitution levels have the class skills of the standard paladin class.","levels":[{"level":1,"bab":"+1","fort":"+2","ref":"+0","will":"+0","special":"Aura of good, detect magic, smite evil 1/day"},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+1","special":"Enemy of strife"},{"level":6,"bab":"+6/+1","fort":"+5","ref":"+2","will":"+2","special":"Restore the Weave"}],"featuresText":"All of the following are features of the Golden Lion substitution levels.\n\nDetect Magic (Sp): A Golden Lion can use a detect magic effect at will. Her caster level is equal to her paladin level. This benefit replaces the standard paladin’s detect evil ability.\n\nEnemy of Strife (Su): Golden Lions are tasked with eliminating the Zhentarim and the churches of Bane and Cyric. Beginning at 4th level, any smite evil attack used against a member of one of these groups (or a creature created or conjured by a member of one of these groups) automatically ignores any miss chance from concealment and overcomes damage reduction as if it were made with a good-aligned weapon. This benefit replaces the standard paladin’s ability to turn undead.\n\nRestore the Weave (Sp): At 6th level, once per day a Golden Lion can repair a 5-foot cube of dead magic or wild magic area, returning it to its normal function. This ability only works if the paladin stands in an area of normal Weave that is adjacent to the damaged area (in other words, it cannot create an “island” of normal Weave within a damaged area). Slowly but surely, the Golden Lions can repair large problem areas. This spell-like ability is the equivalent of a 3rd-level spell. This benefit replaces the remove disease class feature gained by a standard paladin at 6th level. At any level where a standard paladin gains an extra daily use of remove disease, a Golden Lion can instead gain another daily use of her restore the Weave ability.","skillPointsPerLevel":"2 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-holy-judge-paladin','Holy Judge','Holy Judge','This group of Tyr-worshiping paladins is focused primarily on its god’s lawful aspects. The Holy Judges hunt and punish criminals and lawbreakers, and they have a fervent hatred for devils, which they see as a terrible perversion of a lawful society. To take a Holy Judge substitution level, a character must have Tyr as her patron deity and be about to take her 1st, 4th, or 6th level of paladin.','substitution',1,null,ARRAY['Paladin']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-holy-judge-paladin","name":"Holy Judge","baseClass":"Paladin","hitDie":10,"flavor":"This group of Tyr-worshiping paladins is focused primarily on its god’s lawful aspects. The Holy Judges hunt and punish criminals and lawbreakers, and they have a fervent hatred for devils, which they see as a terrible perversion of a lawful society.","requirements":"To take a Holy Judge substitution level, a character must have Tyr as her patron deity and be about to take her 1st, 4th, or 6th level of paladin.","classSkills":"Holy Judge substitution levels have the class skills of the standard paladin class plus Knowledge (the planes).","levels":[{"level":1,"bab":"+1","fort":"+2","ref":"+0","will":"+0","special":"Aura of good, detect evil, favored enemy devils +2"},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+1","special":"Censure devil"},{"level":6,"bab":"+6/+1","fort":"+5","ref":"+2","will":"+2","special":"Zone of truth 1/week"}],"featuresText":"All of the following are features of the Holy Judge substitution levels.\n\nFavored Enemy (Ex): At 1st level, a Holy Judge gains devils as a favored enemy, just as if he were a 1st-level ranger. Unlike standard ranger favored enemies, which are classified by monster type, a Holy Judge’s favored enemy bonuses apply only to devils, not all kinds of evil outsiders. At 5th level, and every five levels thereafter, the bonus granted by the Holy Judge’s favored enemy class feature improves by 2. This increase has no effect on any other favored enemies the Holy Judge might have. This benefit replaces the standard paladin’s smite evil class feature.\n\nCensure Devil (Su): A Holy Judge on his home plane can utter words of censuring that can daze a devil within 30 feet. The devil must succeed on a Will save (DC 10 + 1/2 paladin level + Cha modifier) or be dazed for 1 round. A Holy Judge can use this ability a number of times per day equal to three + his Charisma modifier.\n\nZone of Truth (Sp): A Holy Judge can use a zone of truth effect once per week, using his paladin level as his caster level. This benefit replaces the standard paladin remove disease class feature. If the Holy Judge would later gain an extra weekly use of remove disease, he instead gains an extra weekly use of zone of truth.","skillPointsPerLevel":"2 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-lion-legionnaire-paladin','Lion Legionnaire','Lion Legionnaire','The mighty wemic paladins of Nobanion are called the Legion of Lions; they are small in number but great in their bravery. Unlike most of Lord Firemane’s wemic followers, they travel outside the Shaar in search of evil, and partly because of their efforts Nobanion’s faith has attracted humanoid followers. Though most Lion Legionnaires are wemics, a small number are humanoids, and at least one lammasu is a member of this elite group. Rather than traditional paladin abilities, they develop powers relating to Nobanion’s strengths and tactics. To take a Lion Legionnaire substitution level, a character must have Nobanion as his patron deity and be about to take his 3rd, 4th, or 5th level of paladin.','substitution',1,null,ARRAY['Paladin']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-lion-legionnaire-paladin","name":"Lion Legionnaire","baseClass":"Paladin","hitDie":10,"flavor":"The mighty wemic paladins of Nobanion are called the Legion of Lions; they are small in number but great in their bravery. Unlike most of Lord Firemane’s wemic followers, they travel outside the Shaar in search of evil, and partly because of their efforts Nobanion’s faith has attracted humanoid followers. Though most Lion Legionnaires are wemics, a small number are humanoids, and at least one lammasu is a member of this elite group. Rather than traditional paladin abilities, they develop powers relating to Nobanion’s strengths and tactics.","requirements":"To take a Lion Legionnaire substitution level, a character must have Nobanion as his patron deity and be about to take his 3rd, 4th, or 5th level of paladin.","classSkills":"Lion Legionnaire substitution levels have the class skills of the standard paladin class plus Knowledge (nature).","levels":[{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+1","special":"Firemane aura"},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+1","special":"Wild fighting"},{"level":5,"bab":"+5","fort":"+4","ref":"+1","will":"+1","special":"Smite evil 2/day, flying lion"}],"featuresText":"All of the following are features of the Lion Legionnaire substitution levels.\n\nFiremane Aura (Su): Once per day a Lion Legionnaire can create an aura of holy flame around his body. As this ability activates, the paladin’s hair or mane (if any) momentarily turns into a brilliant golden flame. Any evil creature striking a Lion Legionnaire with a natural weapon, or a melee weapon that is not a reach weapon, takes damage equal to the Legionnaire’s paladin level. Half of this damage is fire damage, but the other half results directly from divine power and is therefore not subject to being reduced by resistance to fire. This aura lasts for 1 minute. This benefit replaces the standard paladin’s aura of courage class feature.\n\nWild Fighting (Su): Lion Legionnaires develop a fighting style that gives them extra attacks at the cost of accuracy. As a free action, a Lion Legionnaire can enter a state of wild fighting for 1 round. During this round, a Legionnaire can make one extra attack with any one melee weapon (including natural weapons), but all attacks made during the round (including the extra attack) take a –2 penalty. A Lion Legionnaire must use a full attack action to benefit from wild fighting. A Lion Legionnaire can use this ability a number of times per day equal to three + his Charisma modifier. This benefit replaces the turn undead class feature gained by a standard paladin at 4th level.\n\nFlying Lion (Su): At 5th level, a Lion Legionnaire gains the ability to grow eagle’s wings, as Nobanion himself sometimes does in battle. Once per day as a full-round action, the Legionnaire grows feathered wings appropriate to the size of his body. The wings remain for up to 10 minutes per paladin level, though he can dismiss them as a free action. He can fly with the wings at his normal land speed, with poor maneuverability. Nonleonine creatures who use this ability temporarily gain a lionlike appearance while it is used (catlike eyes, a thick mane of hair, and larger teeth). This benefit replaces the special mount class feature gained by a standard paladin at 5th level (Nobanion’s wemic paladins have no need for a quadruped mount to carry them into battle).","skillPointsPerLevel":"2 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-mystic-fire-knight-paladin','Mystic Fire Knight','Mystic Fire Knight','The Knights of the Mystic Fire serve Mystra by guarding her temples and questing for lost magical troves. They develop increased ability to use magic, counter hostile magic, and defeat enemy spellcasters. To take a Mystic Fire Knight substitution level, a character must have Mystra as her patron deity and be about to take her 4th, 5th, or 6th level of paladin.','substitution',1,null,ARRAY['Paladin']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-mystic-fire-knight-paladin","name":"Mystic Fire Knight","baseClass":"Paladin","hitDie":8,"flavor":"The Knights of the Mystic Fire serve Mystra by guarding her temples and questing for lost magical troves. They develop increased ability to use magic, counter hostile magic, and defeat enemy spellcasters.","requirements":"To take a Mystic Fire Knight substitution level, a character must have Mystra as her patron deity and be about to take her 4th, 5th, or 6th level of paladin.","classSkills":"Mystic Fire Knight substitution levels have the class skills of the standard paladin plus Knowledge (arcana) and Spellcraft.","levels":[{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+1","special":"Bonus spell, improved spellcasting"},{"level":5,"bab":"+5","fort":"+5","ref":"+1","will":"+1","special":"Smite evil 2/day, special mount"},{"level":6,"bab":"+6/+1","fort":"+5","ref":"+2","will":"+2","special":"Spellshatter"}],"featuresText":"All of the following are features of the Mystic Fire Knight substitution levels.\n\nBonus Spell (Su): At 4th level, a Mystic Fire Knight gains a bonus 1st-level paladin spell slot as if from a high Wisdom score. At 8th level, she gains a bonus 2nd-level paladin spell slot, at 11th level she gains a bonus 3rd-level paladin spell slot, and at 14th level she gains a bonus 4th-level paladin spell slot. This benefit replaces the turn undead class feature gained by a standard paladin at 4th level.\n\nImproved Spellcasting (Ex): When casting paladin spells, a Mystic Fire Knight can treat her caster level as equal to one-half her paladin level +2. If she also has arcane spellcasting ability from another class, she can add her caster level from that class to this value to determine her paladin caster level.\n\nSmite Evil (Su): In addition to the normal effect, when a Mystic Fire Knight of 5th level or higher hits a creature with her smite evil attack, that creature finds it temporarily difficult to cast spells or use spell completion or spell trigger items. For 1 round, any attempt to complete one of these actions requires a successful Concentration check (DC 10 + paladin’s level + Cha modifier + spell level); failure means that the action fails. If a spell was being cast, the spell or spell slot is lost; if a magic item was being activated, the attempt merely fails. Multiple smite evil hits on the same creature don’t have a cumulative effect. This class feature augments, but does not replace, the standard paladin’s smite evil class feature.\n\nSpellshatter (Su): Once per day starting at 6th level, a Mystic Fire Knight can choose to deliver a targeted greater dispel magic effect with a melee attack. The decision to use this ability must be made before the attack is rolled; if the attack misses, the effect is wasted. If the attack hits, treat this as if the Mystic Fire Knight had cast a targeted greater dispel magic on the creature struck, using her paladin level (plus any arcane caster level she might have from another class) as her caster level, up to a maximum of +20. This benefit replaces the standard paladin’s remove disease class feature. If the Mystic Fire Knight would later gain an extra weekly use of remove disease, she instead gains an extra daily use of spellshatter.","skillPointsPerLevel":"2 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-noble-heart-paladin','Noble Heart','Noble Heart','The Companions of the Noble Heart are aggressive knights in the service of Ilmater who have dedicated themselves to eliminating the evil of those who are known to enjoy the torturing and suffering of others. In particular, they oppose members of the church of Loviatar and destroy them and their temples whenever possible. When servants of the other members of the Triad crusade against Loviatar’s servants, Noble Heart knights often join with them. To take a Noble Heart substitution level, a character must have Ilmater as her patron deity and be about to take her 3rd, 4th, or 6th level of paladin.','substitution',1,null,ARRAY['Paladin']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-noble-heart-paladin","name":"Noble Heart","baseClass":"Paladin","hitDie":10,"flavor":"The Companions of the Noble Heart are aggressive knights in the service of Ilmater who have dedicated themselves to eliminating the evil of those who are known to enjoy the torturing and suffering of others. In particular, they oppose members of the church of Loviatar and destroy them and their temples whenever possible. When servants of the other members of the Triad crusade against Loviatar’s servants, Noble Heart knights often join with them.","requirements":"To take a Noble Heart substitution level, a character must have Ilmater as her patron deity and be about to take her 3rd, 4th, or 6th level of paladin.","classSkills":"Noble Heart substitution levels have the class skills of the standard paladin class plus Survival.","levels":[{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+1","special":"Aura of courage, tenacious tracker"},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+1","special":"Sunder the sadistic"},{"level":6,"bab":"+6/+1","fort":"+5","ref":"+2","will":"+2","special":"Delay poison 1/week"}],"featuresText":"All of the following are features of the Noble Heart substitution levels.\n\nTenacious Tracker (Su): Beginning at 3rd level, a Noble Heart paladin gains the ability to follow the trail of those cruel enough to torture and maim others. She receives Track as a bonus feat. She gains a +10 competence bonus on Survival checks made to track those who have Loviatar as a patron deity. Furthermore, whenever she physically touches the flesh of one who has been injured within the previous hour by someone who has Loviatar as his patron deity, she receives a clear mental image of that person’s true appearance. This benefit replaces the standard paladin’s divine health class feature.\n\nSunder the Sadistic (Su): At 4th level, a Noble Heart paladin gains the ability to reduce to rubble objects and structures dedicated to evil. Whenever she attacks an object owned by a character who has Loviatar as a patron deity, or an object that is part of a temple or other structure dedicated to Loviatar, she can ignore the object’s hardness. She can also use her smite evil class ability against such objects as if they were evil creatures. This benefit replaces the standard paladin’s ability to turn undead.\n\nDelay Poison (Sp): The enemies of the Noble Heart paladin frequently employ poison in their efforts to spread evil and cruelty. Starting at 6th level, a Noble Heart paladin can use a delay poison effect once per week using her paladin level as her caster level. This benefit replaces the remove disease class feature gained by a standard paladin. If she would later gain extra weekly uses of remove disease, the Noble Heart paladin instead gains extra weekly uses of delay poison.","skillPointsPerLevel":"2 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-phoenix-disciple-monk','Phoenix Disciple','Phoenix Disciple','The Disciples of the Phoenix are unusual lawful good Kossuthan monks. They are extremely disciplined and take some of their beliefs to painful extremes. Obsessed with the power of fire to purify, they have developed strange monk abilities based on that concept. To take a Phoenix Disciple substitution level, a character must be lawful good, have Kossuth as his patron deity, and be about to take his 1st, 3rd, or 12th level of monk.','substitution',1,null,ARRAY['Monk']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-phoenix-disciple-monk","name":"Phoenix Disciple","baseClass":"Monk","hitDie":8,"flavor":"The Disciples of the Phoenix are unusual lawful good Kossuthan monks. They are extremely disciplined and take some of their beliefs to painful extremes. Obsessed with the power of fire to purify, they have developed strange monk abilities based on that concept.","requirements":"To take a Phoenix Disciple substitution level, a character must be lawful good, have Kossuth as his patron deity, and be about to take his 1st, 3rd, or 12th level of monk.","classSkills":"Phoenix Disciple substitution levels have the class skills of the standard monk class.","levels":[{"level":1,"bab":"+0","fort":"+2","ref":"+2","will":"+2","special":"Flurry of blows, purifying flame, unarmed strike"},{"level":3,"bab":"+2","fort":"+3","ref":"+3","will":"+3","special":"Resistance to fire"},{"level":12,"bab":"+9/+4","fort":"+8","ref":"+8","will":"+8","special":"Fire stride, slow fall 60 ft."}],"featuresText":"All of the following are features of the Phoenix Disciple substitution levels.\n\nPurifying Flame (Su): A Phoenix Disciple can transform his ki into purifying fire. Once per round, a Phoenix Disciple can add 1d6 points of fire damage to any unarmed strike. The decision to use this ability must be made before the attack is rolled; if the attack misses, the power is wasted. A Phoenix Disciple can use this ability a number of times per day equal to his monk level. This benefit replaces the bonus feat gained by a standard 1st-level monk.\n\nResistance to Fire (Ex): At 3rd level, a Phoenix Disciple develops a minor tolerance for fire. He gains resistance to fire 5. This benefit replaces the still mind class feature gained by a standard monk at 3rd level.\n\nFire Stride (Sp): At 12th level, a Phoenix Disciple gains the ability to use a fire stride effect (see page 69 of the FORGOTTEN REALMS Campaign Setting) once per day, using his monk level as his caster level. This benefit replaces the abundant step class feature gained by a standard monk at 12th level.","skillPointsPerLevel":"4 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-purple-staff-cleric','Purple Staff','Purple Staff','The Followers of the Purple Staff are a group of divine spellcasters trying to create a benign theocracy in the eastern part of the Dragon Coast. These clerics carry a great deal of political power within the borders of the so-called “Holy Realm” and use their magic to aid the citizens of their new land. To take a Purple Staff substitution level, a character must have Chauntea, Helm, Lathander, Nobanion, Selûne, or Sune as his patron deity and be about to take his 4th, 6th, or 9th level of cleric.','substitution',1,null,ARRAY['Cleric']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-purple-staff-cleric","name":"Purple Staff","baseClass":"Cleric","hitDie":8,"flavor":"The Followers of the Purple Staff are a group of divine spellcasters trying to create a benign theocracy in the eastern part of the Dragon Coast. These clerics carry a great deal of political power within the borders of the so-called “Holy Realm” and use their magic to aid the citizens of their new land.","requirements":"To take a Purple Staff substitution level, a character must have Chauntea, Helm, Lathander, Nobanion, Selûne, or Sune as his patron deity and be about to take his 4th, 6th, or 9th level of cleric.","classSkills":"Purple Staff substitution levels have the class skills of the standard cleric class.","levels":[{"level":4,"bab":"+3","fort":"+4","ref":"+1","will":"+4","special":"Spontaneous faith healing"},{"level":6,"bab":"+4","fort":"+5","ref":"+2","will":"+5","special":"Imbue with spell ability"},{"level":9,"bab":"+6/+11","fort":"+6","ref":"+3","will":"+6","special":"Turn invader"}],"featuresText":"All of the following are features of the Purple Staff substitution levels.\n\nSpontaneous Faith Healing (Su): At 4th level, a Purple Staff cleric gains the ability to spontaneously convert prepared cleric spells of 1st level or higher to cast faith healingMag in the same way she can convert them to cure spells. Armed with this power, a Purple Staff cleric is easily able to deal with even the most severe injuries that common folk might suffer. This class feature replaces the 2nd-level spell slot gained by a standard cleric at 4th level. From this point forward, a Purple Staff cleric has one less 2nd-level spell slot than normal.\n\nImbue with Spell Ability (Sp): At 6th level, a Purple Staff cleric can use an imbue with spell ability effect to imbue a creature with a single 0or 1st-level spell she has prepared. She can use this ability a number of times per day equal to one-half her class level. With this power, an adventuring Purple Staff cleric can leave nonspellcaster lieutenants in town to act on her behalf in emergencies or to spread out her spells to help defend a larger area (though she is not limited to these purposes, of course). This class feature replaces the 3rd-level spell slot gained by a standard cleric at 6th level. From this point forward, a Purple Staff cleric has one less 3rd-level spell slot than normal.\n\nTurn Invader (Su): At 9th level, a Purple Staff cleric is so devoted to protecting his homeland that he can use his ability to turn undead to frighten enemies of the Holy Realm. When standing within the borders of his country, he can turn hostile monsters or enemies of the Holy Realm as a good-aligned cleric turns undead. He cannot destroy such creatures outright using this ability.","skillPointsPerLevel":"2 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-red-falcon-paladin','Red Falcon','Red Falcon','Members of the Order of the Red Falcon serve the Red Knight and have earned fame in Tethyr for their heroics. They have a reputation for being excellent military tacticians, and even their followers are a cut above the norm. To take a Red Falcon substitution level, a character must have the Red Knight as her patron deity and be about to take her 2nd, 4th, or 6th level of paladin.','substitution',1,null,ARRAY['Paladin']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-red-falcon-paladin","name":"Red Falcon","baseClass":"Paladin","hitDie":10,"flavor":"Members of the Order of the Red Falcon serve the Red Knight and have earned fame in Tethyr for their heroics. They have a reputation for being excellent military tacticians, and even their followers are a cut above the norm.","requirements":"To take a Red Falcon substitution level, a character must have the Red Knight as her patron deity and be about to take her 2nd, 4th, or 6th level of paladin.","classSkills":"Red Falcon substitution levels have the class skills of the standard paladin class plus Knowledge (history).","levels":[{"level":2,"bab":"+2","fort":"+3","ref":"+0","will":"+0","special":"Brilliant strategy, lay on hands, military knowledge"},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+1","special":"Expanded spell list, military knowledge, turn undead"},{"level":6,"bab":"+6/+1","fort":"+5","ref":"+2","will":"+2","special":"Military knowledge, remove disease 1/week, spontaneous extend spell, trained militia"}],"featuresText":"All of the following are features of the Red Falcon substitution levels.\n\nBrilliant Strategy (Ex): At 2nd level and higher, a Red Falcon can draw upon her instinct for battle to give her an amazing ability to predict the imminent actions of her enemies and her best options for taking advantage of those actions. Activating this ability is an immediate action; it grants her an insight bonus to AC equal to her Charisma bonus (if any) for 1 round. A Red Falcon can use this ability a number of times per day equal to one-half her class level. This benefit replaces the standard paladin’s divine grace class feature.\n\nExpanded Spell List: At 4th level, a Red Falcon adds augury (2nd level), deathwatch (1st level), and status (2nd level) to her paladin spell list.\n\nMilitary Knowledge (Ex): Each time a Red Falcon substitution level is taken, the character gains a cumulative +2 competence bonus on Knowledge checks concerning military history or strategy.\n\nTurn Undead (Su): A Red Falcon is not as skilled at turning undead as a normal paladin. She can only use this ability a number of times per day equal to her Charisma modifier.\n\nSpontaneous Extend Spell (Su): At 6th level, once per day a Red Falcon can cast one of her spells as if she had prepared it with the Extend Spell feat. Doing this does not require a higher-level slot or increase the casting time for the spell. This class feature replaces the 1st-level spell slot normally gained at 6th level. From this point forward, a Red Falcon has one less 1st-level paladin spell slot than normal.\n\nTrained Militia: At 6th level, due to her leadership and skill at war, all cohorts and followers of the Red Falcon are treated as if they had Martial Weapon Proficiency in a single weapon of the Red Falcon’s choice. This benefit remains as long as the cohorts and followers remain in her service and as long as she meets with them at least once a month to refresh their training. If more than a month goes by without such a meeting, the cohorts and followers lose this proficiency until she has the opportunity to train them again. A Red Falcon can grant different weapon proficiencies to different cohorts and followers (they don’t all have to gain longsword proficiency, for example).","skillPointsPerLevel":"2 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-ruby-rose-knight-paladin','Ruby Rose Knight','Ruby Rose Knight','Members of Sune’s order of paladins, the Sisters and Brothers of the Ruby Rose, are known for their charm, beauty, and aversion to ugliness and evil. They use the power of love to destroy evil and hideous things, and they draw strength from their many romances. To take a Ruby Rose Knight substitution level, a character must have Sune as her patron and be about to take her 3rd, 6th, or 12th level of paladin.','substitution',1,null,ARRAY['Paladin']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-ruby-rose-knight-paladin","name":"Ruby Rose Knight","baseClass":"Paladin","hitDie":8,"flavor":"Members of Sune’s order of paladins, the Sisters and Brothers of the Ruby Rose, are known for their charm, beauty, and aversion to ugliness and evil. They use the power of love to destroy evil and hideous things, and they draw strength from their many romances.","requirements":"To take a Ruby Rose Knight substitution level, a character must have Sune as her patron and be about to take her 3rd, 6th, or 12th level of paladin.","classSkills":"Ruby Rose Knight substitution levels have the class skills of the standard paladin class plus Bluff and Perform (dance, oratory, sing, and string instruments).","levels":[{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+1","special":"Aura of courage, enduring personality, expanded spell list"},{"level":6,"bab":"+6/+1","fort":"+5","ref":"+2","will":"+2","special":"Heroism 1/week"},{"level":12,"bab":"+12/+7/+2","fort":"+8","ref":"+4","will":"+4","special":"Heroic rapture"}],"featuresText":"All of the following are features of the Ruby Rose Knight substitution levels.\n\nEnduring Personality (Su): A 3rd-level Ruby Rose Knight is immune to any effect that would deal Charisma damage or Charisma drain. This benefit replaces the standard paladin’s divine health class feature.\n\nExpanded Spell List: At 3rd level, a Ruby Rose Knight adds love bite (see page 56) to her paladin spell list (even though she can’t actually cast the spell herself until at least 4th level).\n\nHeroism (Sp): At 6th level, a Ruby Rose Knight can use a heroism effect once per week, using her class level as her caster level. She can’t use this spell-like ability on herself, only on another creature. This benefit replaces the remove disease class feature gained by a standard paladin. If she would later gain extra weekly uses of remove disease, a Ruby Rose Knight instead gains extra weekly uses of heroism.\n\nHeroic Rapture (Su): At 12th level, once per day a Ruby Rose Knight can spend a full-round action embracing another creature to grant it great bravery. The affected creature gains a +4 morale bonus on attack rolls, saves, and skill checks, immunity to fear effects, and a number of temporary hit points equal to the Ruby Rose Knight’s paladin level. The effect lasts for 1 minute. This benefit replaces the 3rd-level spell slot gained by a standard paladin at 12th level. From this point on, a Ruby Rose Knight has one less 3rd-level spell slot than normal.","skillPointsPerLevel":"2 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-shadow-sword-ranger','Shadow Sword','Shadow Sword','Rangers of the Knights of the Shadow Sword patrol Myth Drannor and attempt to rid it of the evils living there. They use their stealth and spell-power to aid the fighters of their order. To take a Shadow Sword substitution level, a character must have Shaundakul as his patron and be about to take his 3rd, 6th, or 8th level of ranger.','substitution',1,null,ARRAY['Ranger']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-shadow-sword-ranger","name":"Shadow Sword","baseClass":"Ranger","hitDie":8,"flavor":"Rangers of the Knights of the Shadow Sword patrol Myth Drannor and attempt to rid it of the evils living there. They use their stealth and spell-power to aid the fighters of their order.","requirements":"To take a Shadow Sword substitution level, a character must have Shaundakul as his patron and be about to take his 3rd, 6th, or 8th level of ranger.","classSkills":"Shadow Sword substitution levels have the class skills of the standard ranger class plus Knowledge (history).","levels":[{"level":3,"bab":"+3","fort":"+3","ref":"+3","will":"+1","special":"Walk in silence"},{"level":6,"bab":"+6","fort":"+5","ref":"+5","will":"+1","special":"Bane weapon"},{"level":8,"bab":"+8/+3","fort":"+6","ref":"+6","will":"+2","special":"Portal analysis"}],"featuresText":"All of the following are features of the Shadow Sword substitution levels.\n\nWalk in Silence (Su): At 3rd level, a Shadow Sword gains the ability to move with amazing silence, receiving a +5 circumstance bonus on Move Silently checks for 1 round. The ranger activates this ability with a swift action and can use it a number of times per day equal to one-half his ranger level. This ability only functions if the ranger is wearing light or no armor and carrying no more than a light load. This benefit replaces the Endurance bonus feat gained by a standard ranger at 3rd level.\n\nBane Weapon (Su): At 6th level, a Shadow Sword learns how to temporarily turn any weapon he wields into a bane weapon (see page 224 of the Dungeon Master’s Guide). Activating this ability requires a full-round action, at which point the ranger must choose the type (and subtype, if appropriate) of creature against which the bane special ability will apply. This choice must match a creature type (and subtype) of one of the ranger’s favored enemies. The effect lasts for a number of rounds equal to one-half the ranger’s class level, and can be used a number of times per day equal to one + his Wisdom modifier (minimum 1/day). The bane ability only functions while the weapon is in the ranger’s hands. The ranger can have no more than one weapon affected by this class feature at any time, nor can any weapon benefit from more than one application of this class feature (in either case, a second use immediately ends any previous effect). This benefit replaces the improved combat style class feature normally gained at 6th level. If a Shadow Sword ranger later gains combat style mastery, he instead gains improved combat style.\n\nPortal Analysis (Su): At 8th level, a Shadow Sword gains the ability to sense portals and manipulate them in strange ways. He automatically detects any portal within 10 feet and can thereafter study any portal within 10 feet as if using analyze portal (see page 66 of the FORGOTTEN REALMS Campaign Setting). If he is able to activate the portal, once per day the Shadow Sword can enter it as if using the portal well spell (see page 56). This benefit replaces the swift tracker class feature gained by a standard ranger at 8th level.","skillPointsPerLevel":"6 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-shooting-star-ranger','Shooting Star','Shooting Star','Rangers of the Order of the Shooting Star (see Knights of the Mystic Fire, page 102) serve Mystra by scouting, spying, and dealing with fiends and monstrosities created by magical experimentation. To take a Shooting Star substitution level, a character must have Mystra as her patron deity and be about to take her 3rd, 4th, or 8th level of ranger.','substitution',1,null,ARRAY['Ranger']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-shooting-star-ranger","name":"Shooting Star","baseClass":"Ranger","hitDie":8,"flavor":"Rangers of the Order of the Shooting Star (see Knights of the Mystic Fire, page 102) serve Mystra by scouting, spying, and dealing with fiends and monstrosities created by magical experimentation.","requirements":"To take a Shooting Star substitution level, a character must have Mystra as her patron deity and be about to take her 3rd, 4th, or 8th level of ranger.","classSkills":"Shooting Star substitution levels have the class skills of the standard ranger class plus Knowledge (arcana) and Spellcraft.","levels":[{"level":3,"bab":"+3","fort":"+3","ref":"+3","will":"+1","special":"Weavespeak"},{"level":4,"bab":"+4","fort":"+4","ref":"+4","will":"+1","special":"Bonus spells, improved spellcasting"},{"level":8,"bab":"+8/+3","fort":"+6","ref":"+6","will":"+2","special":"Bonus spells, expanded spell list"},{"level":11,"bab":"+11/+6/+1","fort":"+7","ref":"+7","will":"+3","special":"Bonus spells"},{"level":14,"bab":"+14/+9/+4","fort":"+9","ref":"+9","will":"+4","special":"Bonus spells"}],"featuresText":"All of the following are features of the Shooting Star ranger substitution levels.\n\nWeavespeak (Sp): Because the members of this order need to report their findings over long distances, starting at 3rd level a Shooting Star develops the power to use the Weave itself to transmit short messages. Once per day the character can transmit a message of twenty-five words or less to the nearest cleric, paladin, or ranger of Mystra (the Shooting Star can’t choose the recipient). This ability only functions where the Weave is active, and it cannot jump planar boundaries; the ranger knows if either condition would prevent the message from reaching its target. It is otherwise the equivalent of a sending spell. This benefit replaces the Endurance bonus feat gained by a standard ranger at 3rd level.\n\nBonus Spells (Su): At 4th level, a Shooting Star gains a bonus 1st-level ranger spell slot as if from a high Wisdom score. At 8th level she gains a bonus 2nd-level ranger spell slot, at 11th level she gains a bonus 3rd-level ranger spell slot, and at 14th level she gains a bonus 4th-level ranger spell slot. This benefit replaces the animal companion class feature gained by a standard ranger at 4th level.\n\nImproved Spellcasting (Ex): When casting ranger spells, a Shooting Star can treat her caster level as equal to one-half her ranger level +2. If she also has arcane spellcasting ability from another class, she can add her caster level from that class to this value to determine her caster level.\n\nExpanded Spell List: At 8th level, a Shooting Star adds see invisibility (2nd level) and word of recall (4th level) to her ranger spell list. This replaces the standard ranger’s swift tracker class feature.","skillPointsPerLevel":"6 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-vigilant-eye-of-helm-paladin','Vigilant Eye of Helm','Vigilant Eye of Helm','This paladin order of Helm is growing rapidly and impressing the common folk with its members’ humility and self-sacrifice. The Vigilant Eyes of Helm defend the innocent from threats and develop special ways of recognizing danger and protecting others. To take a Vigilant Eye substitution level, a character must have Helm as her patron deity and be about to take her 1st, 3rd, or 4th level of paladin.','substitution',1,null,ARRAY['Paladin']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-vigilant-eye-of-helm-paladin","name":"Vigilant Eye of Helm","baseClass":"Paladin","hitDie":10,"flavor":"This paladin order of Helm is growing rapidly and impressing the common folk with its members’ humility and self-sacrifice. The Vigilant Eyes of Helm defend the innocent from threats and develop special ways of recognizing danger and protecting others.","requirements":"To take a Vigilant Eye substitution level, a character must have Helm as her patron deity and be about to take her 1st, 3rd, or 4th level of paladin.","classSkills":"Vigilant Eye substitution levels have the class skills of the standard paladin class.","levels":[{"level":1,"bab":"+1","fort":"+2","ref":"+0","will":"+0","special":"Aura of good, expanded spell list, know greatest enemy, smite evil 1/day"},{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+1","special":"Aura of courage, vigilant aid"},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+1","special":"Awesome smite"}],"featuresText":"All of the following are features of the Vigilant Eye substitution levels.\n\nKnow Greatest Enemy (Su): A Vigilant Eye automatically knows which enemy in her presence is the most powerful (in game terms, which enemy has the highest CR). This benefit applies only to enemies that she can see that are within 60 feet of her. She does not need to use an action to know this, and this sense updates automatically if current foes leave or die or if new opponents arrive. She doesn’t know why the most powerful enemy is such (for example, she wouldn’t know that the most powerful orc in a patrol was a 3rd-level barbarian), just that it is so. She doesn’t know exactly how tough this enemy is, but does know if that enemy is significantly more powerful than her (in game terms, if its CR is 4 or more above her effective character level). This benefit replaces the standard paladin’s detect evil class feature.\n\nExpanded Spell List: A Vigilant Eye adds see invisibility (2nd level) to her paladin spell list.\n\nVigilant Aid (Su): Starting at 3rd level, when a Vigilant Eye uses the aid another special attack in melee combat to give an ally a bonus to his AC, she only has to spend a move action rather than a standard action. She can use more than one aid another special attack in a single round, but no ally can be aided more than once per round in this fashion. This benefit replaces the standard paladin’s divine health class feature.\n\nAwesome Smite (Su): At 4th level, a Vigilant Eye gains the ability to repel enemies with powerful holy power. As a standard action, she can spend a daily smite evil attempt and strike an evil creature as if she had the Awesome Blow feat (see page 303 of the Monster Manual), even if she does not have the normal prerequisites for that feat. Note that the paladin doesn’t also gain the normal benefit of smite evil. She is treated as if one size category larger than normal for determining which creatures she can affect with this ability. If she accidentally uses this ability against a creature that isn’t evil, she deals normal damage but the Awesome Blow effect is not triggered, and it still counts as one of her daily uses of smite evil. This benefit replaces the standard paladin’s turn undead class feature.","skillPointsPerLevel":"2 + Int modifier"}'::jsonb),
('dnd35.cov.substitution.cov-sub-wary-swordknight-paladin','Wary Swordknight','Wary Swordknight','Members of Arvoreen’s Marchers kept halfling villages safe during Tethyr’s Interregnum; the Wary Swordknights are the paladins of the order, and are known for their martial prowess and vigilant nature. To take a Wary Swordknight substitution level, a character must be a halfling, have Arvoreen as her patron deity, and be about to take her 3rd, 4th, or 6th level of paladin.','substitution',1,null,ARRAY['Paladin']::text[],'v35-cov','D&D 3.5 — Champions of Valor',34,'dnd35','{"id":"cov-sub-wary-swordknight-paladin","name":"Wary Swordknight","baseClass":"Paladin","hitDie":10,"flavor":"Members of Arvoreen’s Marchers kept halfling villages safe during Tethyr’s Interregnum; the Wary Swordknights are the paladins of the order, and are known for their martial prowess and vigilant nature.","requirements":"To take a Wary Swordknight substitution level, a character must be a halfling, have Arvoreen as her patron deity, and be about to take her 3rd, 4th, or 6th level of paladin.","classSkills":"Wary Swordknight substitution levels have the class skills of the standard paladin plus Listen and Spot.","levels":[{"level":3,"bab":"+3","fort":"+3","ref":"+1","will":"+1","special":"Divine health, tougher than small"},{"level":4,"bab":"+4","fort":"+4","ref":"+1","will":"+1","special":"Uncanny dodge"},{"level":6,"bab":"+6","fort":"+5","ref":"+2","will":"+2","special":"Haste (self) 1/day"}],"featuresText":"All of the following are features of the Wary Swordknight substitution levels.\n\nTougher than Small (Ex): When a Wary Swordknight is subject to a size modifier or special size modifier for an opposed check (such as during grapple checks, bull rush attempts, and trip attempts), she is treated as one size larger if doing so is advantageous to her. A Wary Swordknight is also considered to be one size larger when determining whether a creature’s special attacks based on size (such as improved grab or swallow whole) can affect her. The benefits of this class feature stack with effects that change her size category. This benefit replaces the standard paladin’s aura of courage class feature.\n\nUncanny Dodge (Ex): At 4th level, a Swordknight gains uncanny dodge (as the barbarian class feature of the same name). This benefit replaces the standard paladin’s turn undead class feature.\n\nHaste (Sp): At 6th level, a Swordknight becomes able to use a haste effect on herself once per day. Her caster level for this ability is equal to one-half her paladin level. This benefit replaces the 1st-level spell slot gained at 6th level, as well as the remove disease class feature normally gained at 6th level. From this point forward, a Wary Swordknight has one less weekly use of remove disease than normal. Spells In a world of magic such as Faerûn, the right spell at the right time is sometimes the difference between life and death. Some of the spells described here are only available to characters who have the proper initiate feat (as indicated in the Level entry of the spell description); some provide extra abilities when prepared by a spellcaster; and others are more effective for sorcerers than members of other classes.","skillPointsPerLevel":"4 + Int modifier"}'::jsonb)
insert into public.catalog_feats (id,feat_type,level,name_pt,name_en,description_pt,prerequisites,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.cov.feat.cov-broken-ones-sacrifice','General',1,'Broken One’s Sacrifice','Broken One’s Sacrifice','As an immediate action, you can intervene on behalf of an adjacent ally (of your size or smaller) who is under attack. When you activate this feat, you and the ally switch spaces. If there is not enough space for this to occur, you can’t activate the feat. Then, you suffer the harmful effect as if you were the intended target; the ally is unaffected by it. In addition to the obvious harmful effect this has upon you, this action is a drain on your personal energy. Once the effect of the intervention is resolved, you become fatigued. You cannot use this feat if you are exhausted or if you are immune to fatigue. You can choose to activate this feat after the success or failure of the harmful effect is determined, but you must activate it before the extent of the effect is determined and/or applied to the ally. Example: If an adjacent ally is attacked, you could wait until after the attack roll (and confirmation roll, if the attack is a critical threat) is made to activate the feat, but you would have to activate it before damage is rolled. If the adjacent creature also benefits from a miss chance, you could wait until after that roll was made to activate the feat. Example: If an adjacent creature is within the area of a lightning bolt spell, you could wait until the creature rolls its saving throw (and checks its spell resistance, if any), but you would have to activate the feat before the spell’s damage is rolled. If an adjacent creature is targeted by an attack that deals a fixed amount of damage, such as a maximized magic missile spell, you would choose to activate this feat after the spell hit the target, but before damage was applied. By activating this feat, you give up any opportunity to avoid the harmful effect normally allowed by a saving throw, spell resistance, AC, or concealment. If the effect allows a saving throw or spell resistance, you automatically fail the save or spell resistance check. If the effect requires an attack roll, it automatically hits you (and if it scored a critical hit, it automatically scores a critical hit on you), even if you would normally benefit from a miss chance against the attack. Any immunities or resistances you have apply normally; for example, if you are immune to critical hits, an attacker can’t score a critical hit on you just because he scored one on the ally. If you can’t physically interact with or manipulate objects (for instance, if you are incorporeal or in gaseous form, or if either you or the ally, but not both of you, are ethereal), you can’t switch places with the ally and thus can’t activate this feat. It should go without saying, but if you are incapable of taking an action (dazed, paralyzed, stunned, unconscious, and so on), you can’t use this feat.','Wis 13, member of the Broken Ones monk order',ARRAY['general']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-broken-ones-sacrifice","name":"Broken One’s Sacrifice","type":"General","prerequisite":"Wis 13, member of the Broken Ones monk order","summary":"Your dedication to Ilmater’s philosophy has given you the power to take attacks directed at others.","benefit":"As an immediate action, you can intervene on behalf of an adjacent ally (of your size or smaller) who is under attack. When you activate this feat, you and the ally switch spaces. If there is not enough space for this to occur, you can’t activate the feat. Then, you suffer the harmful effect as if you were the intended target; the ally is unaffected by it. In addition to the obvious harmful effect this has upon you, this action is a drain on your personal energy. Once the effect of the intervention is resolved, you become fatigued. You cannot use this feat if you are exhausted or if you are immune to fatigue. You can choose to activate this feat after the success or failure of the harmful effect is determined, but you must activate it before the extent of the effect is determined and/or applied to the ally. Example: If an adjacent ally is attacked, you could wait until after the attack roll (and confirmation roll, if the attack is a critical threat) is made to activate the feat, but you would have to activate it before damage is rolled. If the adjacent creature also benefits from a miss chance, you could wait until after that roll was made to activate the feat. Example: If an adjacent creature is within the area of a lightning bolt spell, you could wait until the creature rolls its saving throw (and checks its spell resistance, if any), but you would have to activate the feat before the spell’s damage is rolled. If an adjacent creature is targeted by an attack that deals a fixed amount of damage, such as a maximized magic missile spell, you would choose to activate this feat after the spell hit the target, but before damage was applied. By activating this feat, you give up any opportunity to avoid the harmful effect normally allowed by a saving throw, spell resistance, AC, or concealment. If the effect allows a saving throw or spell resistance, you automatically fail the save or spell resistance check. If the effect requires an attack roll, it automatically hits you (and if it scored a critical hit, it automatically scores a critical hit on you), even if you would normally benefit from a miss chance against the attack. Any immunities or resistances you have apply normally; for example, if you are immune to critical hits, an attacker can’t score a critical hit on you just because he scored one on the ally. If you can’t physically interact with or manipulate objects (for instance, if you are incorporeal or in gaseous form, or if either you or the ally, but not both of you, are ethereal), you can’t switch places with the ally and thus can’t activate this feat. It should go without saying, but if you are incapable of taking an action (dazed, paralyzed, stunned, unconscious, and so on), you can’t use this feat."}'::jsonb),
('dnd35.cov.feat.cov-carmendine-monk','General',1,'Carmendine Monk','Carmendine Monk','You can use your Intelligence bonus instead of your Wisdom bonus for determining your monk AC bonus and for determining the save DC against your stunning fist and quivering palm attacks. You can study your thesis notes for 1 hour to treat your monk level as two higher for determining one of the following monk abilities: unarmed damage, AC bonus, or unarmored speed bonus. This benefit lasts for 24 hours, at which point you can study your notes again to gain the same or a different effect. You can’t study your notes more than once in any 24-hour period.','Int 13, member of Zealots of the Written Word monk order (see page 105)',ARRAY['general']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-carmendine-monk","name":"Carmendine Monk","type":"General","prerequisite":"Int 13, member of Zealots of the Written Word monk order (see page 105)","summary":"You have learned that study is just as important as insight to finding enlightenment.","benefit":"You can use your Intelligence bonus instead of your Wisdom bonus for determining your monk AC bonus and for determining the save DC against your stunning fist and quivering palm attacks. You can study your thesis notes for 1 hour to treat your monk level as two higher for determining one of the following monk abilities: unarmed damage, AC bonus, or unarmored speed bonus. This benefit lasts for 24 hours, at which point you can study your notes again to gain the same or a different effect. You can’t study your notes more than once in any 24-hour period."}'::jsonb),
('dnd35.cov.feat.cov-defender-of-the-homeland','Exalted',1,'Defender of the Homeland','Defender of the Homeland','When fighting in your home region, you gain a +1 sacred bonus to Armor Class and immunity to fear effects.','Wis 13, any good alignment',ARRAY['exalted']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-defender-of-the-homeland","name":"Defender of the Homeland","type":"Exalted","prerequisite":"Wis 13, any good alignment","summary":"You have sworn a sacred oath to protect your country from evil.","benefit":"When fighting in your home region, you gain a +1 sacred bonus to Armor Class and immunity to fear effects."}'::jsonb),
('dnd35.cov.feat.cov-detect-shadow-weave-user','General',1,'Detect Shadow Weave User','Detect Shadow Weave User','Whenever you observe spellcasting or a magical effect you can make a Spellcraft check (DC 15 + spell level) as an immediate action to determine if the effect comes from the Weave or the Shadow Weave. When using detect magic, you automatically identify the Weave or Shadow Weave origin of any aura you detect.','Knowledge (arcana) 5 ranks, Spellcraft 5 ranks',ARRAY['general']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-detect-shadow-weave-user","name":"Detect Shadow Weave User","type":"General","prerequisite":"Knowledge (arcana) 5 ranks, Spellcraft 5 ranks","summary":"You can determine if a magic item or spellcaster is using the Weave or the Shadow Weave.","benefit":"Whenever you observe spellcasting or a magical effect you can make a Spellcraft check (DC 15 + spell level) as an immediate action to determine if the effect comes from the Weave or the Shadow Weave. When using detect magic, you automatically identify the Weave or Shadow Weave origin of any aura you detect."}'::jsonb),
('dnd35.cov.feat.cov-druuth-slayer','General',1,'Druuth Slayer','Druuth Slayer','This feat grants three benefits. First, you get a +1 bonus on Will saving throws. Second, you gain a +10 insight bonus on Spot checks made to recognize a doppelganger using its change shape ability. Third, if affected by a mind flayer’s mind blast, you get a new saving throw every round at the end of your turn to end the stun effect.','Knowledge (dungeoneering) 2 ranks, Knowledge (nature) 2 ranks',ARRAY['general']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-druuth-slayer","name":"Druuth Slayer","type":"General","prerequisite":"Knowledge (dungeoneering) 2 ranks, Knowledge (nature) 2 ranks","summary":"You have studied the lore of the druuth (a cabal of doppelgangers led by a mind flayer) and know how to recognize and resist their powers.","benefit":"This feat grants three benefits. First, you get a +1 bonus on Will saving throws. Second, you gain a +10 insight bonus on Spot checks made to recognize a doppelganger using its change shape ability. Third, if affected by a mind flayer’s mind blast, you get a new saving throw every round at the end of your turn to end the stun effect."}'::jsonb),
('dnd35.cov.feat.cov-duerran-metaform-training','Psionic',1,'Duerran Metaform Training','Duerran Metaform Training','You can expend 5 power points to activate your enlarge person spell-like ability. Though the triggering energy is psionic (and thus can’t be initiated where psionics is unavailable), all other effects work like standard spell-like abilities. Note: This psionic technique was created by the gray dwarf worshipers of Deep Duerra, but other duergar (including exiles) have developed it independently.','Gray dwarf',ARRAY['psionic']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-duerran-metaform-training","name":"Duerran Metaform Training","type":"Psionic","prerequisite":"Gray dwarf","summary":"Your studies have shown you the way to link your psionics and your enlarge person spell-like ability.","benefit":"You can expend 5 power points to activate your enlarge person spell-like ability. Though the triggering energy is psionic (and thus can’t be initiated where psionics is unavailable), all other effects work like standard spell-like abilities. Note: This psionic technique was created by the gray dwarf worshipers of Deep Duerra, but other duergar (including exiles) have developed it independently."}'::jsonb),
('dnd35.cov.feat.cov-duerran-stealth-training','Psionic',1,'Duerran Stealth Training','Duerran Stealth Training','You can expend 5 power points to activate your invisibility spell-like ability. Though the triggering energy is psionic (and thus can’t be initiated where psionics is unavailable), all other effects work like standard spell-like abilities. Note: This psionic technique was created by the gray dwarf worshipers of Deep Duerra, but other duergar (including exiles) have developed it independently.','Gray dwarf',ARRAY['psionic']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-duerran-stealth-training","name":"Duerran Stealth Training","type":"Psionic","prerequisite":"Gray dwarf","summary":"Your studies have shown you the way to link your psionics and your invisibility spell-like ability.","benefit":"You can expend 5 power points to activate your invisibility spell-like ability. Though the triggering energy is psionic (and thus can’t be initiated where psionics is unavailable), all other effects work like standard spell-like abilities. Note: This psionic technique was created by the gray dwarf worshipers of Deep Duerra, but other duergar (including exiles) have developed it independently."}'::jsonb),
('dnd35.cov.feat.cov-from-smite-to-song','General',1,'From Smite to Song','From Smite to Song','You can spend a smite evil attempt to duplicate the effects of the inspire courage bardic music ability (see page 29 of the Player’s Handbook). Your effective bard level (for the purpose of determining the value of the bonuses granted) is equal to your paladin level. Add Perform to your list of paladin class skills.','Perform (any) 3 ranks, member of the Harmonious Order (see page 101)',ARRAY['general']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-from-smite-to-song","name":"From Smite to Song","type":"General","prerequisite":"Perform (any) 3 ranks, member of the Harmonious Order (see page 101)","summary":"You can channel your destructive holy energy into powerful song magic for the glory of Milil.","benefit":"You can spend a smite evil attempt to duplicate the effects of the inspire courage bardic music ability (see page 29 of the Player’s Handbook). Your effective bard level (for the purpose of determining the value of the bonuses granted) is equal to your paladin level. Add Perform to your list of paladin class skills."}'::jsonb),
('dnd35.cov.feat.cov-initiate-of-anhur','Initiate',1,'Initiate of Anhur','Initiate of Anhur','You take no penalty on Listen checks for being distracted or asleep. You can make attacks of opportunity when you are flat-footed as though you had the Combat Reflexes feat. You do not gain extra attacks of opportunity in a round from this ability. In addition, you add the following spells to your cleric or ranger spell list. 1st—bless weapon. 2nd—spiritual weapon (ranger only), thunderstroke (see page 59).','Cleric or ranger 5th, patron deity Anhur',ARRAY['initiate']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-initiate-of-anhur","name":"Initiate of Anhur","type":"Initiate","prerequisite":"Cleric or ranger 5th, patron deity Anhur","summary":"You have been initiated into the greatest secrets of Anhur’s church.","benefit":"You take no penalty on Listen checks for being distracted or asleep. You can make attacks of opportunity when you are flat-footed as though you had the Combat Reflexes feat. You do not gain extra attacks of opportunity in a round from this ability. In addition, you add the following spells to your cleric or ranger spell list. 1st—bless weapon. 2nd—spiritual weapon (ranger only), thunderstroke (see page 59).","normal":"A distracted or sleeping character makes Listen checks with a –5 or –10 penalty, respectively."}'::jsonb),
('dnd35.cov.feat.cov-initiate-of-arvoreen','Initiate',1,'Initiate of Arvoreen','Initiate of Arvoreen','Add Hide and Move Silently to your list of cleric or paladin class skills. In addition, you add the following spells to your cleric or paladin spell list. 1st—enlarge person, low-light visionMag, message. 3rd—blade thirstMag, safe clearingMag.','Halfling, cleric or paladin 4th, patron deity Arvoreen',ARRAY['initiate']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-initiate-of-arvoreen","name":"Initiate of Arvoreen","type":"Initiate","prerequisite":"Halfling, cleric or paladin 4th, patron deity Arvoreen","summary":"You have been initiated into the greatest secrets of Arvoreen’s church.","benefit":"Add Hide and Move Silently to your list of cleric or paladin class skills. In addition, you add the following spells to your cleric or paladin spell list. 1st—enlarge person, low-light visionMag, message. 3rd—blade thirstMag, safe clearingMag."}'::jsonb),
('dnd35.cov.feat.cov-initiate-of-baravar-cloakshadow','Initiate',1,'Initiate of Baravar Cloakshadow','Initiate of Baravar Cloakshadow','You can spend a turn/rebuke attempt as a standard action to recognize all visible illusion effects within 60 feet of you. If the illusion has a save entry that includes “disbelief” (such as silent image), you are immediately awarded an automatically successful save against that illusion. Illusions that have no visible effect (such as invisibility) are not revealed by this action. In addition, you add the following spells to your cleric or paladin spell list. 1st—camouflageMag. 2nd—invisibility, swift invisibility (see page 56). 3rd—displacement. 4th—dimension door.','Gnome, cleric or paladin 4th, patron deity Baravar Cloakshadow',ARRAY['initiate']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-initiate-of-baravar-cloakshadow","name":"Initiate of Baravar Cloakshadow","type":"Initiate","prerequisite":"Gnome, cleric or paladin 4th, patron deity Baravar Cloakshadow","summary":"You have been initiated into the greatest secrets of Baravar Cloakshadow’s church.","benefit":"You can spend a turn/rebuke attempt as a standard action to recognize all visible illusion effects within 60 feet of you. If the illusion has a save entry that includes “disbelief” (such as silent image), you are immediately awarded an automatically successful save against that illusion. Illusions that have no visible effect (such as invisibility) are not revealed by this action. In addition, you add the following spells to your cleric or paladin spell list. 1st—camouflageMag. 2nd—invisibility, swift invisibility (see page 56). 3rd—displacement. 4th—dimension door."}'::jsonb),
('dnd35.cov.feat.cov-initiate-of-eilistraee','Initiate',1,'Initiate of Eilistraee','Initiate of Eilistraee','Once per day, you can spend one of the daily uses of your racial spell-like abilities (dancing lights, darkness, or faerie fire) to produce a magic missile effect (caster level equals class level). In addition, you add the following spells to your cleric or ranger spell list. 1st—Eilistraee’s moonfire (see page 55). 3rd—lesser spellsong (see page 58)†. 6th (cleric only)—spellsong (see page 58).','Drow or half-drow, cleric or ranger 4th, patron deity Eilistraee',ARRAY['initiate']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-initiate-of-eilistraee","name":"Initiate of Eilistraee","type":"Initiate","prerequisite":"Drow or half-drow, cleric or ranger 4th, patron deity Eilistraee","summary":"You have been initiated into the greatest secrets of Eilistraee’s church.","benefit":"Once per day, you can spend one of the daily uses of your racial spell-like abilities (dancing lights, darkness, or faerie fire) to produce a magic missile effect (caster level equals class level). In addition, you add the following spells to your cleric or ranger spell list. 1st—Eilistraee’s moonfire (see page 55). 3rd—lesser spellsong (see page 58)†. 6th (cleric only)—spellsong (see page 58)."}'::jsonb),
('dnd35.cov.feat.cov-initiate-of-the-holy-realm','Initiate',1,'Initiate of the Holy Realm','Initiate of the Holy Realm','You get a +1 sacred bonus on all saving throws while within the Holy Realm or on a quest specifically dedicated to supporting the Holy Realm. In addition, you add the following spells to your cleric, paladin, or ranger spell list. 1st—alarm, handfirePG, horrible taste (see page 56), rose-mantlePG. 2nd—lionheart (see page 56), love bite (see page 56), warningPG.','Cleric, paladin, or ranger 3rd of Chauntea, Helm, Lathander, Nobanion, Selûne, or Sune',ARRAY['initiate']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-initiate-of-the-holy-realm","name":"Initiate of the Holy Realm","type":"Initiate","prerequisite":"Cleric, paladin, or ranger 3rd of Chauntea, Helm, Lathander, Nobanion, Selûne, or Sune","summary":"You have been initiated into the greatest secrets of one of the faiths of the Holy Realm (Chauntea, Helm, Lathander, Selûne, or Sune).","benefit":"You get a +1 sacred bonus on all saving throws while within the Holy Realm or on a quest specifically dedicated to supporting the Holy Realm. In addition, you add the following spells to your cleric, paladin, or ranger spell list. 1st—alarm, handfirePG, horrible taste (see page 56), rose-mantlePG. 2nd—lionheart (see page 56), love bite (see page 56), warningPG."}'::jsonb),
('dnd35.cov.feat.cov-initiate-of-horus-re','Initiate',1,'Initiate of Horus-Re','Initiate of Horus-Re','Once per day, you can use wild shape (as the druid ability) to take the shape of a hawk for 1 hour. This is a supernatural ability. In addition, you add the following spells to your cleric, paladin, or ranger spell list. 1st—command (paladin and ranger only), disk of solar vengeance (see page 54), herald’s callMag. 2nd—stormvoice (see page 59). 3rd—righteous furyMag (cleric only), searing light (paladin and ranger only).','Cleric, paladin, or ranger 4th, patron deity Horus-Re',ARRAY['initiate']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-initiate-of-horus-re","name":"Initiate of Horus-Re","type":"Initiate","prerequisite":"Cleric, paladin, or ranger 4th, patron deity Horus-Re","summary":"You have been initiated into the greatest secrets of Horus-Re’s church.","benefit":"Once per day, you can use wild shape (as the druid ability) to take the shape of a hawk for 1 hour. This is a supernatural ability. In addition, you add the following spells to your cleric, paladin, or ranger spell list. 1st—command (paladin and ranger only), disk of solar vengeance (see page 54), herald’s callMag. 2nd—stormvoice (see page 59). 3rd—righteous furyMag (cleric only), searing light (paladin and ranger only)."}'::jsonb),
('dnd35.cov.feat.cov-initiate-of-milil','Initiate',1,'Initiate of Milil','Initiate of Milil','Your bard, cleric, and paladin levels stack for the purpose of determining which kinds of bardic music you can use (but not any other effect related to bardic music). You must still meet the Perform skill rank requirement to use various kinds of bardic music. In addition, you add the following spells to your cleric or paladin spell list. 1st—harmonyMag. 2nd—dispel silence (see page 54). 3rd—reveilleMag.','Cleric or paladin 4th, Perform (any) 3 ranks, patron deity Milil',ARRAY['initiate']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-initiate-of-milil","name":"Initiate of Milil","type":"Initiate","prerequisite":"Cleric or paladin 4th, Perform (any) 3 ranks, patron deity Milil","summary":"You have been initiated into the greatest secrets of Milil’s church.","benefit":"Your bard, cleric, and paladin levels stack for the purpose of determining which kinds of bardic music you can use (but not any other effect related to bardic music). You must still meet the Perform skill rank requirement to use various kinds of bardic music. In addition, you add the following spells to your cleric or paladin spell list. 1st—harmonyMag. 2nd—dispel silence (see page 54). 3rd—reveilleMag."}'::jsonb),
('dnd35.cov.feat.cov-initiate-of-nobanion','Initiate',1,'Initiate of Nobanion','Initiate of Nobanion','You gain wild empathy (as the druid class feature), usable only on feline and part-feline animals or magical beasts (such as chimeras, dire lions, dire tigers, dragonnes, and man-ticores); your effective druid level for the purpose of making such checks is equal to the sum of your druid, ranger, cleric, and paladin class levels. You also gain the smite power, the supernatural ability to make a single melee attack once per day with a +4 bonus on the attack roll and a bonus on damage equal to the sum of your cleric, druid, ranger, and paladin levels. These bonuses only apply if the attack is made against a follower of Malar or an item of his church; if you accidentally smite a creature or object that doesn’t meet this requirement, the smite has no effect but is still used. You must declare the smite attempt before making the attack. In addition, you add the following spells to your cleric or paladin spell list. 2nd—lionheart (see page 56). 3rd—summon nature’s ally II (lion only). 4th—shout.','Cleric or paladin 4th, patron deity Nobanion',ARRAY['initiate']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-initiate-of-nobanion","name":"Initiate of Nobanion","type":"Initiate","prerequisite":"Cleric or paladin 4th, patron deity Nobanion","summary":"You have been initiated into the greatest secrets of Nobanion’s church.","benefit":"You gain wild empathy (as the druid class feature), usable only on feline and part-feline animals or magical beasts (such as chimeras, dire lions, dire tigers, dragonnes, and man-ticores); your effective druid level for the purpose of making such checks is equal to the sum of your druid, ranger, cleric, and paladin class levels. You also gain the smite power, the supernatural ability to make a single melee attack once per day with a +4 bonus on the attack roll and a bonus on damage equal to the sum of your cleric, druid, ranger, and paladin levels. These bonuses only apply if the attack is made against a follower of Malar or an item of his church; if you accidentally smite a creature or object that doesn’t meet this requirement, the smite has no effect but is still used. You must declare the smite attempt before making the attack. In addition, you add the following spells to your cleric or paladin spell list. 2nd—lionheart (see page 56). 3rd—summon nature’s ally II (lion only). 4th—shout."}'::jsonb),
('dnd35.cov.feat.cov-initiate-of-torm','Initiate',1,'Initiate of Torm','Initiate of Torm','You gain the smite power, the supernatural ability to make a single melee attack once per day with a +4 bonus on the attack roll and a bonus on damage equal to the sum of your cleric, druid, ranger, and paladin levels. These bonuses only apply if the attack is made against a follower of Bane or Cyric (including former incarnations or variants of those deities, such as Bhaal, Myrkul, or Xvim); if you accidentally smite a creature that doesn’t meet this requirement the smite has no effect but is still used. You must declare the smite attempt before making the attack. In addition, you add the following spells to your cleric or paladin spell list. 1st—bless weapon (cleric only), command (paladin only). 4th—hand of TormMag *. *This spell (and others) appeared in Magic of Faerûn with a deity designator, but there was no rule prohibiting its use by other clerics. If you use initiate feats in your game, you should not allow clerics without the appropriate initiate feat to cast those spells. Thus, only characters with the Initiate of Torm feat should be able to cast the hand of Torm spell, even though Magic of Faerûn put it on the cleric and paladin spell lists.','Cleric or paladin 4th, patron deity Torm',ARRAY['initiate']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-initiate-of-torm","name":"Initiate of Torm","type":"Initiate","prerequisite":"Cleric or paladin 4th, patron deity Torm","summary":"You have been initiated into the greatest secrets of Torm’s church.","benefit":"You gain the smite power, the supernatural ability to make a single melee attack once per day with a +4 bonus on the attack roll and a bonus on damage equal to the sum of your cleric, druid, ranger, and paladin levels. These bonuses only apply if the attack is made against a follower of Bane or Cyric (including former incarnations or variants of those deities, such as Bhaal, Myrkul, or Xvim); if you accidentally smite a creature that doesn’t meet this requirement the smite has no effect but is still used. You must declare the smite attempt before making the attack. In addition, you add the following spells to your cleric or paladin spell list. 1st—bless weapon (cleric only), command (paladin only). 4th—hand of TormMag *. *This spell (and others) appeared in Magic of Faerûn with a deity designator, but there was no rule prohibiting its use by other clerics. If you use initiate feats in your game, you should not allow clerics without the appropriate initiate feat to cast those spells. Thus, only characters with the Initiate of Torm feat should be able to cast the hand of Torm spell, even though Magic of Faerûn put it on the cleric and paladin spell lists."}'::jsonb),
('dnd35.cov.feat.cov-initiate-of-tymora','Initiate',1,'Initiate of Tymora','Initiate of Tymora','Once per day, you can add a +5 luck bonus on any attack roll, saving throw, skill check, or ability check you have just made before the DM declares whether the roll results in success or failure. If you have the Luck domain and you use that domain’s power to reroll this attack, save, or check, the luck bonus applies to the reroll as well. In addition, you add the following spells to your cleric or ranger spell list. 1st—fleeting fortune (see page 55). 2nd—favor of Tymora (see page 55).','Cleric or ranger 4th, patron deity Tymora',ARRAY['initiate']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-initiate-of-tymora","name":"Initiate of Tymora","type":"Initiate","prerequisite":"Cleric or ranger 4th, patron deity Tymora","summary":"You have been initiated into the greatest secrets of Tymora’s church.","benefit":"Once per day, you can add a +5 luck bonus on any attack roll, saving throw, skill check, or ability check you have just made before the DM declares whether the roll results in success or failure. If you have the Luck domain and you use that domain’s power to reroll this attack, save, or check, the luck bonus applies to the reroll as well. In addition, you add the following spells to your cleric or ranger spell list. 1st—fleeting fortune (see page 55). 2nd—favor of Tymora (see page 55)."}'::jsonb),
('dnd35.cov.feat.cov-knight-of-the-red-falcon','Exalted',1,'Knight of the Red Falcon','Knight of the Red Falcon','You gain a +1 morale bonus to Armor Class when you are adjacent to more than one enemy. (Helpless enemies don’t count toward this benefit.)','Cleric, fighter, or paladin 4th, member of the Order of the Red Falcon (see page 103)',ARRAY['exalted']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-knight-of-the-red-falcon","name":"Knight of the Red Falcon","type":"Exalted","prerequisite":"Cleric, fighter, or paladin 4th, member of the Order of the Red Falcon (see page 103)","summary":"Your military order has a legendary ability to survive against overwhelming odds.","benefit":"You gain a +1 morale bonus to Armor Class when you are adjacent to more than one enemy. (Helpless enemies don’t count toward this benefit.)"}'::jsonb),
('dnd35.cov.feat.cov-knight-of-the-risen-scepter','Exalted',1,'Knight of the Risen Scepter','Knight of the Risen Scepter','You get a +4 sacred bonus on saving throws against death effects, energy drain, and ability drain. If you are slain by a follower of Set, you come back to life 1 hour later as though resurrection had been cast upon you. Instead of losing a level due to this effect, you gain one negative level. If a follower of Osiris brings you back to life with raise dead, resurrection, or a similar effect that would normally cause you to lose a level, you gain one negative level rather than losing a level. You can gain the negative level bestowed by this feat even if you are normally immune to negative levels. A negative level bestowed by this feat can’t be removed by any normal means (such as restoration), nor does it ever become an actual lost level. Instead, the negative level remains until you next gain a class level, or until you kill or destroy the follower of Set who killed you, at which point it disappears. While you have a negative level bestowed by this feat, you lose all benefits of this feat except the sacred bonus on saving throws.','Paladin or ranger 8th, patron deity Osiris',ARRAY['exalted']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-knight-of-the-risen-scepter","name":"Knight of the Risen Scepter","type":"Exalted","prerequisite":"Paladin or ranger 8th, patron deity Osiris","summary":"Your military order is dedicated to fighting Set and his minions, and even death cannot stop you from this task.","benefit":"You get a +4 sacred bonus on saving throws against death effects, energy drain, and ability drain. If you are slain by a follower of Set, you come back to life 1 hour later as though resurrection had been cast upon you. Instead of losing a level due to this effect, you gain one negative level. If a follower of Osiris brings you back to life with raise dead, resurrection, or a similar effect that would normally cause you to lose a level, you gain one negative level rather than losing a level. You can gain the negative level bestowed by this feat even if you are normally immune to negative levels. A negative level bestowed by this feat can’t be removed by any normal means (such as restoration), nor does it ever become an actual lost level. Instead, the negative level remains until you next gain a class level, or until you kill or destroy the follower of Set who killed you, at which point it disappears. While you have a negative level bestowed by this feat, you lose all benefits of this feat except the sacred bonus on saving throws."}'::jsonb),
('dnd35.cov.feat.cov-knight-of-tyrs-holy-judgment','Exalted',1,'Knight of Tyr’s Holy Judgment','Knight of Tyr’s Holy Judgment','You gain a supernatural ability to sense and understand laws. Add your paladin level to any Knowledge or Intelligence check made regarding laws. You can use this ability even if you are unfamiliar with the local laws or don’t even know where you are. For example, if you use this ability upon approaching the city of Luthcheq in Chessenta, a Knowledge (arcana) or Knowledge (local Chessenta) check reveals to you that arcane magic is forbidden there. If you later end up in a strange land by way of a portal, and a Knowledge (religion) check reveals that Loviatar is the official religion where you are, you realize you are in (for instance) Dambrath. You can use this ability to find loopholes in the law, such as learning that the local temple’s ability to offer a wanted criminal sanctuary only applies from dusk until dawn, allowing you to arrest the criminal after daybreak. When you use your detect evil ability, the second round of use reveals whether or not any creatures in the area are devils, though you do not learn their exact location (but in most cases you can identify them in the third round by the strength of their aura). You gain a +1 sacred bonus to Armor Class against devils.','Int 13, member of the Knights of Holy Judgment (see page 102)',ARRAY['exalted']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-knight-of-tyrs-holy-judgment","name":"Knight of Tyr’s Holy Judgment","type":"Exalted","prerequisite":"Int 13, member of the Knights of Holy Judgment (see page 102)","summary":"You can draw upon the power of Tyr to sense and understand the law and to locate devils.","benefit":"You gain a supernatural ability to sense and understand laws. Add your paladin level to any Knowledge or Intelligence check made regarding laws. You can use this ability even if you are unfamiliar with the local laws or don’t even know where you are. For example, if you use this ability upon approaching the city of Luthcheq in Chessenta, a Knowledge (arcana) or Knowledge (local Chessenta) check reveals to you that arcane magic is forbidden there. If you later end up in a strange land by way of a portal, and a Knowledge (religion) check reveals that Loviatar is the official religion where you are, you realize you are in (for instance) Dambrath. You can use this ability to find loopholes in the law, such as learning that the local temple’s ability to offer a wanted criminal sanctuary only applies from dusk until dawn, allowing you to arrest the criminal after daybreak. When you use your detect evil ability, the second round of use reveals whether or not any creatures in the area are devils, though you do not learn their exact location (but in most cases you can identify them in the third round by the strength of their aura). You gain a +1 sacred bonus to Armor Class against devils."}'::jsonb),
('dnd35.cov.feat.cov-knight-of-tyrs-merciful-sword','Exalted',1,'Knight of Tyr’s Merciful Sword','Knight of Tyr’s Merciful Sword','You gain the supernatural ability to sense injustice and great evil. Once per week as a standard action, you can concentrate to sense the direction of the greatest injustice or evil within 1 mile of you (DM’s determination). Alternatively, you can meditate for 8 hours to expand your range to 10 miles for that use of the feat. Murder, treason, and the presence of evil outsiders rank highest with this sense, while other crimes, injustices, and evil creatures rank lower, similar to the aura strengths listed in the detect evil spell. You gain a +1 sacred bonus to Armor Class against demons.','Wis 13, member of the Knights of the Merciful Sword (see page 102)',ARRAY['exalted']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-knight-of-tyrs-merciful-sword","name":"Knight of Tyr’s Merciful Sword","type":"Exalted","prerequisite":"Wis 13, member of the Knights of the Merciful Sword (see page 102)","summary":"You can draw upon the power of Tyr to sense where you are needed.","benefit":"You gain the supernatural ability to sense injustice and great evil. Once per week as a standard action, you can concentrate to sense the direction of the greatest injustice or evil within 1 mile of you (DM’s determination). Alternatively, you can meditate for 8 hours to expand your range to 10 miles for that use of the feat. Murder, treason, and the presence of evil outsiders rank highest with this sense, while other crimes, injustices, and evil creatures rank lower, similar to the aura strengths listed in the detect evil spell. You gain a +1 sacred bonus to Armor Class against demons."}'::jsonb),
('dnd35.cov.feat.cov-mark-of-the-triad','Divine',1,'Mark of the Triad','Mark of the Triad','You can spend a turn undead attempt as a swift action and imbue a greatsword, longsword, or unarmed strike with either the axiomatic or holy special ability (see page 223 and 225 of the Dungeon Master’s Guide, respectively). The effect lasts until the start of your next turn.','Initiate of IlmaterPG, Initiate of Torm (see page 31), or Initiate of TyrPG',ARRAY['divine']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-mark-of-the-triad","name":"Mark of the Triad","type":"Divine","prerequisite":"Initiate of IlmaterPG, Initiate of Torm (see page 31), or Initiate of TyrPG","summary":"You have been initiated into the greatest secrets of the Triad, the godly triumvirate of Tyr, Torm, and Ilmater.","benefit":"You can spend a turn undead attempt as a swift action and imbue a greatsword, longsword, or unarmed strike with either the axiomatic or holy special ability (see page 223 and 225 of the Dungeon Master’s Guide, respectively). The effect lasts until the start of your next turn."}'::jsonb),
('dnd35.cov.feat.cov-overcome-shadow-weave','General',1,'Overcome Shadow Weave','Overcome Shadow Weave','You get a +5 bonus on caster level checks to detect, counterspell, and dispel Shadow Weave effects. You get a +1 bonus on Will saving throws against Shadow Weave effects.','Knowledge (arcana) 5 ranks, Spellcraft 5 ranks, spellcaster who uses the Weave',ARRAY['general']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-overcome-shadow-weave","name":"Overcome Shadow Weave","type":"General","prerequisite":"Knowledge (arcana) 5 ranks, Spellcraft 5 ranks, spellcaster who uses the Weave","summary":"You understand the strengths and weaknesses of the Shadow Weave and are more resistant to its tricks.","benefit":"You get a +5 bonus on caster level checks to detect, counterspell, and dispel Shadow Weave effects. You get a +1 bonus on Will saving throws against Shadow Weave effects."}'::jsonb),
('dnd35.cov.feat.cov-paladin-of-the-noble-heart','Exalted',1,'Paladin of the Noble Heart','Paladin of the Noble Heart','You get one extra smite evil attempt per day that can only be used on followers of Loviatar or items of her church. You get a +1 sacred bonus on Fortitude saves against effects created by followers of Loviatar.','Knowledge (religion) 4 ranks, member of the Companions of the Noble Heart (see page 100)',ARRAY['exalted']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-paladin-of-the-noble-heart","name":"Paladin of the Noble Heart","type":"Exalted","prerequisite":"Knowledge (religion) 4 ranks, member of the Companions of the Noble Heart (see page 100)","summary":"You are tasked by Ilmater to eliminate cruelty from the world, particularly that of Loviatar.","benefit":"You get one extra smite evil attempt per day that can only be used on followers of Loviatar or items of her church. You get a +1 sacred bonus on Fortitude saves against effects created by followers of Loviatar."}'::jsonb),
('dnd35.cov.feat.cov-silver-blood','General',1,'Silver Blood','Silver Blood','You cannot be infected with lycanthropy. Any lycanthrope that bites you must make a Fortitude save (DC 10 + 1/2 your Hit Dice + your Con modifier) or take damage equal to your Constitution modifier (minimum 1 point). This damage is treated as silver for the purpose of overcoming a lycanthrope’s damage reduction.','Base Fortitude save +2',ARRAY['general']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-silver-blood","name":"Silver Blood","type":"General","prerequisite":"Base Fortitude save +2","summary":"You have magically or alchemically imbued your flesh and blood with silver, making you resistant to lycanthrope attacks.","benefit":"You cannot be infected with lycanthropy. Any lycanthrope that bites you must make a Fortitude save (DC 10 + 1/2 your Hit Dice + your Con modifier) or take damage equal to your Constitution modifier (minimum 1 point). This damage is treated as silver for the purpose of overcoming a lycanthrope’s damage reduction.","special":"If you are already an afflicted lycanthrope, the DCs for your Control Shape checks increase by 5 and you lose your lycanthrope damage reduction. If you are already a natural lycanthrope, you must make a DC 15 Control Shape check to change form and your lycanthrope damage reduction decreases to 5/silver."}'::jsonb),
('dnd35.cov.feat.cov-silver-fang','General',1,'Silver Fang','Silver Fang','Your natural attacks and unarmed strikes count as silver weapons for the purpose of overcoming damage reduction.','Base Fortitude save +4, member or ally of the Fangshields (see page 78)',ARRAY['general']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-silver-fang","name":"Silver Fang","type":"General","prerequisite":"Base Fortitude save +4, member or ally of the Fangshields (see page 78)","summary":"By following a ritual taught by the Fangshields, your natural attacks are suffused with the power of silver and are fully effective against lycanthropes.","benefit":"Your natural attacks and unarmed strikes count as silver weapons for the purpose of overcoming damage reduction.","special":"If you are a lycanthrope, your natural attacks no longer infect others with lycanthropy."}'::jsonb),
('dnd35.cov.feat.cov-smiting-power','General',1,'Smiting Power','Smiting Power','You can use your smite ability (whether smite evil or from some other source) when making a bull rush or overrun attempt. If your smite ability would normally grant a bonus on your attack roll against the target of your bull rush or overrun, you can add this bonus to your Strength check instead. In addition, if you win the opposed check to bull rush or overrun the target, you deal damage to the target equal to the bonus the smite would grant on a damage roll against that creature. You must announce the smite attempt before starting the bull rush or overrun. If your smite attempt would not grant a bonus against the target of your bull rush or overrun attempt (for instance, if you used smite evil when bull rushing a non-evil creature), the attempt is wasted to no effect.','Power Attack, ability to smite',ARRAY['general']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-smiting-power","name":"Smiting Power","type":"General","prerequisite":"Power Attack, ability to smite","summary":"You use your smite ability to augment other combat maneuvers.","benefit":"You can use your smite ability (whether smite evil or from some other source) when making a bull rush or overrun attempt. If your smite ability would normally grant a bonus on your attack roll against the target of your bull rush or overrun, you can add this bonus to your Strength check instead. In addition, if you win the opposed check to bull rush or overrun the target, you deal damage to the target equal to the bonus the smite would grant on a damage roll against that creature. You must announce the smite attempt before starting the bull rush or overrun. If your smite attempt would not grant a bonus against the target of your bull rush or overrun attempt (for instance, if you used smite evil when bull rushing a non-evil creature), the attempt is wasted to no effect."}'::jsonb),
('dnd35.cov.feat.cov-sword-of-the-arcane-order','General',1,'Sword of the Arcane Order','Sword of the Arcane Order','You can use your paladin and ranger spell slots to prepare wizard spells. You must have a minimum Intelligence score of 10 + the spell’s level to prepare it, and the save DC of the spell is equal to 10 + your Int modifier (as if you were a wizard). These wizard spells can be taken either from your spellbook (if you have one) or from another character’s spellbook (though in the latter case you must decipher the writing in the book and succeed on a Spellcraft check to prepare the spell, just as a wizard using a borrowed spellbook; see Wizard Spells and Borrowed Spellbooks, page 178 of the Player’s Handbook, for details). If you also have levels in wizard, your wizard caster level is treated as the sum of your wizard, paladin, and ranger class levels.','Paladin 4th of Azuth or Mystra, or ranger 4th of Mystra; member of the Knights of the Mystic Fire (see page 102), the Order of the Shooting Star (see Knights of the Mystic Fire, page 102), or the Swords of the High One (see page 104)',ARRAY['general']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-sword-of-the-arcane-order","name":"Sword of the Arcane Order","type":"General","prerequisite":"Paladin 4th of Azuth or Mystra, or ranger 4th of Mystra; member of the Knights of the Mystic Fire (see page 102), the Order of the Shooting Star (see Knights of the Mystic Fire, page 102), or the Swords of the High One (see page 104)","summary":"Members of your military order have a special connection with arcane magic.","benefit":"You can use your paladin and ranger spell slots to prepare wizard spells. You must have a minimum Intelligence score of 10 + the spell’s level to prepare it, and the save DC of the spell is equal to 10 + your Int modifier (as if you were a wizard). These wizard spells can be taken either from your spellbook (if you have one) or from another character’s spellbook (though in the latter case you must decipher the writing in the book and succeed on a Spellcraft check to prepare the spell, just as a wizard using a borrowed spellbook; see Wizard Spells and Borrowed Spellbooks, page 178 of the Player’s Handbook, for details). If you also have levels in wizard, your wizard caster level is treated as the sum of your wizard, paladin, and ranger class levels.","special":"Azuth has a paladin order called the Swords of the High One. Mystra has a paladin order called the Knights of the Mystic Fire and a closely allied group of rangers called the Order of the Shooting Star. Members of all three of these groups can select this feat as long as they are at least 4th level in their respective order’s primary class."}'::jsonb),
('dnd35.cov.feat.cov-sun-soul-monk','General',1,'Sun Soul Monk','Sun Soul Monk','This feat’s benefit depends on the patron deity of the monastery where you studied. Lathander: You can channel your ki to turn an undead creature. Once per day you can choose to imbue a single unarmed strike with ki; this decision must be made before the attack roll is made. If you hit an undead creature with this attack, it is turned unless it succeeds on a Will save (DC 10 + 1/2 your HD + your Wis modifier). If the undead creature has turn resistance, it can add this as a bonus on its save. If you have the Stunning Fist feat, you can also expend a daily use of your stunning fist to use this feat. If you have the turn undead class feature, you can expend a turn undead attempt to use this feat. Selûne: Your unarmed strikes deal an extra 1 point of cold damage and count as silvered weapons for the purpose of overcoming damage reduction. When in moonlight or starlight, treat your monk level as three levels higher for the purpose of determining your unarmored speed bonus. Sune: Your combat style is fascinating to watch. Once per day as a standard action, you can perform a maneuver that fascinates a single creature within 30 feet that can see you (Will negates; save DC 10 + 1/2 your HD + Cha modifier). Creatures of a type different from your gain a +4 bonus on the save. This supernatural effect lasts for 1 round. If you have the Stunning Fist feat, you can also expend a daily use of your stunning fist to use this feat.','Monk 6th, member of the Sun Soul monk order (see page 25 of the FORGOTTEN REALMS Campaign Setting and page 41 of City of Splendors: Waterdeep)',ARRAY['general']::text[],'v35-cov','D&D 3.5 — Champions of Valor',27,'dnd35','{"id":"cov-sun-soul-monk","name":"Sun Soul Monk","type":"General","prerequisite":"Monk 6th, member of the Sun Soul monk order (see page 25 of the FORGOTTEN REALMS Campaign Setting and page 41 of City of Splendors: Waterdeep)","summary":"Your training with this monk order gives you special powers depending on which sect you follow.","benefit":"This feat’s benefit depends on the patron deity of the monastery where you studied. Lathander: You can channel your ki to turn an undead creature. Once per day you can choose to imbue a single unarmed strike with ki; this decision must be made before the attack roll is made. If you hit an undead creature with this attack, it is turned unless it succeeds on a Will save (DC 10 + 1/2 your HD + your Wis modifier). If the undead creature has turn resistance, it can add this as a bonus on its save. If you have the Stunning Fist feat, you can also expend a daily use of your stunning fist to use this feat. If you have the turn undead class feature, you can expend a turn undead attempt to use this feat. Selûne: Your unarmed strikes deal an extra 1 point of cold damage and count as silvered weapons for the purpose of overcoming damage reduction. When in moonlight or starlight, treat your monk level as three levels higher for the purpose of determining your unarmored speed bonus. Sune: Your combat style is fascinating to watch. Once per day as a standard action, you can perform a maneuver that fascinates a single creature within 30 feet that can see you (Will negates; save DC 10 + 1/2 your HD + Cha modifier). Creatures of a type different from your gain a +4 bonus on the save. This supernatural effect lasts for 1 round. If you have the Stunning Fist feat, you can also expend a daily use of your stunning fist to use this feat."}'::jsonb)
insert into public.catalog_spells (id,name_pt,name_en,description_pt,rank,is_cantrip,is_focus,traditions,cast_actions,range,targets,duration,defense,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.cov.spell.cov-animate-with-the-spirit','Animate With the Spirit','Animate With the Spirit','By casting this spell, you request your deity to send you the spirit of a good-aligned outsider (of 6 HD or less) of the deity’s choice to inhabit a corpse within range, which becomes animated by the spirit. If you serve no particular deity, the spell is a general plea answered by a creature sharing your philosophical alignment. If you know an individual creature’s name, you can request that individual by speaking the name during the spell (though you might get a different creature anyway). The Hit Dice of the corpse to be animated (not counting class levels) cannot exceed your caster level. The possessed body attacks your opponents to the best of its ability. If you can communicate with the possessing spirit, you can direct it not to attack, to attack particular enemies, or to perform other actions. While the body is inhabited by the spirit, it is treated as if were still alive but possessed. It uses the outsider’s Intelligence, Wisdom, Charisma, base attack bonus, base save bonuses, alignment, mental abilities, and any class levels it might have. The body regains the Strength, Dexterity, Constitution, hit points, and innate abilities of the creature the corpse represented when it was alive. For example, a sahuagin’s body breathes water and a troll’s body regenerates. The spirit can’t choose to activate the host body’s extraordinary or supernatural abilities, and the host body’s spells and spell-like abilities do not stay with the body. The spirit remains within the body until the spell is dismissed, the duration ends, or the host body is slain, at which point it returns to its original body with no ill effects. A celestial fortress makes an ideal refuge for great heroes Sacrifice Component: 1d3 points of Strength drain.',4,false,false,ARRAY['sanctified']::text[],'10 minutes','Medium (100 ft. + 10 ft./level)','One corpse with HD equal to or less than your caster level','10 minutes/level (D)','None',ARRAY['Conjuration','Good']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-animate-with-the-spirit","name":"Animate With the Spirit","school":"Conjuration","subschool":"Summoning","descriptors":["Good"],"schoolLine":"Conjuration (Summoning) [Good]","levels":{"sanctified":4},"levelLine":"Sanctified 4","components":"V, S, DF, sacrifice","castingTime":"10 minutes","range":"Medium (100 ft. + 10 ft./level)","duration":"10 minutes/level (D)","savingThrow":"None","spellResistance":"No","targetLabel":"Target","target":"One corpse with HD equal to or less than your caster level","sacrificeComponent":"1d3 points of Strength drain.","description":"By casting this spell, you request your deity to send you the spirit of a good-aligned outsider (of 6 HD or less) of the deity’s choice to inhabit a corpse within range, which becomes animated by the spirit. If you serve no particular deity, the spell is a general plea answered by a creature sharing your philosophical alignment. If you know an individual creature’s name, you can request that individual by speaking the name during the spell (though you might get a different creature anyway). The Hit Dice of the corpse to be animated (not counting class levels) cannot exceed your caster level. The possessed body attacks your opponents to the best of its ability. If you can communicate with the possessing spirit, you can direct it not to attack, to attack particular enemies, or to perform other actions. While the body is inhabited by the spirit, it is treated as if were still alive but possessed. It uses the outsider’s Intelligence, Wisdom, Charisma, base attack bonus, base save bonuses, alignment, mental abilities, and any class levels it might have. The body regains the Strength, Dexterity, Constitution, hit points, and innate abilities of the creature the corpse represented when it was alive. For example, a sahuagin’s body breathes water and a troll’s body regenerates. The spirit can’t choose to activate the host body’s extraordinary or supernatural abilities, and the host body’s spells and spell-like abilities do not stay with the body. The spirit remains within the body until the spell is dismissed, the duration ends, or the host body is slain, at which point it returns to its original body with no ill effects. A celestial fortress makes an ideal refuge for great heroes Sacrifice Component: 1d3 points of Strength drain."}'::jsonb),
('dnd35.cov.spell.cov-benign-projection','Benign Projection','Benign Projection','This spell functions like project image, except as noted above and as follows. You can create an image of your entire body or just your face, and you can cause it to shed light as a candle at will. It can only mimic your actions and speech (you cannot direct it to perform other actions). The image can cast spells only from the schools of abjuration, divination, and conjuration (healing). Sacrifice Component: 1d2 points of Strength damage.',6,false,false,ARRAY['sanctified']::text[],null,'See text',null,null,null,ARRAY['Illusion']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-benign-projection","name":"Benign Projection","school":"Illusion","subschool":"Shadow","descriptors":[],"schoolLine":"Illusion (Shadow)","levels":{"sanctified":6},"levelLine":"Sanctified 6","components":"V, S, DF, sacrifice","range":"See text","sacrificeComponent":"1d2 points of Strength damage.","description":"This spell functions like project image, except as noted above and as follows. You can create an image of your entire body or just your face, and you can cause it to shed light as a candle at will. It can only mimic your actions and speech (you cannot direct it to perform other actions). The image can cast spells only from the schools of abjuration, divination, and conjuration (healing). Sacrifice Component: 1d2 points of Strength damage."}'::jsonb),
('dnd35.cov.spell.cov-celestial-fortress','Celestial Fortress','Celestial Fortress','This spell functions like Leomund’s secure shelter, except as noted above and as follows. The structure is a simple flat-roofed fort rather than a cottage. It has a sturdy door and a fireplace but no windows; access to the roof is through a ladder and a sturdy hatch. The fortress resonates with the power of your deity’s home plane, and it is protected by consecrate and magic circle against evil. The fortress’s appearance reflects your deity and deity’s realm. For example, Mystra’s forts created by this spell look like high-fantasy castles, those of Mulhorandi deities look native to their land, those of dwarven deities look very dwarflike, and so on. Sacrifice Component: 1d2 points of Constitution damage.',4,false,false,ARRAY['sanctified']::text[],null,null,null,null,null,ARRAY['Conjuration']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-celestial-fortress","name":"Celestial Fortress","school":"Conjuration","subschool":"Creation","descriptors":[],"schoolLine":"Conjuration (Creation)","levels":{"sanctified":4},"levelLine":"Sanctified 4","components":"V, S, DF, sacrifice","sacrificeComponent":"1d2 points of Constitution damage.","description":"This spell functions like Leomund’s secure shelter, except as noted above and as follows. The structure is a simple flat-roofed fort rather than a cottage. It has a sturdy door and a fireplace but no windows; access to the roof is through a ladder and a sturdy hatch. The fortress resonates with the power of your deity’s home plane, and it is protected by consecrate and magic circle against evil. The fortress’s appearance reflects your deity and deity’s realm. For example, Mystra’s forts created by this spell look like high-fantasy castles, those of Mulhorandi deities look native to their land, those of dwarven deities look very dwarflike, and so on. Sacrifice Component: 1d2 points of Constitution damage."}'::jsonb),
('dnd35.cov.spell.cov-convert-wand','Convert Wand','Convert Wand','This spell temporarily transforms a magic wand of any type into a healing wand with the same number of charges remaining. At the end of the spell’s duration, the wand’s original properties are restored, and any charges that were drained remain so. The spell level of the wand determines how powerful a healing instrument the wand becomes: Spell Level New Wand Type 1st Wand of cure light wounds 2nd Wand of cure moderate wounds 3rd Wand of cure serious wounds 4th Wand of cure critical wounds For example, a 10th-level cleric can transform a wand of lightning bolt (3rd-level spell) into a wand of cure serious wounds for 10 minutes.',5,false,false,ARRAY['cleric']::text[],'1 standard action','Touch','Wand touched','1 minute/level','None',ARRAY['Transmutation']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-convert-wand","name":"Convert Wand","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"cleric":5},"levelLine":"Cleric 5","components":"V, S","castingTime":"1 standard action","range":"Touch","duration":"1 minute/level","savingThrow":"None","spellResistance":"No","targetLabel":"Target","target":"Wand touched","description":"This spell temporarily transforms a magic wand of any type into a healing wand with the same number of charges remaining. At the end of the spell’s duration, the wand’s original properties are restored, and any charges that were drained remain so. The spell level of the wand determines how powerful a healing instrument the wand becomes: Spell Level New Wand Type 1st Wand of cure light wounds 2nd Wand of cure moderate wounds 3rd Wand of cure serious wounds 4th Wand of cure critical wounds For example, a 10th-level cleric can transform a wand of lightning bolt (3rd-level spell) into a wand of cure serious wounds for 10 minutes."}'::jsonb),
('dnd35.cov.spell.cov-create-lantern-archon','Create Lantern Archon','Create Lantern Archon','You sacrifice a small part of your own life force to create a new lantern archon (see page 16 of the Monster Manual) in the service of your patron. The lantern archon is not under your control but is friendly to you. It willingly performs one nonhazardous task of your choice taking up to 1 hour without requiring any payment. Alternatively, you can request that it perform a hazardous or longer task, but in this case payment is required—see lesser planar ally, page 261 of the Player’s Handbook, for details on tasks and payment. Upon completion of the task, the lantern archon is magically transported to your deity’s home plane. Sacrifice Component: 1d2 points of Constitution drain.',3,false,false,ARRAY['sanctified']::text[],'1 hour','Close (25 ft. + 5 ft./2 levels)','One lantern archon','Instantaneous','None',ARRAY['Conjuration','Good','Light']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-create-lantern-archon","name":"Create Lantern Archon","school":"Conjuration","subschool":"Creation","descriptors":["Good","Light"],"schoolLine":"Conjuration (Creation) [Good, Light]","levels":{"sanctified":3},"levelLine":"Sanctified 3","components":"V, S, DF, sacrifice","castingTime":"1 hour","range":"Close (25 ft. + 5 ft./2 levels)","duration":"Instantaneous","savingThrow":"None","spellResistance":"No","targetLabel":"Effect","target":"One lantern archon","sacrificeComponent":"1d2 points of Constitution drain.","description":"You sacrifice a small part of your own life force to create a new lantern archon (see page 16 of the Monster Manual) in the service of your patron. The lantern archon is not under your control but is friendly to you. It willingly performs one nonhazardous task of your choice taking up to 1 hour without requiring any payment. Alternatively, you can request that it perform a hazardous or longer task, but in this case payment is required—see lesser planar ally, page 261 of the Player’s Handbook, for details on tasks and payment. Upon completion of the task, the lantern archon is magically transported to your deity’s home plane. Sacrifice Component: 1d2 points of Constitution drain."}'::jsonb),
('dnd35.cov.spell.cov-dawnshroud','Dawnshroud','Dawnshroud','You cause the target to glow with the rosy light of the dawn. In addition to acting as a daylight spell, the light is harmful to oozes and undead. When the spell is cast, and at the beginning of each of your turns thereafter, such creatures take 1d6 points of damage if within the bright light of the spell (out to 60 feet) or 1 point of damage per round if within the shadowy illumination of the spell (more than 60 feet, out to 120 feet). If the subject is touched by such a creature using a touch attack, or if it hits the subject with a natural weapon or unarmed strike, it takes 1d6 points of damage + 1 point per caster level (maximum 1d6+15), with a Will saving throw for half damage. If you cast this spell on yourself, you can suppress or restore this light as a free action once each round. This spell was created by clerics of the church of Lathander, but they do not try to restrict its use to only those of their faith.',5,false,false,ARRAY['cleric','druid']::text[],'1 standard action','Touch','Willing creature touched','10 minutes/level (D)','Will half; see text',ARRAY['Evocation','Light']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-dawnshroud","name":"Dawnshroud","school":"Evocation","subschool":null,"descriptors":["Light"],"schoolLine":"Evocation [Light]","levels":{"cleric":5,"druid":5},"levelLine":"Cleric 5, druid 5","components":"V, S, DF","castingTime":"1 standard action","range":"Touch","duration":"10 minutes/level (D)","savingThrow":"Will half; see text","spellResistance":"Yes","targetLabel":"Target","target":"Willing creature touched","description":"You cause the target to glow with the rosy light of the dawn. In addition to acting as a daylight spell, the light is harmful to oozes and undead. When the spell is cast, and at the beginning of each of your turns thereafter, such creatures take 1d6 points of damage if within the bright light of the spell (out to 60 feet) or 1 point of damage per round if within the shadowy illumination of the spell (more than 60 feet, out to 120 feet). If the subject is touched by such a creature using a touch attack, or if it hits the subject with a natural weapon or unarmed strike, it takes 1d6 points of damage + 1 point per caster level (maximum 1d6+15), with a Will saving throw for half damage. If you cast this spell on yourself, you can suppress or restore this light as a free action once each round. This spell was created by clerics of the church of Lathander, but they do not try to restrict its use to only those of their faith."}'::jsonb),
('dnd35.cov.spell.cov-disk-of-solar-vengeance','Disk of Solar Vengeance','Disk of Solar Vengeance','This spell creates a disk of sunlike flames behind your head. The flames give you resistance to cold 5. In addition, if any creature strikes you with a natural attack, an unarmed strike, or a melee weapon that is not a reach weapon, it takes 1d6 points of fire damage +1 point per caster level (maximum +5) after dealing its normal damage to you. This instantly discharges the spell. If the attacker has spell resistance, it applies to this effect. Creatures wielding reach weapons, such as longspears, trigger this effect but are not subject to this damage if they attack you. You can also use the spell to attack as if it were a touch spell (a successful hit discharges the spell).',1,false,false,ARRAY['initiate-of-horus-re']::text[],'1 swift action','Personal','You','1 round/level or until discharged (D)',null,ARRAY['Evocation','Fire']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-disk-of-solar-vengeance","name":"Disk of Solar Vengeance","school":"Evocation","subschool":null,"descriptors":["Fire"],"schoolLine":"Evocation [Fire]","levels":{"initiate-of-horus-re":1},"levelLine":"Initiate of Horus-Re 1","components":"V, S, DF","castingTime":"1 swift action","range":"Personal","duration":"1 round/level or until discharged (D)","targetLabel":"Target","target":"You","description":"This spell creates a disk of sunlike flames behind your head. The flames give you resistance to cold 5. In addition, if any creature strikes you with a natural attack, an unarmed strike, or a melee weapon that is not a reach weapon, it takes 1d6 points of fire damage +1 point per caster level (maximum +5) after dealing its normal damage to you. This instantly discharges the spell. If the attacker has spell resistance, it applies to this effect. Creatures wielding reach weapons, such as longspears, trigger this effect but are not subject to this damage if they attack you. You can also use the spell to attack as if it were a touch spell (a successful hit discharges the spell)."}'::jsonb),
('dnd35.cov.spell.cov-dispel-silence','Dispel Silence','Dispel Silence','This spell functions like dispel magic, except as noted above and that it only works against effects that create an area of silence (silence, Khelben’s suspended silence, and so on). While you have this spell prepared, you gain a +2 competence bonus on Listen checks.',2,false,false,ARRAY['initiate-of-milil']::text[],'1 immediate action',null,'One silence effect',null,null,ARRAY['Abjuration']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-dispel-silence","name":"Dispel Silence","school":"Abjuration","subschool":null,"descriptors":[],"schoolLine":"Abjuration","levels":{"initiate-of-milil":2},"levelLine":"Initiate of Milil 2","components":"S, DF","castingTime":"1 immediate action","targetLabel":"Target or Area","target":"One silence effect","description":"This spell functions like dispel magic, except as noted above and that it only works against effects that create an area of silence (silence, Khelben’s suspended silence, and so on). While you have this spell prepared, you gain a +2 competence bonus on Listen checks."}'::jsonb),
('dnd35.cov.spell.cov-eilistraees-moonfire','Eilistraee’s Moonfire','Eilistraee’s Moonfire','You surround your hand or some other part of your body with light resembling moonlight. You can change the intensity from a faint glow equivalent to a candle to a clear, bright light equivalent to a torch. It varies in color as you desire, whether blue-white, soft green, white, or silver. You can use this moonfire as a melee touch attack that deals 2d6 points of cold damage +1 point per caster level (maximum +5). Whether or not the attack hits, the spell effect is discharged. You can cause the moonlight to leave your body and move about as a single light similar to dancing lights. Once it leaves your body, the effect’s duration is 1 minute per level, and the effect can no longer be used to attack.',1,false,false,ARRAY['initiate-of-eilistraee']::text[],'1 standard action','Touch','Creature touched','1 minute/level or until discharged; see text','None',ARRAY['Evocation','Light']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-eilistraees-moonfire","name":"Eilistraee’s Moonfire","school":"Evocation","subschool":null,"descriptors":["Light"],"schoolLine":"Evocation [Light]","levels":{"initiate-of-eilistraee":1},"levelLine":"Initiate of Eilistraee 1","components":"V, S","castingTime":"1 standard action","range":"Touch","duration":"1 minute/level or until discharged; see text","savingThrow":"None","spellResistance":"Yes","targetLabel":"Target","target":"Creature touched","description":"You surround your hand or some other part of your body with light resembling moonlight. You can change the intensity from a faint glow equivalent to a candle to a clear, bright light equivalent to a torch. It varies in color as you desire, whether blue-white, soft green, white, or silver. You can use this moonfire as a melee touch attack that deals 2d6 points of cold damage +1 point per caster level (maximum +5). Whether or not the attack hits, the spell effect is discharged. You can cause the moonlight to leave your body and move about as a single light similar to dancing lights. Once it leaves your body, the effect’s duration is 1 minute per level, and the effect can no longer be used to attack."}'::jsonb),
('dnd35.cov.spell.cov-favor-of-tymora','Favor of Tymora','Favor of Tymora','This spell creates a glistening aura of golden magical energy around the target creature. The creature gains a +2 luck bonus to AC. Focus: A gold piece.',2,false,false,ARRAY['initiate-of-tymora']::text[],'1 immediate action','Close (25 ft. + 5 ft./2 levels)','One creature','1 round/3 levels','Will negates (harmless)',ARRAY['Abjuration']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-favor-of-tymora","name":"Favor of Tymora","school":"Abjuration","subschool":null,"descriptors":[],"schoolLine":"Abjuration","levels":{"initiate-of-tymora":2},"levelLine":"Initiate of Tymora 2","components":"V, S, F","castingTime":"1 immediate action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"1 round/3 levels","savingThrow":"Will negates (harmless)","spellResistance":"Yes (harmless)","targetLabel":"Target","target":"One creature","description":"This spell creates a glistening aura of golden magical energy around the target creature. The creature gains a +2 luck bonus to AC. Focus: A gold piece."}'::jsonb),
('dnd35.cov.spell.cov-faith-healing-wand','Faith Healing Wand','Faith Healing Wand','This spell functions like convert wand (see page 53), except you always transform the wand into a wand of faith healingMag, no matter what spell the wand normally contains.',3,false,false,ARRAY['cleric']::text[],null,null,null,null,null,ARRAY['Transmutation']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-faith-healing-wand","name":"Faith Healing Wand","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"cleric":3},"levelLine":"Cleric 3","description":"This spell functions like convert wand (see page 53), except you always transform the wand into a wand of faith healingMag, no matter what spell the wand normally contains."}'::jsonb),
('dnd35.cov.spell.cov-fleeting-fortune','Fleeting Fortune','Fleeting Fortune','You imbue the subject with a bit of Tymora’s luck, granting her a +5 luck bonus on a single skill check of her choice. Activating the luck bonus requires no action but must be declared before the skill check is rolled.',1,false,false,ARRAY['initiate-of-tymora']::text[],'1 immediate action','Close (25 ft. + 5 ft./2 levels)','One creature','1 round or until discharged','Yes (harmless)',ARRAY['Transmutation']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-fleeting-fortune","name":"Fleeting Fortune","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"initiate-of-tymora":1},"levelLine":"Initiate of Tymora 1","components":"V, S, DF","castingTime":"1 immediate action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"1 round or until discharged","savingThrow":"Yes (harmless)","spellResistance":"Yes (harmless)","targetLabel":"Target","target":"One creature","description":"You imbue the subject with a bit of Tymora’s luck, granting her a +5 luck bonus on a single skill check of her choice. Activating the luck bonus requires no action but must be declared before the skill check is rolled."}'::jsonb),
('dnd35.cov.spell.cov-golden-dragonmail','Golden Dragonmail','Golden Dragonmail','You create a suit of shining golden full plate around your body. The armor is etched with a dragonscale pattern, an image of a gold dragon, or Torm’s holy symbol (your choice when you cast the spell). It is treated as +1 mithral full plate for all purposes (including arcane spell failure chance), and you are treated as proficient with this armor. Removing or destroying the armor dismisses the spell. This spell has no effect if you are already wearing armor. Torm the True is served by gold and silver dragons, and some of these dragons are the founders of ancient sorcerer bloodlines among the younger races. If you are a sorcerer, the armor also gives you resistance to fire 10. Focus: A gold coin and a piece of mithral in the shape of a dragonscale.',3,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','Personal','One suit of magic armor','1 hour/level (D); see text',null,ARRAY['Conjuration']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-golden-dragonmail","name":"Golden Dragonmail","school":"Conjuration","subschool":"Creation","descriptors":[],"schoolLine":"Conjuration (Creation)","levels":{"sorcerer/wizard":3},"levelLine":"Sorcerer/wizard 3","components":"V, S, F","castingTime":"1 standard action","range":"Personal","duration":"1 hour/level (D); see text","targetLabel":"Effect","target":"One suit of magic armor","description":"You create a suit of shining golden full plate around your body. The armor is etched with a dragonscale pattern, an image of a gold dragon, or Torm’s holy symbol (your choice when you cast the spell). It is treated as +1 mithral full plate for all purposes (including arcane spell failure chance), and you are treated as proficient with this armor. Removing or destroying the armor dismisses the spell. This spell has no effect if you are already wearing armor. Torm the True is served by gold and silver dragons, and some of these dragons are the founders of ancient sorcerer bloodlines among the younger races. If you are a sorcerer, the armor also gives you resistance to fire 10. Focus: A gold coin and a piece of mithral in the shape of a dragonscale."}'::jsonb),
('dnd35.cov.spell.cov-holy-fire-shield','Holy Fire Shield','Holy Fire Shield','This spell functions like fire shield, except half the damage from the spell is fire (or cold) and the remainder is divine energy, similar to a flame strike spell. If you create a warm shield, the flames are a beautiful golden-red. If you create a chill shield, the flames are a soothing blue-white. Sacrifice Component: 1d3 points of Strength damage.',4,false,false,ARRAY['sanctified']::text[],null,null,null,null,null,ARRAY['Evocation','Cold or Fire','Good']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-holy-fire-shield","name":"Holy Fire Shield","school":"Evocation","subschool":null,"descriptors":["Cold or Fire","Good"],"schoolLine":"Evocation [Cold or Fire; Good]","levels":{"sanctified":4},"levelLine":"Sanctified 4","components":"V, S, sacrifice","sacrificeComponent":"1d3 points of Strength damage.","description":"This spell functions like fire shield, except half the damage from the spell is fire (or cold) and the remainder is divine energy, similar to a flame strike spell. If you create a warm shield, the flames are a beautiful golden-red. If you create a chill shield, the flames are a soothing blue-white. Sacrifice Component: 1d3 points of Strength damage."}'::jsonb),
('dnd35.cov.spell.cov-horrible-taste','Horrible Taste','Horrible Taste','Drawing upon the talents of some creatures of the insect world, you change your flesh to make it unpalatable to other creatures. Any creature that hits you with a bite attack becomes nauseated until the end of your next turn unless it succeeds on a Fortitude save. Creatures immune to poison are unaffected by this spell.',1,false,false,ARRAY['druid','initiate-of-the-holy-realm','ranger']::text[],'1 immediate action','Personal','You','1 turn/level',null,ARRAY['Transmutation']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-horrible-taste","name":"Horrible Taste","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"druid":1,"initiate-of-the-holy-realm":1,"ranger":1},"levelLine":"Druid 1, initiate of the Holy Realm 1, ranger 1","components":"V, S","castingTime":"1 immediate action","range":"Personal","duration":"1 turn/level","targetLabel":"Target","target":"You","description":"Drawing upon the talents of some creatures of the insect world, you change your flesh to make it unpalatable to other creatures. Any creature that hits you with a bite attack becomes nauseated until the end of your next turn unless it succeeds on a Fortitude save. Creatures immune to poison are unaffected by this spell."}'::jsonb),
('dnd35.cov.spell.cov-invisibility-swift','Invisibility, Swift','Invisibility, Swift','This spell functions like invisibility except as noted above.',1,false,false,ARRAY['assassin','bard','initiate-of-baravar-cloakshadow']::text[],'1 swift action','Personal','You','1 round',null,ARRAY['Illusion']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-invisibility-swift","name":"Invisibility, Swift","school":"Illusion","subschool":"Glamer","descriptors":[],"schoolLine":"Illusion (Glamer)","levels":{"assassin":2,"bard":2,"initiate-of-baravar-cloakshadow":1},"levelLine":"Assassin 2, bard 2, initiate of Baravar Cloakshadow 1","components":"V","castingTime":"1 swift action","range":"Personal","duration":"1 round","targetLabel":"Target","target":"You","description":"This spell functions like invisibility except as noted above."}'::jsonb),
('dnd35.cov.spell.cov-lionheart','Lionheart','Lionheart','This spell originated in Nobanion’s faith. It functions like remove fear except as noted above.',2,false,false,ARRAY['initiate-of-the-holy-realm','initiate-of-nobanion']::text[],'1 immediate action',null,null,'1 minute',null,ARRAY['Abjuration']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-lionheart","name":"Lionheart","school":"Abjuration","subschool":null,"descriptors":[],"schoolLine":"Abjuration","levels":{"initiate-of-the-holy-realm":2,"initiate-of-nobanion":2},"levelLine":"Initiate of the Holy Realm 2, initiate of Nobanion 2","castingTime":"1 immediate action","duration":"1 minute","description":"This spell originated in Nobanion’s faith. It functions like remove fear except as noted above."}'::jsonb),
('dnd35.cov.spell.cov-love-bite','Love Bite','Love Bite','This spell originated in Sune’s faith. You determine at the time of casting what effect it takes. Fleeting Kiss: The target feels the sensation of a brief, tender kiss on a visible part of her body or on her mouth if her body is completely covered. This effect is often used as a signal. Love Bite: The target takes 1 point of damage. In either case, if you are holding the charge on a touch spell of 2nd level or lower when you cast love bite, this spell also delivers the touch spell to the target as if you had touched it directly (normal saving throws and spell resistance for the touch spell applies, if applicable). You must make a melee touch attack as normal with a +2 bonus. This form of the spell always attacks from your direction and cannot flank targets as a creature can. Using this spell to deliver a held charge is an exception to the normal rule that casting another spell while holding a charge dissipates the held spell.',1,false,false,ARRAY['initiate-of-the-holy-realm']::text[],'1 standard action','Medium (100 ft. + 10 ft./level)','One creature','Instantaneous; see text','None',ARRAY['Evocation','Force']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-love-bite","name":"Love Bite","school":"Evocation","subschool":null,"descriptors":["Force"],"schoolLine":"Evocation [Force]","levels":{"initiate-of-the-holy-realm":1},"levelLine":"Initiate of the Holy Realm 1","components":"V, S","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./level)","duration":"Instantaneous; see text","savingThrow":"None","spellResistance":"Yes","targetLabel":"Target","target":"One creature","description":"This spell originated in Sune’s faith. You determine at the time of casting what effect it takes. Fleeting Kiss: The target feels the sensation of a brief, tender kiss on a visible part of her body or on her mouth if her body is completely covered. This effect is often used as a signal. Love Bite: The target takes 1 point of damage. In either case, if you are holding the charge on a touch spell of 2nd level or lower when you cast love bite, this spell also delivers the touch spell to the target as if you had touched it directly (normal saving throws and spell resistance for the touch spell applies, if applicable). You must make a melee touch attack as normal with a +2 bonus. This form of the spell always attacks from your direction and cannot flank targets as a creature can. Using this spell to deliver a held charge is an exception to the normal rule that casting another spell while holding a charge dissipates the held spell."}'::jsonb),
('dnd35.cov.spell.cov-portal-well','Portal Well','Portal Well','When you step into a portal affected by this spell, you can wait for a short time within an extradimensional space between the portal’s entrance and exit. This spell only works on a portal you are able to activate; for example, if you are an elf and the target portal doesn’t work for elves, you can’t use this spell on the portal. The extradimensional space created by this spell is similar to that created by a rope trick spell but can only hold you and your gear (up to your maximum heavy load). When the spell ends, you exit the portal at either your point of entry or the portal’s destination. While within this extradimensional space, you can see the origin and destination locations, though the images are blurry (much like viewing the Material Plane from the Ethereal Plane). Dispel magic or gate seal traps you within the extradimensional space for as long as the portal is negated or sealed (as would surrounding both ends with a dead magic area). Mordenkainen’s disjunction or some other effect that destroys a portal outright forcibly ejects you from one random end of the portal and deals 5d6 points of damage to you. This spell originated in Shaundakul’s church and is hard to find elsewhere. Arcane Material Component: A silver wire tied in a knot.',2,false,false,ARRAY['bard','cleric','druid','sorcerer/wizard']::text[],'1 standard action','Touch','Active portal touched','1 round/level (D)','None',ARRAY['Transmutation']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-portal-well","name":"Portal Well","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"bard":2,"cleric":2,"druid":2,"sorcerer/wizard":2},"levelLine":"Bard 2, cleric 2, druid 2, sorcerer/wizard 2","components":"V, S, M","castingTime":"1 standard action","range":"Touch","duration":"1 round/level (D)","savingThrow":"None","spellResistance":"No","targetLabel":"Target","target":"Active portal touched","description":"When you step into a portal affected by this spell, you can wait for a short time within an extradimensional space between the portal’s entrance and exit. This spell only works on a portal you are able to activate; for example, if you are an elf and the target portal doesn’t work for elves, you can’t use this spell on the portal. The extradimensional space created by this spell is similar to that created by a rope trick spell but can only hold you and your gear (up to your maximum heavy load). When the spell ends, you exit the portal at either your point of entry or the portal’s destination. While within this extradimensional space, you can see the origin and destination locations, though the images are blurry (much like viewing the Material Plane from the Ethereal Plane). Dispel magic or gate seal traps you within the extradimensional space for as long as the portal is negated or sealed (as would surrounding both ends with a dead magic area). Mordenkainen’s disjunction or some other effect that destroys a portal outright forcibly ejects you from one random end of the portal and deals 5d6 points of damage to you. This spell originated in Shaundakul’s church and is hard to find elsewhere. Arcane Material Component: A silver wire tied in a knot."}'::jsonb),
('dnd35.cov.spell.cov-rend-shadow-weave','Rend Shadow Weave','Rend Shadow Weave','You damage the Shadow Weave, creating an area of dead magic that only affects the Shadow Weave rather than the Weave. While you have this spell prepared, you get a +2 competence bonus on caster level checks to dispel Shadow Weave effects. Material Component: A moonstone worth at least 50 gp.',3,false,false,ARRAY['cleric','sorcerer/wizard']::text[],'1 minute','Close (25 ft. plus 5 ft./2 levels)','One 10-ft.-cube area of the Shadow Weave','Instantaneous','None',ARRAY['Abjuration']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-rend-shadow-weave","name":"Rend Shadow Weave","school":"Abjuration","subschool":null,"descriptors":[],"schoolLine":"Abjuration","levels":{"cleric":3,"sorcerer/wizard":3},"levelLine":"Cleric 3, sorcerer/wizard 3","components":"V, S, M","castingTime":"1 minute","range":"Close (25 ft. plus 5 ft./2 levels)","duration":"Instantaneous","savingThrow":"None","spellResistance":"No","targetLabel":"Effect","target":"One 10-ft.-cube area of the Shadow Weave","description":"You damage the Shadow Weave, creating an area of dead magic that only affects the Shadow Weave rather than the Weave. While you have this spell prepared, you get a +2 competence bonus on caster level checks to dispel Shadow Weave effects. Material Component: A moonstone worth at least 50 gp."}'::jsonb),
('dnd35.cov.spell.cov-runic-marker','Runic Marker','Runic Marker','You create a slender stone pillar 2 feet in diameter and 6 feet tall. It can be square, cylindrical, hexagonal, natural-looking, or any similar shape. It must be solid and complete (without hollow spaces or secret compartments). When you create the runic marker, you can also have a message of up to twenty-five words inscribed upon it. The runic marker also bears a glyph of warding (blast glyph only). In addition to the normal trigger conditions available for a glyph of warding, you can set it to activate if the pillar ever takes damage from a magical effect. When the glyph of warding effect activates, the runic marker is destroyed, leaving nothing behind. An elf wizard protects himself with silver dragonmail Material Component: One vial of holy water.',4,false,false,ARRAY['cleric']::text[],'10 minutes','Close (25 ft. + 5 ft./2 levels)','One stone pillar','Permanent','See text',ARRAY['Conjuration','Earth']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-runic-marker","name":"Runic Marker","school":"Conjuration","subschool":"Creation","descriptors":["Earth"],"schoolLine":"Conjuration (Creation) [Earth]","levels":{"cleric":4},"levelLine":"Cleric 4","components":"V, S, M","castingTime":"10 minutes","range":"Close (25 ft. + 5 ft./2 levels)","duration":"Permanent","savingThrow":"See text","spellResistance":"No","targetLabel":"Effect","target":"One stone pillar","description":"You create a slender stone pillar 2 feet in diameter and 6 feet tall. It can be square, cylindrical, hexagonal, natural-looking, or any similar shape. It must be solid and complete (without hollow spaces or secret compartments). When you create the runic marker, you can also have a message of up to twenty-five words inscribed upon it. The runic marker also bears a glyph of warding (blast glyph only). In addition to the normal trigger conditions available for a glyph of warding, you can set it to activate if the pillar ever takes damage from a magical effect. When the glyph of warding effect activates, the runic marker is destroyed, leaving nothing behind. An elf wizard protects himself with silver dragonmail Material Component: One vial of holy water."}'::jsonb),
('dnd35.cov.spell.cov-shard-blessing-aura','Shard Blessing Aura','Shard Blessing Aura','This spell creates an aura of shimmering blue-white light similar to moonlight that fills your space and moves with you. The aura sheds light equal to a candle. This aura functions like a lesser globe of invulnerability. If you are a sorcerer and Selûne is your patron, the aura also grants you the benefit of protection from evil. The spell is named for the Shards, planetar servants of Selûne drawn from the ranks of her greatest priestesses. Because some shards return to Faerûn to visit their mortal lovers, supernatural bloodlines (usually aasimar, but not always) with ties to Selûne exist in some parts of the world. Material Component: A moonstone or other polished white stone.',5,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','Personal','You','1 round/level',null,ARRAY['Abjuration']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-shard-blessing-aura","name":"Shard Blessing Aura","school":"Abjuration","subschool":null,"descriptors":[],"schoolLine":"Abjuration","levels":{"sorcerer/wizard":5},"levelLine":"Sorcerer/wizard 5","components":"V, S","castingTime":"1 standard action","range":"Personal","duration":"1 round/level","targetLabel":"Target","target":"You","description":"This spell creates an aura of shimmering blue-white light similar to moonlight that fills your space and moves with you. The aura sheds light equal to a candle. This aura functions like a lesser globe of invulnerability. If you are a sorcerer and Selûne is your patron, the aura also grants you the benefit of protection from evil. The spell is named for the Shards, planetar servants of Selûne drawn from the ranks of her greatest priestesses. Because some shards return to Faerûn to visit their mortal lovers, supernatural bloodlines (usually aasimar, but not always) with ties to Selûne exist in some parts of the world. Material Component: A moonstone or other polished white stone."}'::jsonb),
('dnd35.cov.spell.cov-silver-dragonmail','Silver Dragonmail','Silver Dragonmail','You create a shining silver breastplate around your body. The armor is etched with a dragonscale pattern, an image of a silver dragon, or Torm’s holy symbol (your choice when you cast the spell). It is treated as +1 mithral breastplate for all purposes (including arcane spell failure chance), and you are treated as proficient with this armor. Removing or destroying the armor dismisses the spell. This spell has no effect if you are already wearing armor. Torm the True is served by gold and silver dragons, and some of these dragons are the founders of ancient sorcerer bloodlines among the younger races. If you are a sorcerer, the armor also gives you resistance to cold 5. Focus: A silver piece and a piece of mithral in the shape of a dragonscale.',2,false,false,ARRAY['sorcerer/wizard']::text[],'1 standard action','Personal','One suit of magic armor','1 hour/level (D); see text',null,ARRAY['Conjuration']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-silver-dragonmail","name":"Silver Dragonmail","school":"Conjuration","subschool":"Creation","descriptors":[],"schoolLine":"Conjuration (Creation)","levels":{"sorcerer/wizard":2},"levelLine":"Sorcerer/wizard 2","components":"V, S, F","castingTime":"1 standard action","range":"Personal","duration":"1 hour/level (D); see text","targetLabel":"Effect","target":"One suit of magic armor","description":"You create a shining silver breastplate around your body. The armor is etched with a dragonscale pattern, an image of a silver dragon, or Torm’s holy symbol (your choice when you cast the spell). It is treated as +1 mithral breastplate for all purposes (including arcane spell failure chance), and you are treated as proficient with this armor. Removing or destroying the armor dismisses the spell. This spell has no effect if you are already wearing armor. Torm the True is served by gold and silver dragons, and some of these dragons are the founders of ancient sorcerer bloodlines among the younger races. If you are a sorcerer, the armor also gives you resistance to cold 5. Focus: A silver piece and a piece of mithral in the shape of a dragonscale."}'::jsonb),
('dnd35.cov.spell.cov-skin-of-the-steel-dragon','Skin of the Steel Dragon','Skin of the Steel Dragon','Cas ting Time: 1 immediate action Range: Personal Target: You Duration: 1 round/3 levels This spell grants you spell resistance equal to 10 + your caster level. If you are a sorcerer, this spell also grants you a +5 resistance bonus on saving throws against poison. Some of Mystra’s servants are steel dragons, shapeshifting creatures who love living among humanoids. Some sorcerers claim their magic comes from a long-ago dragon ancestor, one of the first steel dragons to serve Mystra in Faerûn. Material Component: A piece of steel in the shape of a seven-pointed star or a steel holy symbol of Mystra’s faith.',5,false,false,ARRAY['sorcerer/wizard']::text[],null,null,null,null,null,ARRAY['Abjuration']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-skin-of-the-steel-dragon","name":"Skin of the Steel Dragon","school":"Abjuration","subschool":null,"descriptors":[],"schoolLine":"Abjuration","levels":{"sorcerer/wizard":5},"levelLine":"Sorcerer/wizard 5","components":"V, S, M","description":"Cas ting Time: 1 immediate action Range: Personal Target: You Duration: 1 round/3 levels This spell grants you spell resistance equal to 10 + your caster level. If you are a sorcerer, this spell also grants you a +5 resistance bonus on saving throws against poison. Some of Mystra’s servants are steel dragons, shapeshifting creatures who love living among humanoids. Some sorcerers claim their magic comes from a long-ago dragon ancestor, one of the first steel dragons to serve Mystra in Faerûn. Material Component: A piece of steel in the shape of a seven-pointed star or a steel holy symbol of Mystra’s faith."}'::jsonb),
('dnd35.cov.spell.cov-spellsong','Spellsong','Spellsong','When you cast this spell, you immediately prepare one spell of 4th level or lower in this spell’s slot. The spell must be a spell you could normally prepare in that slot (for example, you could not prepare a wizard spell or a domain spell). The spell works like any spell prepared in the normal manner, including requiring the normal components. Like a bard spell, casting spellsong always requires a verbal component, and you cannot use Silent Spell or similar effects to cast the spell without a verbal component.',6,false,false,ARRAY['initiate-of-eilistraee']::text[],'1 round','Personal','You','Instantaneous',null,ARRAY['Transmutation']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-spellsong","name":"Spellsong","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"initiate-of-eilistraee":6},"levelLine":"Initiate of Eilistraee 6","components":"V, S, DF","castingTime":"1 round","range":"Personal","duration":"Instantaneous","targetLabel":"Target","target":"You","description":"When you cast this spell, you immediately prepare one spell of 4th level or lower in this spell’s slot. The spell must be a spell you could normally prepare in that slot (for example, you could not prepare a wizard spell or a domain spell). The spell works like any spell prepared in the normal manner, including requiring the normal components. Like a bard spell, casting spellsong always requires a verbal component, and you cannot use Silent Spell or similar effects to cast the spell without a verbal component."}'::jsonb),
('dnd35.cov.spell.cov-spellsong-lesser','Spellsong, Lesser','Spellsong, Lesser','This spell functions like spellsong, except you can use it only to prepare one spell of 1st level or lower in this spell’s slot.',3,false,false,ARRAY['initiate-of-eilistraee']::text[],null,null,null,null,null,ARRAY['Transmutation']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-spellsong-lesser","name":"Spellsong, Lesser","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"initiate-of-eilistraee":3},"levelLine":"Initiate of Eilistraee 3","description":"This spell functions like spellsong, except you can use it only to prepare one spell of 1st level or lower in this spell’s slot."}'::jsonb),
('dnd35.cov.spell.cov-spiderbind','Spiderbind','Spiderbind','An affected creature moves and attacks at a drastically reduced rate, as the slow spell. It can only take a single move action or standard action each turn, but not both (nor can it take full-round actions). Additionally, it takes a –1 penalty on attack rolls, AC, and Reflex saves. A slowed creature moves at half its normal speed (round down to the next 5-foot increment), which affects the creature’s jumping distance as normal for decreased speed. In addition, any attack by the creature that would normally include poison (such as a spider’s bite) does not do so, but all other effects associated with that attack apply. For example, if an aranea subject to spiderbind cast a touch spell and then bit a creature, the attack would deal normal bite damage and trigger the touch spell, but the bite would not inject poison. While you have this spell prepared, you get a +2 circumstance bonus on saving throws against poison. Clerics of Eilistraee created this spell to help battle the many spiderlike creatures that serve Lolth. Araneas, bebiliths, chitinesMag, choldrithsMag, driders, ettercaps, myrlocharsMag, phase spiders, retrievers, and yochlols are sufficiently spiderlike to be affected by this spell. For a more complete list of creatures that qualify as spiderkind, see page 30 of Underdark.',3,false,false,ARRAY['cleric']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','One spider or spiderlike creature/level, no two of which can be more than 30 ft. apart','1 round/level','Fortitude negates',ARRAY['Transmutation']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-spiderbind","name":"Spiderbind","school":"Transmutation","subschool":null,"descriptors":[],"schoolLine":"Transmutation","levels":{"cleric":3},"levelLine":"Cleric 3","components":"V, S, M","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"1 round/level","savingThrow":"Fortitude negates","spellResistance":"Yes","targetLabel":"Targets","target":"One spider or spiderlike creature/level, no two of which can be more than 30 ft. apart","description":"An affected creature moves and attacks at a drastically reduced rate, as the slow spell. It can only take a single move action or standard action each turn, but not both (nor can it take full-round actions). Additionally, it takes a –1 penalty on attack rolls, AC, and Reflex saves. A slowed creature moves at half its normal speed (round down to the next 5-foot increment), which affects the creature’s jumping distance as normal for decreased speed. In addition, any attack by the creature that would normally include poison (such as a spider’s bite) does not do so, but all other effects associated with that attack apply. For example, if an aranea subject to spiderbind cast a touch spell and then bit a creature, the attack would deal normal bite damage and trigger the touch spell, but the bite would not inject poison. While you have this spell prepared, you get a +2 circumstance bonus on saving throws against poison. Clerics of Eilistraee created this spell to help battle the many spiderlike creatures that serve Lolth. Araneas, bebiliths, chitinesMag, choldrithsMag, driders, ettercaps, myrlocharsMag, phase spiders, retrievers, and yochlols are sufficiently spiderlike to be affected by this spell. For a more complete list of creatures that qualify as spiderkind, see page 30 of Underdark."}'::jsonb),
('dnd35.cov.spell.cov-stars-of-arvandor','Stars of Arvandor','Stars of Arvandor','You create one twinkling star per level (maximum ten stars). These minute starbursts orbit your head like ioun stones. As a swift action, you can launch one star at a target you designate within range. Alternatively, as a standard action, you can launch up to three stars at one or more targets within range. You can only launch stars once per round. You must make a ranged touch attack for each star. Against non-evil targets, each star deals 1d8 points of nonlethal damage; evil targets take 1d8 points of lethal damage instead.',3,false,false,ARRAY['cleric','druid','ranger','sorcerer/wizard']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','See text','1 minute/level (D)','None',ARRAY['Evocation','Force','Good']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-stars-of-arvandor","name":"Stars of Arvandor","school":"Evocation","subschool":null,"descriptors":["Force","Good"],"schoolLine":"Evocation [Force, Good]","levels":{"cleric":4,"druid":4,"ranger":4,"sorcerer/wizard":3},"levelLine":"Cleric 4, druid 4, ranger 4, sorcerer/wizard 3","components":"V, S","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"1 minute/level (D)","savingThrow":"None","spellResistance":"Yes","targetLabel":"Target","target":"See text","description":"You create one twinkling star per level (maximum ten stars). These minute starbursts orbit your head like ioun stones. As a swift action, you can launch one star at a target you designate within range. Alternatively, as a standard action, you can launch up to three stars at one or more targets within range. You can only launch stars once per round. You must make a ranged touch attack for each star. Against non-evil targets, each star deals 1d8 points of nonlethal damage; evil targets take 1d8 points of lethal damage instead."}'::jsonb),
('dnd35.cov.spell.cov-stars-of-mystra','Stars of Mystra','Stars of Mystra','You create one twinkling star per three levels (maximum five stars). These minute starbursts orbit your head like ioun stones. Beginning on the turn you cast the spell, you can launch one star as a swift action at a target you designate within range. You must make a ranged touch attack for each star. Each time an evil creature is hit by a star, it must make a saving throw or lose a prepared spell or spell slot as if the creature had used it to cast a spell. The level of the lost spell is 4th (or the highest spell level lower than 4th in which the caster has at least one remaining prepared spell or spell slot). If the target prepares spells, determine the specific lost spell randomly. If the creature has spellcasting ability from more than one class (such as a 4th-level cleric/4th-level ranger), determine the affected spellcasting class randomly. The stars have no effect on nonspellcasters.',4,false,false,ARRAY['cleric']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','See text','1 minute/level (D)','Will negates',ARRAY['Evocation','Force','Good']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-stars-of-mystra","name":"Stars of Mystra","school":"Evocation","subschool":null,"descriptors":["Force","Good"],"schoolLine":"Evocation [Force, Good]","levels":{"cleric":4},"levelLine":"Cleric 4","components":"V, S","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"1 minute/level (D)","savingThrow":"Will negates","spellResistance":"Yes","targetLabel":"Target","target":"See text","description":"You create one twinkling star per three levels (maximum five stars). These minute starbursts orbit your head like ioun stones. Beginning on the turn you cast the spell, you can launch one star as a swift action at a target you designate within range. You must make a ranged touch attack for each star. Each time an evil creature is hit by a star, it must make a saving throw or lose a prepared spell or spell slot as if the creature had used it to cast a spell. The level of the lost spell is 4th (or the highest spell level lower than 4th in which the caster has at least one remaining prepared spell or spell slot). If the target prepares spells, determine the specific lost spell randomly. If the creature has spellcasting ability from more than one class (such as a 4th-level cleric/4th-level ranger), determine the affected spellcasting class randomly. The stars have no effect on nonspellcasters."}'::jsonb),
('dnd35.cov.spell.cov-stars-of-sel-ne','Stars of Selûne','Stars of Selûne','This spell functions like stars of Mystra, except as noted above and as follows. Each star deals 1d8 points of force damage and 1d8 points of cold damage to the target.',4,false,false,ARRAY['cleric']::text[],null,null,null,null,'None',ARRAY['Evocation','Cold','Force']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-stars-of-sel-ne","name":"Stars of Selûne","school":"Evocation","subschool":null,"descriptors":["Cold","Force"],"schoolLine":"Evocation [Cold, Force]","levels":{"cleric":4},"levelLine":"Cleric 4","savingThrow":"None","description":"This spell functions like stars of Mystra, except as noted above and as follows. Each star deals 1d8 points of force damage and 1d8 points of cold damage to the target."}'::jsonb),
('dnd35.cov.spell.cov-stormvoice','Stormvoice','Stormvoice','Your voice is amplified greatly. Subtract 10 from the DC of Listen checks made to hear you talking (even whispering). You also gain a +2 competence bonus on Intimidate checks. While this spell is active, you can use a swift action to create a 15-foot-long cone-shaped burst of intense sound with a shout. Every creature in the area takes 1d8 points of sonic damage and must succeed on a Fortitude save to avoid being stunned for 1 round. Doing this discharges the spell. Creatures that cannot hear are not stunned but are still damaged.',2,false,false,ARRAY['initiate-of-horus-re']::text[],'1 standard action','Personal','You','1 minute/level (D) or until discharged',null,ARRAY['Evocation','Sonic']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-stormvoice","name":"Stormvoice","school":"Evocation","subschool":null,"descriptors":["Sonic"],"schoolLine":"Evocation [Sonic]","levels":{"initiate-of-horus-re":2},"levelLine":"Initiate of Horus-Re 2","components":"V, S, DF","castingTime":"1 standard action","range":"Personal","duration":"1 minute/level (D) or until discharged","targetLabel":"Target","target":"You","description":"Your voice is amplified greatly. Subtract 10 from the DC of Listen checks made to hear you talking (even whispering). You also gain a +2 competence bonus on Intimidate checks. While this spell is active, you can use a swift action to create a 15-foot-long cone-shaped burst of intense sound with a shout. Every creature in the area takes 1d8 points of sonic damage and must succeed on a Fortitude save to avoid being stunned for 1 round. Doing this discharges the spell. Creatures that cannot hear are not stunned but are still damaged."}'::jsonb),
('dnd35.cov.spell.cov-thunderstroke','Thunderstroke','Thunderstroke','You call down a bolt of electricity, which unerringly strikes the target and deals 1d6 points of electricity damage per caster level (maximum 5d6). A small rumble of thunder accompanies the bolt, which is as loud as a battle (Listen DC –10 to hear it).',2,false,false,ARRAY['initiate-of-anhur']::text[],'1 standard action','Medium (100 ft. + 10 ft./level)','One creature or object','Instantaneous','Reflex half',ARRAY['Evocation','Electricity']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-thunderstroke","name":"Thunderstroke","school":"Evocation","subschool":null,"descriptors":["Electricity"],"schoolLine":"Evocation [Electricity]","levels":{"initiate-of-anhur":2},"levelLine":"Initiate of Anhur 2","components":"V, S, DF","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./level)","duration":"Instantaneous","savingThrow":"Reflex half","spellResistance":"Yes","targetLabel":"Target","target":"One creature or object","description":"You call down a bolt of electricity, which unerringly strikes the target and deals 1d6 points of electricity damage per caster level (maximum 5d6). A small rumble of thunder accompanies the bolt, which is as loud as a battle (Listen DC –10 to hear it)."}'::jsonb),
('dnd35.cov.spell.cov-vision-of-punishment','Vision of Punishment','Vision of Punishment','You give the target a vision of what awaits it in the afterlife. Since most evil creatures go to an evil plane where they take the form of a lowly and much-tortured petitioner (barring special arrangements with evil gods or fiends that grant them higher status in the afterlife), this is usually a gut-wrenching vision. The target is nauseated; if it makes its saving throw, it is instead sickened (see page 301 of the Dungeon Master’s Guide for definitions of these conditions. Sacrifice Component: 1d2 points of Strength damage.',1,false,false,ARRAY['sanctified']::text[],'1 swift action','Close (25 ft. + 5 ft./2 levels)','One evil living creature','1 round/3 levels','Will partial',ARRAY['Divination','Mind-Affecting']::text[],'v35-cov','D&D 3.5 — Champions of Valor',52,'dnd35','{"id":"cov-vision-of-punishment","name":"Vision of Punishment","school":"Divination","subschool":null,"descriptors":["Mind-Affecting"],"schoolLine":"Divination [Mind-Affecting]","levels":{"sanctified":1},"levelLine":"Sanctified 1","components":"V, DF, sacrifice","castingTime":"1 swift action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"1 round/3 levels","savingThrow":"Will partial","spellResistance":"Yes","targetLabel":"Target","target":"One evil living creature","sacrificeComponent":"1d2 points of Strength damage.","description":"You give the target a vision of what awaits it in the afterlife. Since most evil creatures go to an evil plane where they take the form of a lowly and much-tortured petitioner (barring special arrangements with evil gods or fiends that grant them higher status in the afterlife), this is usually a gut-wrenching vision. The target is nauseated; if it makes its saving throw, it is instead sickened (see page 301 of the Dungeon Master’s Guide for definitions of these conditions. Sacrifice Component: 1d2 points of Strength damage."}'::jsonb)
insert into public.catalog_items (id,name_pt,name_en,description_pt,item_category,level,price_gp,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.cov.magic-item.cov-item-albruin','Albruin','Albruin','Somewhat broader in blade than a classic longsword, Albruin gleams with the sheen of its silver coat-ing. The blade is otherwise unremarkable, making its name known to would-be bearers only through telepathy.','magic-item',0,null,ARRAY[]::text[],'v35-cov','D&D 3.5 — Champions of Valor',60,'dnd35','{"id":"cov-item-albruin","name":"Albruin","intro":"Albruin is a powerful magic sword coated in silver, which makes it effective against undead and lycanthropes. It is intelligent, with a mischievous personality that may drag you on unplanned adventures. You are but the latest in a long and varied line of wielders who have ranged from Cormyr to Impiltur to the Moonsea, with many adventures along the way.","history":"Albruin is believed to be the creation of the long-dead smith Surdee, who was famous in his day for the craftsmanship of his work that came out of the forges of ice-bound Glister, where he worked ore fresh from the mines above the city on the edge of the glacier. The blade itself evades questions about its origins: It has no markings or definite touches of workmanship that identify Albruin as the work of anyone in particular.\n\nAlbruin was held for decades in the royal house of Cormyr, kept as a family treasure but seldom (due to its alignment) borne by the kings of that land. It was stolen from the palace at Suzail in the Year of Daystars (1268 DR) by the thief Nypan (“Nipe”), a halfling who was soon arrested in Wheloon by soldiers of Cormyr and slain when he attempted to escape. Nipe did not have the blade when seized, and he did not reveal its whereabouts. It was rumored among the thieves of that place that Nypan sold it to a “gray trader” (fence) named Blusken Shult, who delivered the sword to a waiting buyer. The blade’s whereabouts were uncertain until the Year of the Wandering Waves (1292 DR), when a lady of high birth in Selgaunt, one Shamur Karn (later Uskreven), found the blade left behind in her bedchamber by a visitor fleeing the city guard. He never returned, and Shamur sold it in the Year of the Talking Skull (1293 DR) before she disappeared. The sword was bought by a recruiter visiting the city of Selgaunt on matters of trade (gold for mercenaries) on behalf of Prince Thaum of Telflamm. With his army in tow, Thaum sailed across the Easting Reach and sacked the city of Sarshel with complete surprise. During the fighting, Thaum came to covet the blade Albruin, and so the prince had its bearer murdered in an ambush by his own men so that Thaum could seize it for his own. After Thaum’s death, Albruin was acquired by Adjuz, one of Thaum’s warriors, who took it back to the Dalelands. He perished at the hands of brigands along the Moonsea Ride, but not before he had sought out the sage Elminster of Shadowdale to ascertain its powers. After the death of Adjuz, the trail of the sword is hidden for some eight winters, but it is known to have been in the hands of the mercenary general Malakar on this visit to Zhentil Keep in the spring of the Year of the Broken Helm (1302 DR), and was identified by the sage Murail of Sarbreen when a mercenary warrior sought him out to learn the blade’s properties in that city in the Year of the Catacombs (1308 DR). Albruin has not been seen since, but Elminster is known to have observed that its plain appearance and ability to control many of its bearers has certainly contributed to this anonymity.","description":"Somewhat broader in blade than a classic longsword, Albruin gleams with the sheen of its silver coat-ing. The blade is otherwise unremarkable, making its name known to would-be bearers only through telepathy.","activation":"Albruin is a +3 silvered longsword. It does not radiate light.","effect":"+3 silvered longsword; AL CN; Int 17, Wis 10, Cha 17; Speech (Common, Elven, Undercommon, thieves’ cant); telepathy; 120 ft. darkvision and hearing; Ego score 16. It sheds an eerie blue radiance equivalent to a light spell (bright illumination in a 20-foot radius, shadowy illumination in a 40-foot radius) when drawn.","lesserPowers":"Cure moderate wounds 3/day, neutralize poison 1/day (wielder only), read magic at will.","greaterPower":"Invisibility purge (30 ft. range) 3/day.","personality":"Albruin has the heart of a scamp, eternally curious yet easily distracted and given to making mischief. Commissioned by a Dambrathan half-drow prince who fled the reach of Queen Ausitil for the Great Grey Land of Thar and sought a boon companion, the blade’s intended recipient never received the sword because Albruin induced a smith at Surdee’s forge to steal it away ere the prince arrived to claim his weapon. Albruin has little interest in notoriety and seeks only wielders who take it to a steady stream of interesting locales. Although not heroic by nature, the sword enjoys the immediate accolades of heroism, and is thus much more likely to prefer a good-aligned wielder to an evil one. Albruin is most likely to exert the strength of its personality when a mysterious ruin is in the offing, yet its wielders seem inclined to seek adventure elsewhere.","auraCasterLevel":"Moderate evocation. CL 9th.","construction":"Craft Magic Arms and Armor, cure moderate wounds, invisibility purge, neutralize poison, read magic, 25,030 gp, 1,970 XP, 50 days.","weight":"4 lb.","price":"49,565 gp."}'::jsonb),
('dnd35.cov.magic-item.cov-item-chalsembyrs-heart','Chalsembyr’s Heart','Chalsembyr’s Heart','Chalsembyr’s Heart is a greatsword masterfully crafted of cold iron with a lion motif throughout. The iron itself has been tinted in gold, and the point where the cross guard and the blade meet bears a raised head of a lion face-on on one side and in profile on the other. The cross guards themselves appear as lion’s paws, and the base of the hilt—which is wrapped in white leather bound in gold wire—holds one large brilliant-cut white diamond surrounded by five fiery yellow rectangular corundums. The words “Seek the High Seat Always” in Celestial are etched along both sides of the blade.','magic-item',0,null,ARRAY[]::text[],'v35-cov','D&D 3.5 — Champions of Valor',60,'dnd35','{"id":"cov-item-chalsembyrs-heart","name":"Chalsembyr’s Heart","intro":"This beautiful greatsword is a unique and intelligent weapon with ties to the temple of Torm. Sadly, it was lost, and many paladins of The True seek it throughout Faerûn.","lore":"Many among those who follow Torm have long sought to know the location of the Loyal Fury’s ancient mortal kingdom of Chalsembyr. Some of his most devout servants have dedicated their lives to finding it, wandering during most of their lifetimes in search of clues. One such intrepid explorer was Bertold the Seeker, a paladin of extraordinary dedication and selflessness. (Knowledge [religion] DC 10) Legend says that Bertold carried with him a greatsword fashioned by clerics of the House of the Hand in Procampur. This weapon, known as Chalsembyr’s Heart, was designed to assist him in his quest to find Chalsembyr. As it happened, Bertold was ambushed and killed by ogres while crossing the Toadsquat Mountains on the southern edge of the Eastern Shaar. (Knowledge [religion] DC 15) There was a quality the clerics had imbued in the weapon that Bertold did not know about. Instead of being drawn to the House of the Triad upon his death as he had expected, Bertold’s soul was drawn into the sword, preserved there so that his knowledge of Chalsembyr would not be lost. It remained there, waiting for another to come along and claim it—and, by extension, Bertold’s knowledge. The legend suggests that should another paladin take Chalsembyr’s Heart as her own blade, she will upon her death be destined to take Bertold’s place in the sword, finally freeing Bertold himself to join his lord in the House of the Triad. Each successive paladin who dies in the service of Torm while wielding the greatsword will similarly serve as a guide in sword form for future seekers of Chalsembyr. (Knowledge [religion] DC 30)","description":"Chalsembyr’s Heart is a greatsword masterfully crafted of cold iron with a lion motif throughout. The iron itself has been tinted in gold, and the point where the cross guard and the blade meet bears a raised head of a lion face-on on one side and in profile on the other. The cross guards themselves appear as lion’s paws, and the base of the hilt—which is wrapped in white leather bound in gold wire—holds one large brilliant-cut white diamond surrounded by five fiery yellow rectangular corundums. The words “Seek the High Seat Always” in Celestial are etched along both sides of the blade.","prerequisite":"In the hands of others, Chalsembyr’s Heart is simply a +2 cold iron greatsword.","effect":"+5 holy cold iron greatsword; AL LG; Int 13, Wis 14, Cha 16; telepathy, 120 ft. vision and hearing, read languages; Ego score 24.","lesserPowers":"10 ranks in Decipher Script (total modifier +11) and 10 ranks in Knowledge (history Chalsembyr) (total modifier +11).","greaterPower":"Detect thoughts at will.","specialPurpose":"Find Chalsembyr.","dedicatedPower":"Sword can perform a benevolent form of soul bind on a paladin of Torm upon death.","auraCasterLevel":"Strong evocation [good]. CL 20th.","construction":"Craft Arms and Armor, miracle, 51,450 gp, 8,920 XP, 52 days.","weight":"8 lb.","price":"100,450 gp."}'::jsonb),
('dnd35.cov.magic-item.cov-item-dornavver','Dornavver','Dornavver','Dornavver is forged of some unknown alloy, and its blade is multihued. The long hilt is wrapped with silver wire and the crosspiece is also plated with this holy metal. The pommel is etched with the symbol of Ilmater, the Broken God.','magic-item',0,null,ARRAY[]::text[],'v35-cov','D&D 3.5 — Champions of Valor',60,'dnd35','{"id":"cov-item-dornavver","name":"Dornavver","intro":"Dornavver, also known as Demonbane, is a legendary scourge of fiends from the Lower Planes, borne by a succession of paladins to cleanse Faerûn of their taint. You carry a legendary weapon that makes even the most powerful demons quail.","history":"Named for the master swordsmith who forged it, Dornavver is only rarely called by its true name. Most sages and historians prefer the imagery that springs to mind when it is referred to as Demonbane, and many tales and fragments of lore surrounding the blade refer to it in this fashion. The sword was fashioned in the Year of the Wrath Sword (275 DR) in response to the proliferation of evil artifacts created during the reign of the Q ysar Shoon IV of the Shoon Imperium. Relics such as Kuraltaar “the Demonshield,” Jaralth “the Fiendspike,” and Morthinmar “the Sallet of Sorrow” convinced the clergy of Ilmater that the faith required more than just prayer to combat the spread of evil throughout the South.\n\nAs recorded in the book Relics of the Righteous by the Sage of the Just Gods, Thontoros the Learned, the Feast of the Moon in Uktar of 275 DR saw a great, holy gathering at the ancient stone circle known as Allyn’s Anvil, where the legendary Demonsbane shields had been consecrated by the Just God himself more than two centuries before. Present were Archsufferer Irmakul “Bloodthews” of Memnon, Revered Brother Filithan of Bormton (a now-ruined village north of present-day Trademeet), Exalted Servant Volshur the Crooked, and a host of other senior priests of the Crying God. On that night, their fervent prayers, interspersed with their cries of suffering, infused Dornavver with its mighty enchantments.\n\nThe sword was entrusted to the Holy Warriors of Suffering, a knightly order of paladins affiliated with the Church of Ilmater that at the time had its fortress at what is now known as Castle Dasaajk, east of the Purple Hills. It is known that over one hundred winters after the sword was entrusted to the Holy Warriors, one of their number took up the blade and traveled north, coming to the tower of Uldoon, “the Mage of Fangs.” The wizard Uldoon was a ruthless—some say insane—spellhurler who consorted with many denizens of the Lower Planes. He established the small realm of Torsil in the lands north of the Cloud Peaks and grew fond of summoning fiends of all types to send against rival holds that bordered his realm, as well as the elves of Askavar, who had their homes in nearby Glimmerwood (the present-day Wood of Sharp Teeth). The tale of how this unnamed paladin, wielding the mighty Dornavver, vanquished Torsil and the fiends therein is recounted in a ballad titled “Uldoon’s Doom,” a popular song still sung by bards of the Sword Coast today.\n\nAfter the fall of Torsil, the blade known as Demonbane was taken by its wielder west of the Heartlands and disappeared from recorded history for over a century. It is known that during the tragic procession of battles that preceded the fall of Myth Drannor, many Dalesmen and more than a few War Wizards of Cormyr took up arms to assist the elves and other races who called the City of Songs home. The court records of King Draxius the Neverdying of Cormyr recount how the ambitious Mindal Rowanmantle, a noble younger son, gathered a ragtag army of volunteers made up of Dalesfolk and warriors of Cormyr and led them to fight alongside the forces of Cormanthyr. The only known description of this campaign is found in the diary of the War Wizard Landraul Skatterhawk, which now rests in the Royal Cormyrean Archives in Suzail. Landraul wrote about a blade that fit the description of Dornavver as being in the possession of the paladin Sarshel Elethlim and wielded by him in the Battles of Snowsblood Trail and Standing Stone’s Blood during the Year of the Firedrake (713 DR).\n\nSarshel Elethlim went on to lead the Triad Crusade against the fiend army that overran and despoiled Impiltur more than a decade after the fall of Myth Drannor. Sarshel wielded Dornavver throughout the many battles of the Fiend Wars (729–732 DR) and used it to devastating effect when he shattered the Crown of Narfell in the Citadel of Conjurers, breaking the power of Orcus over the last demon army and sending it into headlong retreat. His bravery and leadership saw him crowned king of Impiltur, and Dornavver became one of the royal blades of the kingdom. After the death of Sarshel, Demonbane was borne, but seldom wielded, by monarchs of the realm, out of reverence for the man who had led the realm out of darkness. In the years that followed, the sword was employed in battle only twice. In 786 DR, Prince Nord and his brothers donned all the holy regalia of Impiltur, including the legendary Demonsbane shields, to banish the balor Ndulu and his demon host from their realm. In that storied battle, Nord wielded Dornavver and gained for himself eternal glory.\n\nThe only other time that Demonbane was wielded in battle prior to the fall of Old Impiltur in 926 DR was during the time of King Beldred. His reign is famous for “the Scouring,” a year-long campaign in the Year of the Empty Throne (850 DR) that saw the young king lead an army of holy knights deep into the depths of the Rawlinswood, slaying and driving forth pockets of demons that had survived the Fiend Wars. While this campaign averted an age-old threat to the kingdom, it unfortunately released a horde of harried demons on the tribes of Narfell to the north of Impiltur. The tribesmen sought their revenge on Impiltur in the Year of the Risen Sword (893 DR) when they united under the chieftain Galush and rode forth to invade the realm and claim, as the sage Ithyran described, the “warm lands of their ancestors.” Despite being defeated at the Battle of Twelvepikes on the banks of the Soleine River, the nomads managed to do great damage to the outlying eastern borders of the realm, but did little to weaken the realm proper. Their defeat and the death of their leader saw the nomad horsemen turn tail and flee back to the Nar steppes, closing another chapter in Impiltur’s “golden age.”\n\nAs with all the other blades of Imbrar’s Royal Guard that make up Soargar’s Legacy, Dornavver was safely kept by the Mage Royal Soargar in his tower in Lyrabar until the victory of Imphras the Great over the hobgoblin hordes in the Year of the Dawndance (1095 DR) and the reestablishment of the monarchy two years later. Most sages and historians of Impiltur believe that King Imbrar himself wielded Demonbane when he marched north from his lands in 1127 DR to quell the hobgoblin menace stirring once again in the Giantspire Mountains; others state that he gave the blade to his general and commander of the Royal Guard, Lord Osper Wellhaven. The only thing that the sages seem prepared to agree on is that the whereabouts and fate of Dornavver remain a mystery that is yet to be solved.","description":"Dornavver is forged of some unknown alloy, and its blade is multihued. The long hilt is wrapped with silver wire and the crosspiece is also plated with this holy metal. The pommel is etched with the symbol of Ilmater, the Broken God.","activation":"The sword is a +3 outsider bane bastard sword. Its bane special ability functions only against evil outsiders. It glows with a cold, blue light (equal to a light spell in effect) when brought within 60 feet of a demon.","effect":"The bearer of the blade is rendered immune to charm effects created by demons, and is granted a +3 bonus on all saves against spells, spell-like effects, and supernatural abilities employed by demons. Any demon struck by the blade must make a DC 20 Will save or be blocked from summoning others of its kind for the next hour. Finally, the bearer of Dornavver receives Improved Initiative as a bonus feat. The blade bestows one negative level on any evil creature that holds it. The negative level remains as long as the sword is in hand and disappears when it is no longer carried. This negative level never results in actual level loss, but it cannot be overcome in any way (including restoration spells) while the sword is held. Demonbane is legendary among demonkind, and can be readily recognized by any demon with a successful DC 10 Knowledge (the planes) or Intelligence check. The bearer receives a +2 circumstance bonus on Intimidate checks against demons that recognize the blade. The attitude of any demon seeing this blade immediately shifts to hostile (see page 72 of the Player’s Handbook) with respect to the wielder. Most demons will immediately communicate the sword’s location and ownership to their fellows once they learn of it.","auraCasterLevel":"Strong evocation. CL 11th.","construction":"Craft Magic Arms and Armor, Improved Initiative, banishment, detect evil, holy smite, searing light, summon monster I, creator must be good, 131,335 gp, 10,480 XP, 131 days.","weight":"6 lb.","price":"262,335 gp."}'::jsonb),
('dnd35.cov.magic-item.cov-item-dukar-hand-coral','Dukar Hand Coral','Dukar Hand Coral','This piece of coral is about the size and shape of a medallion, three inches across but barely thicker than a coin. It has a convoluted texture, almost like a maze, and has many colors—pink, pale blue, yellow, and green in seemingly random patterns.
